/* ================= SOUND ================= */
let AC=null;
function snd(type){
  if(!S.sound)return;
  try{if(!AC)AC=new (window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();
    const seq={tap:[[520,.04]],coin:[[880,.05],[1320,.08]],water:[[600,.05],[900,.08]],build:[[300,.06],[450,.06],[600,.1]],boom:[[90,.25]],shot:[[1200,.03]],win:[[523,.1],[659,.1],[784,.1],[1046,.3]],lose:[[330,.15],[262,.15],[196,.3]],bad:[[200,.12]],deploy:[[420,.03]]}[type]||[[440,.05]];
    let t=AC.currentTime;seq.forEach(([f,d])=>{const o=AC.createOscillator(),g=AC.createGain();o.type=type==='boom'?'sawtooth':'triangle';o.frequency.value=f;if(type==='boom')o.frequency.exponentialRampToValueAtTime(40,t+d);
      g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(type==='shot'||type==='deploy'?.04:.12,t+.01);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g).connect(AC.destination);o.start(t);o.stop(t+d+.02);t+=d*.9});
  }catch(e){}
}

