/* ================= 3D ENGINE ================= */
const cv=$('#cv');
let W=1,H=1,frameId=0;
const MOB=matchMedia('(pointer:coarse)').matches||/iPhone|iPad|Android/i.test(navigator.userAgent);
const renderer=new THREE.WebGLRenderer({canvas:cv,antialias:true,powerPreference:'high-performance'});
renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.setClearColor(0xd6a15a,1);
const scene=new THREE.Scene();
scene.fog=new THREE.Fog(0xe3b46f,110,175);
const camera=new THREE.PerspectiveCamera(38,1,.5,1200);
const cam={tx:N/2,tz:N/2,z:.8};
const CAMDIR=new THREE.Vector3(1,1.35,1).normalize();
const SINE=CAMDIR.y;
const RIGHT=new THREE.Vector3(1,0,-1).normalize(),FWD=new THREE.Vector3(1,0,1).normalize();
const PPU=34;
const hemi=new THREE.HemisphereLight(0xffeedd,0x8a5a2e,.58);scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffe2b8,.82);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);
Object.assign(sun.shadow.camera,{left:-16,right:16,top:16,bottom:-16,near:1,far:95});sun.shadow.bias=-.0006;sun.shadow.normalBias=.03;
scene.add(sun);scene.add(sun.target);
const rimL=new THREE.DirectionalLight(0x9fc4ff,.28);rimL.position.set(30,18,34);scene.add(rimL);
let shakeAmt=0;function shake(a){shakeAmt=Math.min(.6,Math.max(shakeAmt,a))}
function updateCamera(){const ppu=PPU*cam.z;const sx=(Math.random()-.5)*shakeAmt,sz=(Math.random()-.5)*shakeAmt;const hw=W/2/ppu,hh=H/2/ppu;camera.left=-hw;camera.right=hw;camera.top=hh;camera.bottom=-hh;
  camera.position.set(cam.tx+sx+CAMDIR.x*95,CAMDIR.y*95,cam.tz+sz+CAMDIR.z*95);camera.lookAt(cam.tx+sx,0,cam.tz+sz);camera.updateProjectionMatrix();camera.updateMatrixWorld();
  sun.position.set(cam.tx-17,27,cam.tz-6);sun.target.position.set(cam.tx,0,cam.tz);sun.target.updateMatrixWorld()}
function resize(){fitApp();W=Math.max(1,cv.clientWidth);H=Math.max(1,cv.clientHeight);renderer.setPixelRatio(Math.min((typeof GQ!=='undefined'&&GQ.post)?2.6:2,window.devicePixelRatio||1));renderer.setSize(W,H,false);updateCamera();try{postSize()}catch(e){}}
window.addEventListener('resize',()=>{resize();clampCam()});
if(window.visualViewport)visualViewport.addEventListener('resize',()=>{resize();clampCam()});
window.addEventListener('orientationchange',()=>setTimeout(()=>{resize();clampCam()},300));
const VZ=()=>W<360?.72:W>700?1.0:.8;
function centerOn(gx,gy,z){cam.tx=gx;cam.tz=gy;if(z)cam.z=z;updateCamera()}
function clampCam(){cam.z=Math.max(.3,Math.min(2.2,cam.z));cam.tx=Math.max(-2,Math.min(N+2,cam.tx));cam.tz=Math.max(-2,Math.min(N+2,cam.tz));updateCamera()}
const _ray=new THREE.Raycaster(),_ndc=new THREE.Vector2(),_gp=new THREE.Plane(new THREE.Vector3(0,1,0),0),_hit=new THREE.Vector3(),_pv=new THREE.Vector3();
function rayAt(px,py){_ndc.set(px/W*2-1,-(py/H)*2+1);_ray.setFromCamera(_ndc,camera);return _ray}
function s2w(px,py){rayAt(px,py).ray.intersectPlane(_gp,_hit);return [_hit.x,_hit.z]}
function proj(x,y,z){_pv.set(x,y,z).project(camera);return [(_pv.x+1)/2*W,(1-_pv.y)/2*H]}
function w2s(gx,gy){return proj(gx,0,gy)}
function zoomAt(mx,my,z){const a=s2w(mx,my);cam.z=Math.max(.3,Math.min(2.2,z));updateCamera();const b=s2w(mx,my);cam.tx+=a[0]-b[0];cam.tz+=a[1]-b[1];clampCam()}
const groundY=(x,z)=>(x<0||z<0||x>N||z>N)?-.32:0;

/* materials & primitives */
const MC={};
function M(c,o){const k=c+(o?JSON.stringify(o):'');let m=MC[k];if(!m)m=MC[k]=new THREE.MeshStandardMaterial(Object.assign({color:c,roughness:.88,metalness:0,flatShading:true,envMapIntensity:.35},o||{}));return m}
const SM=c=>M(c,{flatShading:false,roughness:.7});
const mm=c=>typeof c==='string'?M(c):c;
function add(g,geo,m,x,y,z){const o=new THREE.Mesh(geo,m);o.position.set(x||0,y||0,z||0);g.add(o);return o}
const BX=(g,w,h,d,c,x,y,z)=>add(g,new THREE.BoxGeometry(w,h,d),mm(c),x,(y||0)+h/2,z);
const CY=(g,rt,rb,h,c,x,y,z,s)=>add(g,new THREE.CylinderGeometry(rt,rb,h,s||12),mm(c),x,(y||0)+h/2,z);
const CO=(g,r,h,c,x,y,z,s)=>add(g,new THREE.ConeGeometry(r,h,s||8),mm(c),x,(y||0)+h/2,z);
const SP=(g,r,c,x,y,z,s)=>add(g,new THREE.SphereGeometry(r,s||10,Math.max(5,((s||10)*.7)|0)),mm(c),x,y,z);
const DO=(g,r,c,x,y,z)=>add(g,new THREE.DodecahedronGeometry(r,0),mm(c),x,y,z);
const dyn=o=>{o.userData.dyn=1;return o};
const BLOBT=(()=>{const c=document.createElement('canvas');c.width=c.height=64;const g=c.getContext('2d');const r=g.createRadialGradient(32,32,2,32,32,31);r.addColorStop(0,'rgba(40,20,5,.55)');r.addColorStop(1,'rgba(40,20,5,0)');g.fillStyle=r;g.fillRect(0,0,64,64);return new THREE.CanvasTexture(c)})();
const BLOBM=new THREE.MeshBasicMaterial({map:BLOBT,transparent:true,depthWrite:false});const BLOBG=new THREE.PlaneGeometry(1,1);BLOBG.rotateX(-Math.PI/2);
