function disposeObj(o){o.traverse(c=>{if(c.geometry)c.geometry.dispose()})}
const MUD='#dcab6c',MUD2='#c08c52',MUDL='#ebcf9c',WOOD='#8a5a2e',WOODD='#5e3a1a',STONE='#b9b1a5',STONE2='#a39a8c',GOLD='#ffcb2b',WATER='#3fb6ff',PAVE='#d8bf93';
