const WINM=M('#4a2c16');
const DAYLEN=600;
const SKYK=[[0,'#ffe2b8',.82,'#ffeedd','#8a5a2e',.58,'#d6a15a',0],[.52,'#ffe2b8',.82,'#ffeedd','#8a5a2e',.58,'#d6a15a',0],[.6,'#ff9c5e',.74,'#ffcaa0','#7a4a2e',.54,'#c98252',.35],[.68,'#a8b6ff',.55,'#97a4dc','#4a3a58',.66,'#5a5c8e',1],[.88,'#a8b6ff',.55,'#97a4dc','#4a3a58',.66,'#5a5c8e',1],[.95,'#ffb27a',.64,'#ffd6b0','#7a5a3e',.54,'#c99060',.35],[1,'#ffe2b8',.82,'#ffeedd','#8a5a2e',.58,'#d6a15a',0]];
const _c1=new THREE.Color(),_c2=new THREE.Color();let nightK=0;
function updateSky(){const p=(Date.now()/1000%DAYLEN)/DAYLEN;let i=0;while(i<SKYK.length-2&&p>SKYK[i+1][0])i++;const a=SKYK[i],b=SKYK[i+1];const f=(p-a[0])/Math.max(1e-6,b[0]-a[0]);
  const lc=k=>_c1.set(a[k]).lerp(_c2.set(b[k]),f);sun.color.copy(lc(1));sun.intensity=a[2]+(b[2]-a[2])*f;hemi.color.copy(lc(3));hemi.groundColor.copy(lc(4));hemi.intensity=a[5]+(b[5]-a[5])*f;
  const cc=lc(6).clone();renderer.setClearColor(cc);scene.fog.color.copy(cc);nightK=a[7]+(b[7]-a[7])*f;WINM.emissive.setRGB(1,.55,.15).multiplyScalar(nightK*.95)}
