function mergeStatic(g){g.updateMatrixWorld(true);const buckets=new Map(),rm=[];
  g.traverse(o=>{if(!o.isMesh)return;let p=o;while(p&&p!==g){if(p.userData.dyn)return;p=p.parent}if(o.material.transparent||o.userData.ns)return;
    const k=o.material.uuid;if(!buckets.has(k))buckets.set(k,{m:o.material,list:[]});buckets.get(k).list.push(o)});
  buckets.forEach(({m,list})=>{if(list.length<2)return;const geos=list.map(o=>{const gg=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();gg.applyMatrix4(o.matrixWorld);return gg});
    let n=0;geos.forEach(x=>n+=x.attributes.position.count);const pos=new Float32Array(n*3),nor=new Float32Array(n*3);let off=0;
    geos.forEach(x=>{pos.set(x.attributes.position.array,off*3);if(x.attributes.normal)nor.set(x.attributes.normal.array,off*3);off+=x.attributes.position.count;x.dispose()});
    const mg=new THREE.BufferGeometry();mg.setAttribute('position',new THREE.BufferAttribute(pos,3));mg.setAttribute('normal',new THREE.BufferAttribute(nor,3));
    g.add(new THREE.Mesh(mg,m));list.forEach(o=>{o.parent.remove(o);rm.push(o)})});
  rm.forEach(o=>o.geometry.dispose());return g}

/* ---------- buildings ---------- */
function crenels(g,w,d,y,c,s){s=s||.24;const geo=new THREE.ConeGeometry(.09,.18,4);geo.rotateY(Math.PI/4);const m=M(c);
  const nx=Math.max(1,Math.round(w/s)),nz=Math.max(1,Math.round(d/s));const put=(x,z)=>add(g,geo,m,x,y+.09,z);
  for(let i=0;i<=nx;i++){const x=-w/2+i*w/nx;put(x,-d/2+.05);put(x,d/2-.05)}
  for(let i=1;i<nz;i++){const z=-d/2+i*d/nz;put(-w/2+.05,z);put(w/2-.05,z)}}
function pegs(g,w,y,face,n){const geo=new THREE.CylinderGeometry(.035,.035,.22,5);if(face==='x')geo.rotateZ(Math.PI/2);else geo.rotateX(Math.PI/2);
  for(let i=0;i<n;i++){const a=-w/2+.22+i*(w-.44)/Math.max(1,n-1);if(face==='x')add(g,geo,M(WOODD),w/2+.06,y,a);else add(g,geo,M(WOODD),a,y,w/2+.06)}}
function triWins(g,w,y,n){for(let i=0;i<n;i++){const a=-w/2+.25+i*(w-.5)/Math.max(1,n-1);
  const t1=add(g,new THREE.ConeGeometry(.07,.13,3),M('#4a2c16'),a,y,w/2+.005);t1.scale.z=.25;
  const t2=add(g,new THREE.ConeGeometry(.07,.13,3),M('#4a2c16'),w/2+.005,y,a);t2.scale.x=.25}}
function flag(g,x,y,z,c,len){CY(g,.025,.03,len||1,WOODD,x,y,z,6);const fp=dyn(new THREE.Group());fp.position.set(x,y+(len||1)-.06,z);g.add(fp);BX(fp,.56,.34,.03,c,.29,-.34,0);BX(fp,.18,.1,.035,GOLD,.31,-.22,0);return fp}
