function mkDune(){const L=N+1.6,geo=new THREE.PlaneGeometry(L,2,72,24);const p=geo.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),zz=p.getY(i);const crest=.3+.18*Math.sin(x*.55)+.08*Math.sin(x*1.7+1);let h=zz<crest?Math.pow(Math.max(0,Math.cos((zz-crest)/(1+crest)*Math.PI/2)),1.25):Math.pow(Math.max(0,Math.cos((zz-crest)/(1-crest)*Math.PI/2)),2.3);const ex=Math.min(1,(L/2-Math.abs(x))/2.2);h*=(.82+.18*Math.sin(x*.4+2))*Math.max(0,ex)*.98;h+=Math.sin(x*3.1+zz*5)*.015;p.setXYZ(i,x,h,zz)}geo.computeVertexNormals();const m=new THREE.Mesh(geo,new THREE.MeshLambertMaterial({map:duneTex}));m.castShadow=m.receiveShadow=true;m.visible=false;scene.add(m);return m}
