const PG={sph:new THREE.IcosahedronGeometry(1,0),box:new THREE.BoxGeometry(1,1,1)};
const PM={flash:new THREE.MeshBasicMaterial({color:'#ffe27a'}),fire:new THREE.MeshBasicMaterial({color:'#ff8a2b'}),smoke:M('#a89a88'),dark:M('#6b5a48'),wood:M(WOOD),white:M('#fff6e0',{flatShading:false}),sand:M('#ecc78c'),gold:GOLDM,water:WATERM,heal:new THREE.MeshBasicMaterial({color:'#7dff9a'}),rage:new THREE.MeshBasicMaterial({color:'#ff5a2a'}),fly:new THREE.MeshBasicMaterial({color:'#fff2a0'}),c1:new THREE.MeshBasicMaterial({color:'#ff5a5a'}),c2:new THREE.MeshBasicMaterial({color:'#ffd23f'}),c3:new THREE.MeshBasicMaterial({color:'#4fc3ff'}),c4:new THREE.MeshBasicMaterial({color:'#7ddc4a'})};
const parts=[];
function P(geo,m,x,y,z,vx,vy,vz,life,s0,s1,o){if(parts.length>(MOB?160:300))return;const ms=new THREE.Mesh(PG[geo],PM[m]);ms.position.set(x,y,z);ms.scale.setScalar(Math.max(.001,s0));ms.castShadow=(m==='smoke'||m==='dark'||m==='wood');scene.add(ms);parts.push(Object.assign({o:ms,v:new THREE.Vector3(vx,vy,vz),life,t:0,s0,s1,g:0,curve:0,spin:0},o||{}))}
function updateParts(dt){for(let i=parts.length-1;i>=0;i--){const p=parts[i];p.t+=dt;const f=p.t/p.life;if(f>=1){scene.remove(p.o);parts.splice(i,1);continue}
  p.v.y-=p.g*dt;p.o.position.addScaledVector(p.v,dt);if(p.g&&p.o.position.y<.03){p.o.position.y=.03;p.v.set(p.v.x*.4,0,p.v.z*.4)}
  const s=p.curve?p.s1*Math.sin(Math.PI*f):p.s0+(p.s1-p.s0)*f;p.o.scale.setScalar(Math.max(.001,s));if(p.spin){p.o.rotation.x+=p.spin*dt;p.o.rotation.y+=p.spin*dt}}}
function boom(x,z,r){r=r||1;const y=groundY(x,z);P('sph','flash',x,y+.4,z,0,0,0,.22,.1,r*.85);
  for(let i=0;i<7;i++){const a=Math.random()*6.28;P('sph','fire',x,y+.3,z,Math.cos(a)*1.6*r,1.6+Math.random()*1.6,Math.sin(a)*1.6*r,.45,.26*r,.02)}
  for(let i=0;i<8;i++){const a=Math.random()*6.28;P('sph','smoke',x+Math.cos(a)*.2,y+.3,z+Math.sin(a)*.2,Math.cos(a)*.6,.9+Math.random(),Math.sin(a)*.6,1.1+Math.random()*.5,0,.36*r+.15,{curve:1})}
  for(let i=0;i<7;i++){const a=Math.random()*6.28;P('box',Math.random()<.5?'wood':'dark',x,y+.4,z,Math.cos(a)*2.2,3+Math.random()*2,Math.sin(a)*2.2,1.2,.1,.06,{g:12,spin:8})}}
