function updFlyers(dt,t){for(let i=flyers.length-1;i>=0;i--){const F=flyers[i];F.t+=dt;const k=F.t/F.dur;if(k>=1){scene.remove(F.o);disposeObj(F.o);flyers.splice(i,1);continue}
  const p=new THREE.Vector3(cam.tx,0,cam.tz).addScaledVector(RIGHT,17-34*k).addScaledVector(FWD,-2+Math.sin(k*3)*2.5);p.y=4.2+Math.sin(k*6)*.5;F.o.position.copy(p);F.o.rotation.y=Math.atan2(-(-RIGHT.z),-RIGHT.x);
  const w=Math.sin(t*22)*.9;F.o.userData.wings[0].rotation.x=w;F.o.userData.wings[1].rotation.x=-w}}

/* ---------- DOM overlay ---------- */
const ovRoot=$('#ov');const pool={};let used={};
function ovEl(kind){used[kind]=(used[kind]||0)+1;const arr=pool[kind]||(pool[kind]=[]);let e=arr[used[kind]-1];if(!e){e=document.createElement('div');e.className='ov-'+kind;ovRoot.appendChild(e);arr.push(e)}if(e.style.display==='none')e.style.display='';return e}
function ovBegin(){used={}}
function ovEnd(){for(const k in pool){const n=used[k]||0;pool[k].forEach((e,i)=>{if(i>=n&&e.style.display!=='none')e.style.display='none'})}}
function pos2(e,x,y){e.style.transform=`translate(${x.toFixed(1)}px,${y.toFixed(1)}px)`}
function ovHp(x,y,z,f,enemy){const [px,py]=proj(x,y,z);const e=ovEl('hp');if(!e.firstChild)e.innerHTML='<i></i>';e.firstChild.style.width=(Math.max(0,f)*100)+'%';e.firstChild.style.background=enemy?'#e8443a':f>.5?'#6fd12c':'#ffb000';pos2(e,px,py)}
function ovBub(x,y,z,icon,t,full){const [px,py]=proj(x,y,z);const e=ovEl('bub');if(e._k!==icon){e._k=icon;e.innerHTML=art(icon)}if(e._f!==!!full){e._f=!!full;e.classList.toggle('full',!!full)}pos2(e,px,py+Math.sin(t*4+x)*4);return [px,py]}
function ovText(kind,px,py,s,col){const e=ovEl(kind);if(e._s!==s){e._s=s;e.textContent=s}if(col)e.style.color=col;pos2(e,px,py);return e}
function fxUpdate(t){fx.forEach(f=>{if(!f._s){f._s=1;const y=groundY(f.gx,f.gy);
    if(f.k==='boom'){boom(f.gx,f.gy,f.r||1);shake(.06*(f.r||1))}
    else if(f.k==='ring'){for(let i=0;i<30;i++){const a=i/30*6.28;P('sph','rage',f.gx,y+.4,f.gy,Math.cos(a)*7,.6,Math.sin(a)*7,.6,.16,.02)}}
    else if(f.k==='hit'){for(let i=0;i<3;i++)P('sph','white',f.gx,y+.45,f.gy,(Math.random()-.5)*2,1+Math.random(),(Math.random()-.5)*2,.25,.08,0)}
    else if(f.k==='puff'){for(let i=0;i<8;i++){const a=i/8*6.28;P('sph','white',f.gx,y+.1,f.gy,Math.cos(a)*1.7,.3,Math.sin(a)*1.7,.45,0,.22,{curve:1})}}
    else if(f.k==='ghost'){for(let i=0;i<5;i++)P('sph','white',f.gx,y+.3,f.gy,(Math.random()-.5),1.4,(Math.random()-.5),.7,0,.16,{curve:1})}
    else if(f.k==='falcon')spawnFalconFly()}
  if(f.k==='txt'){const [x,y]=proj(f.gx,groundY(f.gx,f.gy)+1.4+f.t/f.dur*1.4,f.gy);const e=ovText('txt',x,y,f.s,f.col);e.style.opacity=1-Math.max(0,(f.t/f.dur-.6)/.4)}
  else if(f.k==='no'){const [x,y]=proj(f.gx,.3,f.gy);const e=ovText('x',x,y,'✕');e.style.opacity=1-f.t/f.dur}})}
let dustAcc=0;
function ambient(t,dt){dustAcc+=dt;if(dustAcc>(MOB?.22:.12)){dustAcc=0;const x=cam.tx+(Math.random()-.5)*26,z=cam.tz+(Math.random()-.5)*26;P('sph','sand',x,groundY(x,z)+.1+Math.random()*.7,z,1.3,.15,-.45,2.6,0,.05,{curve:1})}
  palms.forEach((p,i)=>{p.rotation.z=Math.sin(t*1.3+i)*.06;p.rotation.x=Math.cos(t*1.1+i*.7)*.04});
  if(nightK>.5&&Math.random()<.3){const x=cam.tx+(Math.random()-.5)*22,z=cam.tz+(Math.random()-.5)*22;P('sph','fly',x,groundY(x,z)+.3+Math.random()*.8,z,rnd(-.3,.3),.12,rnd(-.3,.3),3,0,.045,{curve:1})}}

/* ---------- per-building animation ---------- */
function animBuilding(m,b,t,ctx){const ud=m.userData;
  if(ud.flag){ud.flag.rotation.y=Math.sin(t*3+b.x)*.3;ud.flag.scale.x=.9+Math.sin(t*6+b.y)*.1}
  if(ud.flame){ud.flame.scale.set(1+Math.sin(t*17)*.08,1+Math.sin(t*23)*.22,1)}
  if(ud.water)ud.water.position.y=.5+Math.sin(t*2+b.x)*.008;
  if(ud.head)ud.head.rotation.y=Math.sin(t*.8+b.x)*.9;
  if(ud.ring){const k=1+Math.sin(t*8)*.12;ud.ring.scale.set(k,k,k)}
  let fill=.7;
  if(ctx.village){if(b.t==='goldmine')fill=b.stock/BT.goldmine.cap[Math.max(0,b.lvl-1)];else if(b.t==='goldstore')fill=S.gold/capG();else if(b.t==='waterstore')fill=S.water/capW()}
  if(ud.pile){const k=.35+.65*Math.max(0,Math.min(1,fill));ud.pile.scale.set(b.t==='goldstore'?1.15*k:k,(b.t==='goldstore'?.45:.55)*k,b.t==='goldstore'?.8*k:k)}
  if(ud.waterCol){const f=Math.max(.04,Math.min(1,fill))*.86;ud.waterCol.scale.y=f;ud.waterCol.position.y=.25+f/2}
  if(ud.aim){let yaw=null;if(ctx.battle&&BB){const [cx,cz]=bcen(b);let bd=(BT[b.t].range||6)+.5;BB.units.forEach(u=>{if(u.dead)return;const d=Math.hypot(u.x-cx,u.y-cz);if(d<bd){bd=d;yaw=Math.atan2(-(u.y-cz),u.x-cx)}})}
    if(yaw==null)yaw=Math.sin(t*.5+b.x)*1.2+.8;let d=yaw-ud.aim.rotation.y;d=Math.atan2(Math.sin(d),Math.cos(d));ud.aim.rotation.y+=d*.15}
  if(ud.arm){const a=Math.min(1.5,b.arm||0);ud.arm.rotation.z=.45-a*.95;if(ud.arm.userData.stone)ud.arm.userData.stone.visible=a<.25}
  if(ud.hero)ud.hero.rotation.y=.6+Math.sin(t*.5+b.x)*.35;
  if(ud.flame&&ctx.village&&Math.random()<.04)P('sph','smoke',m.position.x+(ud.smk?ud.smk[0]:.95),ud.smk?ud.smk[1]:.6,m.position.z+(ud.smk?ud.smk[2]:.95),rnd(-.1,.1),.7,rnd(-.1,.1),2.2,0,.2,{curve:1});
  if(b.t==='goldmine'&&ctx.village&&Math.random()<.03)P('sph','fly',m.position.x+.52+rnd(-.2,.2),.5,m.position.z+.66,0,.8,0,.8,0,.05,{curve:1})}
function posUnit(m,u,t,face){const ud=m.userData;const px=u._px==null?u.x:u._px,py=u._py==null?u.y:u._py;const dx=u.x-px,dz=u.y-py;
  if(Math.abs(dx)+Math.abs(dz)>1e-4)u._yaw=Math.atan2(-dz,dx);else if(face)u._yaw=Math.atan2(-(face[1]-u.y),face[0]-u.x);
  u._px=u.x;u._py=u.y;if(u._yaw!=null){let d=u._yaw-m.rotation.y;d=Math.atan2(Math.sin(d),Math.cos(d));m.rotation.y+=d*.25}
  const w=(u.walk||0)*10,mv=u.moving;m.position.set(u.x,groundY(u.x,u.y)+(mv?Math.abs(Math.sin(w))*.08:0),u.y);
  if(ud.legs)ud.legs.forEach((l,i)=>l.rotation.z=mv?Math.sin(w+(i%2?Math.PI:0)+(i>1?Math.PI/2:0))*.6:0);
  if(ud.arm)ud.arm.rotation.z=(!mv&&face)?-Math.max(0,Math.sin(t*9))*1.3:0;
  if(ud.cape)ud.cape.rotation.z=.25+(mv?Math.sin(w*1.5)*.18:Math.sin(t*2)*.05)}

/* ---------- village & battle render ---------- */
const placeKey={};
function renderVillage(t,dt){
  const walls=new Set(S.b.filter(b=>b.t==='wall').map(b=>b.x+','+b.y));
  S.b.forEach(b=>{if(place&&place.move===b)return;const s=BT[b.t].s,lvl=Math.max(1,b.lvl);
    let key=b.t+lvl+(b.up?'u':'')+(b.buried?'b':'');let nb=null;
    if(b.t==='wall'){nb={x:walls.has((b.x+1)+','+b.y),z:walls.has(b.x+','+(b.y+1))};key+=(nb.x?'X':'')+(nb.z?'Z':'')}
    const m=syncObj(b,key,()=>buildFull(b.t,lvl,{nb,up:!!b.up,buried:b.buried}));m.position.set(b.x+s/2,0,b.y+s/2);animBuilding(m,b,t,{village:1});
    if(b._pop){const k=t-b._pop;if(k>=0&&k<.7){const sc=1+Math.sin(k/.7*Math.PI*2)*.16*(1-k/.7);m.scale.set(sc,sc+(1-k/.7)*.08,sc)}else{m.scale.set(1,1,1);if(k>=.7)delete b._pop}}
    const cx=b.x+s/2,cz=b.y+s/2,th=TOPH[b.t];
    if(b.up){const [px,py]=proj(cx,th+.5,cz);const e=ovEl('tm');const k=Math.max(0,Math.min(1,1-(b.up.end-now())/(b.up.dur*1000)));e.innerHTML=`<b>${fmtT((b.up.end-now())/1000)}</b><i><u style="width:${k*100}%"></u></i>`;pos2(e,px,py)}
    else if(b.buried)ovBub(cx,th+.6,cz,'shovel',t);
    else if(BT[b.t].rate&&b.stock>BT[b.t].cap[lvl-1]*.15){const full=b.t==='goldmine'?S.gold>=capG():S.water>=capW();const q=ovBub(cx,th+.6,cz,b.t==='well'?'drop':'coin',t,full);b._bub={x:q[0],y:q[1],f:frameId}}});
  (S.obs||[]).forEach(o=>{const m=syncObj(o,'ob'+o.k,()=>obsMesh(o.k));m.position.set(o.x+.5,0,o.y+.5)});
  if(place){const s=BT[place.t].s;const ok=inGrid(place.x,place.y,s)&&!occupied(place.x,place.y,s,place.move)&&!inDune(place.x,place.y,s);
    const lv=place.move?Math.max(1,place.move.lvl):1;const m=syncObj(placeKey,'g'+place.t+lv,()=>buildFull(place.t,lv,{nb:{}}));
    m.position.set(place.x+s/2,.18+Math.sin(t*6)*.06,place.y+s/2);
    placeTile.visible=true;placeTile.scale.set(s,s,1);placeTile.position.set(place.x+s/2,.02,place.y+s/2);placeTile.material.color.set(ok?'#6fd12c':'#e8443a');
    const [px,py]=proj(place.x+s/2,TOPH[place.t]+.7,place.y+s/2);ovText('hint',px,py,'اسحبني')}
  else placeTile.visible=false;
  if(selB&&!place){const s=BT[selB.t].s;setSq(selB.x+s/2,selB.y+s/2,s,(Math.sin(t*5)+1)/2);const r=BT[selB.t].range;
    if(r){rangeDisc.visible=rangeRing.visible=true;rangeDisc.scale.set(r,r,1);rangeRing.scale.set(r,r,1);rangeDisc.position.set(selB.x+s/2,.02,selB.y+s/2);rangeRing.position.copy(rangeDisc.position)}else rangeDisc.visible=rangeRing.visible=false}
  else if(selO&&!place){setSq(selO.x+.5,selO.y+.5,1,(Math.sin(t*5)+1)/2);rangeDisc.visible=rangeRing.visible=false}
  else{selSq.visible=false;rangeDisc.visible=rangeRing.visible=false}
  if(S.dune.side>=0)placeDune(dune,S.dune.side,1);else dune.visible=false;
  if(S.dune.warned&&S.dune.nextSide!=null){const k=Math.max(.12,Math.min(1,1-(S.dune.next-now())/30000));placeDune(dune2,S.dune.nextSide,k);
    if(Math.random()<.5){const sd=S.dune.nextSide,a=Math.random()*N;const x=sd===1?N+.5:sd===3?-.5:a,z=sd===0?-.5:sd===2?N+.5:a;const vx=sd===1?-2:sd===3?2:0,vz=sd===0?2:sd===2?-2:0;P('sph','sand',x,.3+Math.random(),z,vx+(Math.random()-.5),.2,vz+(Math.random()-.5),1.4,0,.13,{curve:1})}}
  else dune2.visible=false;
  blkPlane.visible=false}
function renderBattle(t,dt){const B=BB;const rev=B.revealUntil>now();
  dune.visible=dune2.visible=false;selSq.visible=false;rangeDisc.visible=rangeRing.visible=false;placeTile.visible=false;
  if(mode==='battle'&&B.sel&&B.blocked)setBlocked(B.blocked);else blkPlane.visible=false;
  if(B.kind==='caravan')syncObj(B.path,'road',()=>roadMesh(B.path));
  const walls=new Set(B.bld.filter(b=>b.t==='wall'&&!b.dead).map(b=>b.x+','+b.y));
  B.bld.forEach(b=>{if(b.t==='trap'&&(b.dead||!rev))return;const s=BT[b.t].s;let key=b.t+b.lvl+(b.dead?'d':'');let nb=null;
    if(b.t==='wall'&&!b.dead){nb={x:walls.has((b.x+1)+','+b.y),z:walls.has(b.x+','+(b.y+1))};key+=(nb.x?'X':'')+(nb.z?'Z':'')}
    const m=syncObj(b,key,()=>b.dead?bRubble(s):buildFull(b.t,b.lvl,{nb,revealed:true}));m.position.set(b.x+s/2,0,b.y+s/2);if(b._hit&&t-b._hit<.15&&!b.dead){m.position.x+=(Math.random()-.5)*.1;m.position.z+=(Math.random()-.5)*.1}
    if(!b.dead){animBuilding(m,b,t,{battle:1});if(b.hp<b.maxhp&&b.t!=='trap')ovHp(b.x+s/2,TOPH[b.t]+.3,b.y+s/2,b.hp/b.maxhp)}});
  renderMobs(B,t);
  (B.spells||[]).forEach(sp=>{const m=syncObj(sp,'sp'+sp.k,()=>spellMesh(sp.k));m.position.set(sp.x,groundY(sp.x,sp.y),sp.y);m.userData.spin.rotation.y=t*3;const r=SPL[sp.k].r;
    if(sp.k==='dune'){if(Math.random()<.7)P('sph','sand',sp.x+rnd(-r,r)*.8,rnd(.2,1.4),sp.y+rnd(-r,r)*.8,rnd(-2,2),1.2,rnd(-2,2),.6,.1,.02)}else if(sp.k==='storm'){for(let i=0;i<3;i++){const a=rnd(0,6.28),rr=rnd(.3,r);P('sph','sand',sp.x+Math.cos(a)*rr,rnd(.2,2.2),sp.y+Math.sin(a)*rr,-Math.sin(a)*3.5,.6,Math.cos(a)*3.5,.6,.11,.02)}}
    else{for(let i=0;i<2;i++)P('sph','water',sp.x+rnd(-r,r)*.7,2.4,sp.y+rnd(-r,r)*.7,0,-6,0,.4,.05,.05);if(Math.random()<.5)P('sph','heal',sp.x+rnd(-r,r)*.6,.2,sp.y+rnd(-r,r)*.6,0,1.4,0,.8,0,.08,{curve:1})}});
  B.en.forEach(e=>{if(e.dead||e.escaped||B.prog+e.off<0)return;const m=syncObj(e,'e'+e.t,()=>unitMesh(e.t==='camel'?'camel':'guard',true,e.box));posUnit(m,e,t,null);
    if(e.hp<e.maxhp)ovHp(e.x,groundY(e.x,e.y)+(e.t==='camel'?1.6:1.15),e.y,e.hp/e.maxhp,true)});
  B.proj.forEach(p=>{const m=syncObj(p,'p'+p.k,()=>projMesh(p.k));const f=Math.min(1,p.t/p.dur);let tx,ty;if(p.u){tx=p.u.x;ty=p.u.y}else{tx=p.tx;ty=p.ty}
    const y0=p.k==='stone'?1.3:(p.h?2.1:.65),y1=p.u&&TR[p.u.t]&&TR[p.u.t].air?2:.45;const at=k=>new THREE.Vector3(p.x+(tx-p.x)*k,y0+(y1-y0)*k+Math.sin(Math.PI*k)*(p.k==='stone'?3:.7),p.y+(ty-p.y)*k);
    m.position.copy(at(f));m.lookAt(at(Math.min(1,f+.05)))});
  if(rev&&B.kind==='base')ovText('hint',W/2,150,'الصقر يكشف الفخاخ: '+Math.ceil((B.revealUntil-now())/1000));
  if(mode==='scout')ovText('hint',W/2,H*.27,B.kind==='base'?'استكشف القلعة قبل الهجوم':'القافلة جاية من هالطريق')}
function roadMesh(path){const g=new THREE.Group();const cl=v=>Math.max(0,Math.min(N,v));const pts=path.map(p=>[cl(p[0]),cl(p[1])]);const m=M('#c9925c');
  for(let i=0;i<pts.length-1;i++){const [ax,az]=pts[i],[bx,bz]=pts[i+1];const len=Math.hypot(bx-ax,bz-az);if(len<.01)continue;
    const sg=new THREE.Group();sg.position.set((ax+bx)/2,.008+i*.0004,(az+bz)/2);sg.rotation.y=Math.atan2(-(bz-az),bx-ax);g.add(sg);
    const pl=add(sg,new THREE.PlaneGeometry(len,1.15),m,0,0,0);pl.rotation.x=-Math.PI/2;
    for(let k=.3;k<len;k+=.55){const d=add(sg,new THREE.CircleGeometry(.06,6),M('#a8744a'),k-len/2,.003,(Math.floor(k*3)%2?.18:-.18));d.rotation.x=-Math.PI/2}}
  pts.forEach(([x,z])=>{const c=add(g,new THREE.CircleGeometry(.575,16),m,x,.008,z);c.rotation.x=-Math.PI/2});
  return g}

/* ---------- previews ---------- */
let PR=null,PS=null,PC=null;
function prevRender(obj,w,h,pad){if(!PR){PR=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});PR.setClearColor(0,0);PS=new THREE.Scene();PS.add(new THREE.HemisphereLight(0xffeedd,0x8a5a2e,.65));const d=new THREE.DirectionalLight(0xffe2b8,.85);d.position.set(-17,27,-6);PS.add(d);PC=new THREE.OrthographicCamera(-1,1,1,-1,.1,300);PR.outputEncoding=THREE.sRGBEncoding;PR.toneMapping=THREE.NoToneMapping;PS.children.forEach(l=>{if(l.color)l.color.convertSRGBToLinear();if(l.groundColor)l.groundColor.convertSRGBToLinear()})}
  PR.setPixelRatio(2);PR.setSize(w,h,false);PS.add(obj);obj.updateMatrixWorld(true);
  const bb=new THREE.Box3().setFromObject(obj);const c=bb.getCenter(new THREE.Vector3());PC.position.copy(c).addScaledVector(CAMDIR,80);PC.lookAt(c);PC.updateMatrixWorld();
  const inv=PC.matrixWorldInverse;let x0=1e9,x1=-1e9,y0=1e9,y1=-1e9;for(let i=0;i<8;i++){const v=new THREE.Vector3(i&1?bb.max.x:bb.min.x,i&2?bb.max.y:bb.min.y,i&4?bb.max.z:bb.min.z).applyMatrix4(inv);x0=Math.min(x0,v.x);x1=Math.max(x1,v.x);y0=Math.min(y0,v.y);y1=Math.max(y1,v.y)}
  pad=pad||1.1;let cw=(x1-x0)*pad,ch=(y1-y0)*pad;const ar=w/h;if(cw/ch>ar)ch=cw/ar;else cw=ch*ar;const mx=(x0+x1)/2,my=(y0+y1)/2;
  PC.left=mx-cw/2;PC.right=mx+cw/2;PC.top=my+ch/2;PC.bottom=my-ch/2;PC.near=.1;PC.far=300;PC.updateProjectionMatrix();
  PR.render(PS,PC);PS.remove(obj);disposeObj(obj);return PR.domElement}

/* ================= VILLAGE ================= */
let mode='menu'; // menu | village | scout | battle
let selB=null,place=null,selO=null; // place:{t,x,y,move:b}
function occupied(x,y,s,ignore){for(const b of S.b){if(b===ignore)continue;const bs=BT[b.t].s;if(x<b.x+bs&&x+s>b.x&&y<b.y+bs&&y+s>b.y)return true}if(S.obs)for(const o of S.obs){if(x<o.x+1&&x+s>o.x&&y<o.y+1&&y+s>o.y)return true}return false}
function inGrid(x,y,s){return x>=0&&y>=0&&x+s<=N&&y+s<=N}
function duneSet(){const st=new Set();const sd=S.dune.side;if(sd<0)return st;for(let x=0;x<N;x++)for(let y=0;y<N;y++){if((sd===0&&y<3)||(sd===1&&x>=N-3)||(sd===2&&y>=N-3)||(sd===3&&x<3))st.add(y*N+x)}return st}
function inDune(x,y,s){const st=duneSet();for(let i=x;i<x+s;i++)for(let j=y;j<y+s;j++)if(st.has(j*N+i))return true;return false}
function hitBuilding(gx,gy){let best=null;for(const b of S.b){const s=BT[b.t].s;if(gx>=b.x&&gx<b.x+s&&gy>=b.y&&gy<b.y+s){if(!best||b.x+b.y>best.x+best.y)best=b}}return best}

function villageTick(dt){
  const t=now();
  S.b.forEach(b=>{
    const d=BT[b.t];
    if(b.up&&t>=b.up.end){b.lvl++;b.up=null;snd('win');toast(d.n+' وصل مستوى '+b.lvl+'!');notif('قلاع النفود',d.n+' خلص ووصل مستوى '+b.lvl);b._pop=performance.now()/1000;confettiAt(b.x+d.s/2,b.y+d.s/2);addXP(8*b.lvl);if(selB===b)showSel()}
    if(d.rate&&!b.up&&!b.buried){b.stock=Math.min(d.cap[b.lvl-1],b.stock+d.rate[b.lvl-1]*tribeBonus()*evProd(b.t)*decoB()*wxProd(b.t)*seasonProd()*dt)}
  });
  if(S.queue.length){const q=S.queue[0];if(!q.end)q.end=t+TR[q.t].time*1000*evTrain();if(t>=q.end){S.army[q.t]++;S.queue.shift();if(S.queue[0])S.queue[0].end=t+TR[S.queue[0].t].time*1000*evTrain();else{toast('الجيش جاهز!');snd('build');notif('قلاع النفود','جيشك خلص تدريب وجاهز للهجوم')}}}
  if(S.fz&&S.fz.ready&&t>=S.fz.ready)fzFill();
  // dune
  if(!S.dune.warned&&S.dune.next-t<30000){S.dune.warned=true;S.dune.nextSide=(S.dune.side+1+ri(0,2))%4;banner('dune','الكثبان جاية!','بعد 30 ثانية بيزحف الرمل من '+['الشمال','الشرق','الجنوب','الغرب'][S.dune.nextSide]+'. انقل مبانيك من الطرف.')}
  if(t>=S.dune.next){S.dune.side=S.dune.nextSide!=null?S.dune.nextSide:ri(0,3);S.dune.nextSide=null;S.dune.warned=false;S.dune.next=t+6*60000;applyDune();}
  // tribe auto xp
  if(t-S.tribe.last>20000){S.tribe.last=t;const m=pick(S.tribe.mem);const c=ri(40,160);m.c+=c;addTribeXp(c,true)}
  if(!S.raid.pend&&t>=S.raid.next){S.raid.pend=t+60000;banner('swords','غزاة جايين!','عندك دقيقة. اضغط "دافع" وصدّهم بالفارس والتعاويذ.');snd('bad')}
  if(S.raid.pend&&t>=S.raid.pend)autoRaid();
  if(t>=(S.obsNext||0)){S.obsNext=t+300000;if(S.obs.length<10)spawnObs()}
}
function applyDune(){let n=0;S.b.forEach(b=>{const was=b.buried;b.buried=inDune(b.x,b.y,BT[b.t].s);if(b.buried&&!was)n++});
  banner('dune','زحف الرمل!',n?'الكثبان دفنت '+n+' من مبانيك. احفرها أو انقلها.':'الكثبان زحفت بس مبانيك سليمة.');snd('boom');if(selB)showSel()}
function addTribeXp(x,silent){const need=()=>500*S.tribe.lvl;S.tribe.xp+=x;while(S.tribe.xp>=need()){S.tribe.xp-=need();S.tribe.lvl++;S.gems+=5;if(!silent||true)banner('tent','القبيلة كبرت!','بئر القبيلة وصل مستوى '+S.tribe.lvl+'. إنتاجك زاد، وجاتك 5 جواهر.')}}

/* HUD */
function hud(){
  const cg=capG(),cw=capW();S.gold=Math.min(S.gold,cg);S.water=Math.min(S.water,cw);
  $('#hG').textContent=fmt(S.gold);$('#hW').textContent=fmt(S.water);$('#hGem').textContent=fmt(S.gems);$('#hTro').textContent=S.tro;
  $('#hGc').textContent='/'+fmt(cg);$('#hWc').textContent='/'+fmt(cw);
  $('#fG').style.transform=`scaleX(${S.gold/cg})`;$('#hG').closest('.chip').classList.toggle('full',S.gold>=cg);$('#hW').closest('.chip').classList.toggle('full',S.water>=cw);$('#fW').style.transform=`scaleX(${S.water/cw})`;
  $('#hBld').textContent=(2-busy())+'/2';
  const dl=(S.dune.next-now())/1000;$('#hDune').textContent=dl>0?fmtT(dl):'الحين';
  $('#dunePill').style.background=dl<30?'rgba(232,68,58,.8)':'';
  $('#hLv').textContent=S.plv;$('#hXp').style.width=Math.min(100,S.xp/xpNeed(S.plv)*100)+'%';
  $('#bQuest').classList.toggle('badge',QUESTS.some(q=>!S.claimed.includes(q.id)&&q.v()>=q.n));$('#bDaily').classList.toggle('badge',dailyAvail());
  const rb=$('#raidBtn');if(S.raid.pend){rb.hidden=false;$('#raidT').textContent=fmtT((S.raid.pend-now())/1000)}else rb.hidden=true;
  hud4();hud5();hud7();
}

/* selection panel */
function showSel(){
  if(selO&&!selB){showObs();return}
  const b=selB;if(!b){$('#sel').classList.remove('on');return}
  const d=BT[b.t],L=b.lvl,maxL=b.t==='castle'?MAXL:cl();
  $('#selT').textContent=(b.t==='castle'?HOMEN:d.n)+' · مستوى '+L;
  let sub=d.d;
  if(b.buried)sub='مدفون تحت الرمل! ما يشتغل لين تحفره أو تنقله.';
  else if(b.up)sub='يترقى... باقي '+fmtT((b.up.end-now())/1000);
  else if(d.rate)sub=`ينتج ${(d.rate[L-1]*3600*tribeBonus()*evProd(b.t)*decoB()*wxProd(b.t)*seasonProd()|0).toLocaleString('en-US')} بالساعة · فيه ${b.stock|0}/${d.cap[L-1]}`;
  else if(d.house)sub=`سعة الجيش ${d.house[L-1]}`;
  else if(d.dmg&&b.t!=='trap')sub=`ضرر ${d.dmg[L-1]} · مدى ${d.range}`;
  $('#selS').textContent=sub;
  const A=[];
  if(b.buried){const c=digCost(b);A.push(`<button class="btn y sm" id="aDig" ${S.gold<c?'disabled':''}><span data-art="shovel"></span>احفر · ${fmt(c)}<span data-art="coin"></span></button>`)}
  if(d.rate&&!b.buried&&!b.up)A.push(`<button class="btn g sm" id="aCol" ${b.stock<1?'disabled':''}>جمع</button>`);
  if(b.up){A.push(`<button class="btn p sm" id="aFin">إنهاء · ${gemsFor((b.up.end-now())/1000)}<span data-art="gem"></span></button>`)}
  else if(L<MAXL&&b.t!=='stable'&&!d.decor){const c=d.cost[L];const has=d.res==='g'?S.gold:S.water;const lock=L>=maxL;
    A.push(`<button class="btn sm" id="aUp" ${(has<c||lock)?'disabled':''}><span data-art="up"></span>${lock?'رقِّ القلعة أول':'ترقية · '+fmt(c)}${lock?'':`<span data-art="${d.res==='g'?'coin':'drop'}"></span>`}</button>`)}
  if(b.t==='barracks')A.push(`<button class="btn y sm" id="aTrain"><span data-art="v_w"></span>تدريب</button>`);
  if(b.t==='souq'&&!b.up)A.push(`<button class="btn y sm" id="aSouq"><span data-art="coin"></span>تبادل</button>`);
  if(b.t==='stable')A.push(`<button class="btn y sm" id="aHero"><span data-art="v_h"></span>الفارس</button>`);
  if(!b.up)A.push(`<button class="btn y sm" id="aMove"><span data-art="move"></span>نقل</button>`);
  $('#selA').innerHTML=A.join('');paintArt($('#selA'));
  const on=(id,f)=>{const e=document.getElementById(id);if(e)e.onclick=f};
  on('aDig',()=>{const c=digCost(b);if(S.gold<c)return;S.gold-=c;b.buried=false;b.dug=S.dune.side;snd('build');toast('حفرت '+d.n+'!');showSel();hud();save()});
  on('aCol',()=>collect(b));
  on('aFin',()=>{const g=gemsFor((b.up.end-now())/1000);if(S.gems<g){toast('تحتاج جواهر أكثر');snd('bad');return}S.gems-=g;b.up.end=now();villageTick(0);showSel();hud();save()});
  on('aUp',()=>startUpgrade(b));
  on('aTrain',trainSheet);on('aSouq',()=>souqSheet(b));on('aHero',heroSheet);
  on('aMove',()=>{place={t:b.t,x:b.x,y:b.y,move:b};$('#sel').classList.remove('on');$('#placebar').classList.add('on')});
  $('#sel').classList.add('on');
}
const digCost=b=>30*b.lvl*BT[b.t].s*BT[b.t].s;
function collect(b){const d=BT[b.t];const amt=Math.floor(b.stock);if(amt<1)return;
  if(b.t==='goldmine'){const room=capG()-S.gold;const g=Math.min(room,amt);if(g<=0){fullWarn('g');return}S.gold+=g;b.stock-=g;snd('coin');popAt(b,'+'+g,'#ffcb2b');stat('collectG',g);addXP(Math.ceil(g/100));{const [px,py]=proj(b.x+1,1.3,b.y+1);coinFly(px,py,'coin',Math.ceil(g/50))}}
  else{const room=capW()-S.water;const g=Math.min(room,amt);if(g<=0){fullWarn('w');return}S.water+=g;b.stock-=g;snd('water');popAt(b,'+'+g,'#8fdcff');stat('collectW',g);addXP(Math.ceil(g/100));{const [px,py]=proj(b.x+1,1.3,b.y+1);coinFly(px,py,'drop',Math.ceil(g/50))}}
  hud();if(selB===b)showSel();save()}
let _fw=0;function fullWarn(k){snd('bad');toast(k==='g'?'خزائن الذهب مليانة — ابنِ أو طوّر خزنة ذهب':'خزانات الموية مليانة — ابنِ أو طوّر خزان موية');const c=$(k==='g'?'#hG':'#hW').closest('.chip');c.classList.remove('bump');void c.offsetWidth;c.classList.add('bump')}
function startUpgrade(b){const d=BT[b.t],L=b.lvl;const c=d.cost[L];
  if(busy()>=2){toast('كل البنّائين مشغولين');snd('bad');return}
  if(d.res==='g'){if(S.gold<c)return;S.gold-=c}else{if(S.water<c)return;S.water-=c}
  const tm=Math.round(d.time[L]*evBuild());stat('upgrades');addXP(5+L*3);if(tm<=0){b.lvl++;snd('build');toast(d.n+' مستوى '+b.lvl);b._pop=performance.now()/1000}else{b.up={end:now()+tm*1000,dur:tm};snd('build')}
  showSel();hud();save()}
function popAt(b,s,col){const sz=BT[b.t].s;fx.push({k:'txt',gx:b.x+sz/2,gy:b.y+sz/2,s,col,t:0,dur:1.1})}

/* build shop */
let shopTab='موارد';
function shopSheet(){
  const tabs=Object.keys(SHOP).map(k=>`<button data-k="${k}" class="${k===shopTab?'on':''}">${k}</button>`).join('');
  const cards=SHOP[shopTab].map(t=>{const d=BT[t];const lim=LIM[t][cl()-1];const have=count(t);const c=d.cost[0];const can=(d.res==='g'?S.gold:S.water)>=c&&have<lim;
    return `<button class="card ${can?'':'no'}" data-t="${t}"><span class="lim">${have}/${lim}</span><canvas data-prev="${t}" width="200" height="166"></canvas><b>${d.n}</b><small>${lim===0?'تفتح مع القلعة '+(LIM[t].findIndex(x=>x>0)+1):''}</small><span class="cost ${d.res==='g'?'gold':'water'}">${fmt(c)}<span data-art="${d.res==='g'?'coin':'drop'}"></span></span></button>`}).join('');
  openSheet('بناء',`<div class="tabs-in">${tabs}</div><div class="grid">${cards}</div><p class="note" style="margin-top:12px">مستوى القلعة ${cl()} يحدد كم مبنى تقدر تبني ووش أعلى مستوى لها.</p>`);
  $('#sheetBody').querySelectorAll('[data-k]').forEach(e=>e.onclick=()=>{shopTab=e.dataset.k;snd('tap');shopSheet()});
  $('#sheetBody').querySelectorAll('[data-prev]').forEach(c=>previewBuilding(c,c.dataset.prev));
  $('#sheetBody').querySelectorAll('[data-t]').forEach(e=>e.onclick=()=>{const t=e.dataset.t,d=BT[t];
    if(count(t)>=LIM[t][cl()-1]){toast(LIM[t][cl()-1]?'وصلت الحد. رقِّ القلعة':'يحتاج مستوى قلعة أعلى');snd('bad');return}
    if((d.res==='g'?S.gold:S.water)<d.cost[0]){toast('ما عندك '+(d.res==='g'?'ذهب':'موية')+' كفاية');snd('bad');return}
    if(d.time[0]>0&&busy()>=2){toast('كل البنّائين مشغولين');snd('bad');return}
    closeSheet();const [gx,gy]=s2w(W/2,H/2);place={t,x:Math.round(gx-d.s/2),y:Math.round(gy-d.s/2),move:null};findFree();selB=null;showSel();$('#placebar').classList.add('on');snd('tap')});
}
function findFree(){const s=BT[place.t].s;const ok=(x,y)=>inGrid(x,y,s)&&!occupied(x,y,s,place.move)&&!inDune(x,y,s);if(ok(place.x,place.y))return;
  for(let r=1;r<N;r++)for(let dx=-r;dx<=r;dx++)for(let dy=-r;dy<=r;dy++){if(ok(place.x+dx,place.y+dy)){place.x+=dx;place.y+=dy;return}}}
function previewBuilding(c,t){const g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);try{g.drawImage(prevRender(buildFull(t,1,{nb:{x:true}}),c.width/2,c.height/2),0,0,c.width,c.height)}catch(e){}}
/* army */
function trainSheet(){
  const b=S.b.find(b=>b.t==='barracks');const bl=b?b.lvl:0;const cap=house(),used=armySpace();
  const q=S.queue.map((x,i)=>{const p=i===0&&x.end?1-(x.end-now())/(TR[x.t].time*1000):0;return `<div class="qi">${art('v_'+x.t)}${i===0?`<i><u style="width:${Math.max(0,Math.min(1,p))*100}%"></u></i>`:''}</div>`}).join('');
  const have=TROOPS.filter(k=>S.army[k]).map(k=>`<div class="qi">${art('v_'+k)}<span>${S.army[k]}</span></div>`).join('');
  const cards=TROOPS.map(k=>{const t=TR[k];const lock=bl<t.bl;const can=!lock&&S.water>=t.cost&&used+t.space<=cap;
    return `<button class="card ${can?'':'no'}" data-tr="${k}"><span class="lim" dir="rtl">مكان ${t.space} · م${S.tlv[k]}</span><span style="font-size:58px;line-height:1">${art('v_'+k)}</span><b>${t.n}</b><small>${lock?'يفتح مع معسكر '+t.bl:t.d}</small><span class="cost water">${t.cost}${art('drop')}</span></button>`}).join('');
  const sc=spellCap(),su=spellCount();
  const spc=Object.keys(SPL).map(k=>{const p=SPL[k];const can=S.water>=p.cost&&su<sc;return `<button class="card sp ${can?'':'no'}" data-sp="${k}"><span class="lim">عندك ${S.spells[k]}</span><span style="font-size:58px;line-height:1">${art(k)}</span><b>${p.n}</b><small>${p.d}</small><span class="cost water">${p.cost}${art('drop')}</span></button>`}).join('');
  const ups=TROOPS.filter(k=>bl>=TR[k].bl).map(k=>{const L=S.tlv[k],max=Math.min(MAXL,cl()+1),c=tCost(k);return `<div class="row"><div class="ri">${art('v_'+k)}</div><div class="rt"><b>${TR[k].n} · مستوى ${L}</b><small>صحة وضرر +${Math.round((tMul(k)-1)*100)}%</small></div><button class="btn sm" data-tu="${k}" ${(L>=max||S.gold<c)?'disabled':''}>${L>=MAXL?'الأعلى':L>=max?'رقِّ القلعة':fmt(c)+art('coin')}</button></div>`}).join('');
  openSheet('الجيش',`<div class="row" style="margin-bottom:8px"><div class="rt"><b>المساحة ${used}/${cap}</b><div class="bar w"><i style="width:${used/cap*100}%"></i></div></div></div>
    <small style="font-weight:800;color:var(--muted)">جيشك الجاهز</small><div class="qrow">${have||'<small style="font-weight:700;color:var(--muted);padding:12px">ما عندك جنود</small>'}</div>
    <small style="font-weight:800;color:var(--muted)">قيد التدريب</small><div class="qrow">${q||'<small style="font-weight:700;color:var(--muted);padding:12px">فاضي</small>'}</div>
    <div class="grid">${cards}</div>${S.queue.length?`<button class="btn p" id="finQ" style="width:100%;margin-top:12px">خلّص التدريب الحين · ${gemsFor(S.queue.reduce((s,x,i)=>s+(i===0&&x.end?(x.end-now())/1000:TR[x.t].time),0))}${art('gem')}</button>`:''}
    <h4 class="sec">التعاويذ · ${su}/${sc}</h4><div class="grid">${spc}</div>
    <h4 class="sec">تطوير الجنود</h4>${ups}`);
  $('#sheetBody').querySelectorAll('[data-tr]').forEach(e=>e.onclick=()=>{const k=e.dataset.tr,t=TR[k];
    if(bl<t.bl){toast('رقِّ المعسكر لمستوى '+t.bl);snd('bad');return}
    if(armySpace()+t.space>house()){toast('المعسكر مليان');snd('bad');return}
    if(S.water<t.cost){toast('ما عندك موية كفاية');snd('bad');return}
    S.water-=t.cost;S.queue.push({t:k,end:0});stat('trained');snd('tap');hud();trainSheet();save()});
  $('#sheetBody').querySelectorAll('[data-sp]').forEach(e=>e.onclick=()=>{const k=e.dataset.sp,p=SPL[k];
    if(spellCount()>=spellCap()){toast('وصلت حد التعاويذ');snd('bad');return}if(S.water<p.cost){toast('ما عندك موية كفاية');snd('bad');return}
    S.water-=p.cost;S.spells[k]++;snd('water');hud();trainSheet();save()});
  $('#sheetBody').querySelectorAll('[data-tu]').forEach(e=>e.onclick=()=>{const k=e.dataset.tu,c=tCost(k);if(S.gold<c)return;S.gold-=c;S.tlv[k]++;snd('win');addXP(10);toast(TR[k].n+' صار مستوى '+S.tlv[k]);hud();trainSheet();save()});
  const f=$('#finQ');if(f)f.onclick=()=>{const g=gemsFor(S.queue.reduce((s,x,i)=>s+(i===0&&x.end?(x.end-now())/1000:TR[x.t].time),0));if(S.gems<g){toast('تحتاج جواهر أكثر');return}S.gems-=g;S.queue.forEach(x=>S.army[x.t]++);S.queue=[];snd('win');hud();trainSheet();save()};
}

/* tribe */
function tribeSheet(){const need=500*S.tribe.lvl;
  openSheet('القبيلة',`<div class="row"><div class="ri">${art('tent')}</div><div class="rt"><b>بئر القبيلة · مستوى ${S.tribe.lvl}</b><small>كل مستوى يزيد إنتاج مناجمك وآبارك 4%. البونص الحالي: +${Math.round((tribeBonus()-1)*100)}%</small><div class="bar w"><i style="width:${S.tribe.xp/need*100}%"></i></div><small>${S.tribe.xp|0}/${need}</small></div></div>
    <div class="note">أعضاء القبيلة يتبرعون بالموية للبئر بشكل تلقائي، وكل ما كبر البئر استفاد الكل. في هالنموذج أعضاء القبيلة شخصيات آلية للتجربة.</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><button class="btn sm" id="don1" ${S.water<200?'disabled':''}>تبرّع 200${art('drop')}</button><button class="btn sm" id="don2" ${S.water<1000?'disabled':''}>تبرّع 1000${art('drop')}</button></div>
    <div class="members">${S.tribe.mem.slice().sort((a,b)=>b.c-a.c).map(m=>`<div><span>${esc(m.n)}</span><span>${fmt(m.c)}</span></div>`).join('')}<div style="background:#ffe07a"><span>أنت</span><span>${fmt(S.tribe.me||0)}</span></div></div>`);
  const don=a=>{if(S.water<a)return;S.water-=a;S.tribe.me=(S.tribe.me||0)+a;addTribeXp(a);snd('water');hud();tribeSheet();save()};
  $('#don1').onclick=()=>don(200);$('#don2').onclick=()=>don(1000)}

/* ================= BATTLE ================= */
let BB=null;
const fx=[];
function genBase(L){
  const bl=[];const occ=(x,y,s)=>bl.some(b=>{const bs=BT[b.t].s;return x<b.x+bs&&x+s>b.x&&y<b.y+bs&&y+s>b.y});
  const put=(t,x,y,l)=>{const d=BT[t];const lv=Math.max(1,Math.min(MAXL,l||ri(Math.max(1,L-1),L)));bl.push({t,x,y,lvl:lv,hp:d.hp[lv-1],maxhp:d.hp[lv-1],cd:rnd(0,1)})};
  const tryPut=(t,x0,y0,x1,y1)=>{const s=BT[t].s;for(let k=0;k<60;k++){const x=ri(x0,x1-s),y=ri(y0,y1-s);if(inGrid(x,y,s)&&!occ(x,y,s)){put(t,x,y);return true}}return false};
  const cxp=ri(9,10),cyp=ri(9,10);put('castle',cxp,cyp,L);
  const def=[['archer',LIM.archer[L-1]],['catapult',LIM.catapult[L-1]],['firetower',LIM.firetower[L-1]]];
  def.forEach(([t,n])=>{for(let i=0;i<n;i++)tryPut(t,6,6,16,16)});
  for(let i=0;i<LIM.goldstore[L-1];i++)tryPut('goldstore',6,6,16,16);
  for(let i=0;i<LIM.waterstore[L-1];i++)tryPut('waterstore',6,6,16,16);
  // wall ring
  const r0=5,r1=16;const wl=WALLC.length;const wlv=Math.max(1,Math.min(MAXL,L));
  for(let i=r0;i<=r1;i++){[[i,r0],[i,r1],[r0,i],[r1,i]].forEach(([x,y])=>{if(!occ(x,y,1)&&Math.random()>.08)put('wall',x,y,wlv)})}
  for(let i=0;i<LIM.goldmine[L-1];i++)tryPut('goldmine',1,1,21,21);
  for(let i=0;i<LIM.well[L-1];i++)tryPut('well',1,1,21,21);
  tryPut('barracks',1,1,21,21);
  for(let i=0;i<LIM.trap[L-1]+1;i++)tryPut('trap',5,5,17,17);
  return bl;
}
function startScout(kind,o){o=o||{};
  closeMap(true);closeSheet();closeModal();selB=null;selO=null;showSel();
  const L=o.L||Math.max(1,Math.min(MAXL,cl()+ri(-1,1)));
  const fal=S.b.find(b=>b.t==='falcon'&&!b.buried);
  BB={kind,L,camp:o.camp,clock:0,spells:[],sp:{...S.spells},spInit:{...S.spells},heroOut:false,nakhwa:false,raiders:[],name:o.name||(kind==='base'?pick(ENEMY_NAMES):'قافلة '+pick(['تجار الشام','تجار الدهناء','أهل الأحساء','ركب الغروب','حجاج اليمن'])),bld:[],units:[],en:[],proj:[],time:180,started:false,ended:false,
    left:{...S.army},init:{...S.army},sel:null,revealUntil:0,falcon:fal?BT.falcon.scout[fal.lvl-1]:0,gotG:0,gotW:0,stars:0,pct:0,dep:0,destroyedCastle:false};
  if(kind==='base'){BB.bld=genBase(L);addGuards(BB);BB.availG=o.g||ri(800,1500)*L;BB.availW=o.w||ri(800,1500)*L;
    const lootable=BB.bld.filter(b=>['goldstore','waterstore','goldmine','well','castle'].includes(b.t));
    lootable.forEach(b=>{const w=b.t==='castle'?.15:(b.t.includes('store')?.6/Math.max(1,BB.bld.filter(x=>x.t.includes('store')).length):.25/Math.max(1,BB.bld.filter(x=>x.t==='goldmine'||x.t==='well').length));
      b.lg=(b.t==='waterstore'||b.t==='well')?0:BB.availG*w*(b.t.includes('store')?2:1);b.lw=(b.t==='goldstore'||b.t==='goldmine')?0:BB.availW*w*(b.t.includes('store')?2:1);if(b.t==='castle'){b.lg=BB.availG*.15;b.lw=BB.availW*.15}});
    BB.total=BB.bld.filter(b=>b.t!=='wall'&&b.t!=='trap').length;
  } else {
    // caravan path
    const pts=[[-2,ri(4,8)],[ri(6,9),ri(3,8)],[ri(11,14),ri(12,17)],[ri(16,19),ri(6,12)],[N+2,ri(12,18)]];BB.path=pts;
    let len=0;BB.seg=[];for(let i=0;i<pts.length-1;i++){const d=Math.hypot(pts[i+1][0]-pts[i][0],pts[i+1][1]-pts[i][1]);BB.seg.push(d);len+=d}BB.len=len;
    const nC=4+Math.min(3,L-1);BB.availG=0;BB.availW=0;const evc=evOn('car')?2:1;
    for(let i=0;i<nC;i++){const hp=380*L;const lg=ri(150,300)*L*evc,lw=ri(200,380)*L*evc;BB.availG+=lg;BB.availW+=lw;BB.en.push({t:'camel',off:-i*1.5-1,hp,maxhp:hp,lg,lw,x:0,y:0,walk:0,moving:true,box:pick(['#e8443a','#2f8ee8','#8a52d6','#ffcb2b'])})}
    [0.6,-nC*1.5-.6,-nC*.75].forEach(off=>{const hp=220*L;BB.en.push({t:'guard',off,hp,maxhp:hp,x:0,y:0,cd:0,walk:0,moving:true})});
    BB.prog=0;BB.speed=.55+L*.03;BB.total=nC;
    BB.bld=[];[['wall',0]].length;
    // scatter rocks as obstacles (decor only)
  }
  computeBlocked();
  mode='scout';$('#vhud').hidden=true;$('#bhud').classList.add('on');renderBattleHud();centerOn(N/2,N/2,.82);clampCam();
}
function computeBlocked(){const st=new Set();if(BB.kind==='base'){BB.bld.forEach(b=>{if(b.t==='trap'||b.dead)return;const s=BT[b.t].s;for(let x=b.x-1;x<b.x+s+1;x++)for(let y=b.y-1;y<b.y+s+1;y++)if(x>=0&&y>=0&&x<N&&y<N)st.add(y*N+x)})}BB.blocked=st}
function pathPos(d){if(d<0)return [...BB.path[0]];let i=0;while(i<BB.seg.length&&d>BB.seg[i]){d-=BB.seg[i];i++}if(i>=BB.seg.length)return [...BB.path[BB.path.length-1]];const a=BB.path[i],b=BB.path[i+1],f=d/BB.seg[i];return [a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f]}

function renderBattleHud(){
  const B=BB;const def=B.kind==='defense';
  $('#bInfo').innerHTML=def?`<b>غزاة ${esc(B.name)}</b><div class="lr">${art('swords')} 3 موجات</div>`:`<b>${esc(B.name)}</b><div class="lr">${art(B.kind==='caravan'?'caravan':'castle')} مستوى ${B.L}${B.camp!=null?' · مرحلة '+(B.camp+1):''}</div>`;
  $('#bLoot').innerHTML=def?`<div class="lr">${art('swords')}<b>0</b></div><small>غزاة باقين</small>`:`<div class="lr">${art('coin')}<b>0</b></div><div class="lr">${art('drop')}<b>0</b></div><small>متاح للنهب</small>`;
  updateBattleTop();
  if(mode==='scout'){
    $('#bTroops').innerHTML='';$('#bEnd').hidden=true;
    $('#scoutBar').innerHTML=`<button class="btn r" id="sBack">رجوع</button>${B.kind==='base'&&B.camp==null?`<button class="btn y" id="sNext">التالي · ${50*cl()}${art('coin')}</button>`:''}<button class="btn g" id="sGo">${B.falcon?art('falcon')+' أطلق الصقر وهاجم':'هاجم!'}</button>`;
    $('#sBack').onclick=()=>{toVillage()};
    const n=$('#sNext');if(n)n.onclick=()=>{const c=50*cl();if(S.gold<c){toast('ما عندك ذهب');return}S.gold-=c;snd('tap');startScout('base')};
    $('#sGo').onclick=beginBattle;return}
  $('#scoutBar').innerHTML='';$('#bEnd').hidden=false;
  if(B.replay){$('#bEnd').hidden=true;$('#bTroops').innerHTML=`<div class="rpbar"><span class="rp-l">${art('play')} إعادة</span>${[1,2,4].map(v=>`<button class="btn sm ${(B.speed||1)===v?'y':''}" data-spd="${v}">×${v}</button>`).join('')}<button class="btn r sm" id="rpX">خروج</button></div>`;
    $('#bTroops').querySelectorAll('[data-spd]').forEach(e=>e.onclick=()=>{B.speed=+e.dataset.spd;snd('tap');renderBattleHud()});$('#rpX').onclick=()=>{snd('tap');toVillage()};return}$('#bEnd').textContent=def?'استسلم':'إنهاء المعركة';
  const ks=TROOPS.filter(k=>B.init[k]>0);
  if(B.sel==null||(B.sel!=='h'&&B.sel!=='fz'&&B.sel!=='aim'&&!B.sel.startsWith('s:')&&!B.left[B.sel])||(B.sel==='h'&&B.heroOut)||(B.sel.startsWith('s:')&&!B.sp[B.sel.slice(2)]))B.sel=ks.find(k=>B.left[k]>0)||(!B.heroOut?'h':null);
  const cards=[];
  if(!B.heroOut)cards.push(`<button class="tcard hero ${B.sel==='h'?'on':''}" data-k="h"><span class="n">${S.hero.lvl}</span>${art('v_h')}الفارس</button>`);
  else if(!B.nakhwa&&B.units.some(u=>u.t==='h'&&!u.dead))cards.push(`<button class="tcard ab" data-ab="1">${art('shout')}النخوة</button>`);
  if(mode==='battle')cards.push(`<button class="tcard aim ${B.sel==='aim'?'on':''}" data-k="aim">${art('swords')}وجّه</button>`);
  if(B.kind!=='defense'&&!B.fzOut&&S.fz.list.length)cards.push(`<button class="tcard fz ${B.sel==='fz'?'on':''}" data-k="fz"><span class="n">${S.fz.list.length}</span>${art('tent')}الفزعة</button>`);
  ks.forEach(k=>cards.push(`<button class="tcard ${B.sel===k?'on':''} ${B.left[k]?'':'zero'}" data-k="${k}"><span class="n">${B.left[k]}</span>${art('v_'+k)}${TR[k].n}</button>`));
  Object.keys(SPL).forEach(k=>{if(B.spInit[k]>0)cards.push(`<button class="tcard sp ${B.sel==='s:'+k?'on':''} ${B.sp[k]?'':'zero'}" data-k="s:${k}"><span class="n">${B.sp[k]}</span>${art(k)}${SPL[k].n}</button>`)});
  $('#bTroops').innerHTML=cards.join('')||'<div class="bcard">ما عندك جنود ولا تعاويذ.</div>';
  $('#bTroops').querySelectorAll('[data-k]').forEach(e=>e.onclick=()=>{const k=e.dataset.k;if(k.startsWith('s:')&&!B.sp[k.slice(2)])return;if(!k.startsWith('s:')&&k!=='h'&&k!=='fz'&&k!=='aim'&&!B.left[k])return;if(k==='aim')toast(B.kind==='defense'?'اضغط على الغازي اللي تبي جيشك يضربه':'اضغط على المبنى اللي تبي جيشك يضربه');B.sel=k;snd('tap');renderBattleHud()});
  const ab=$('#bTroops').querySelector('[data-ab]');if(ab)ab.onclick=nakhwa;
}
function updateBattleTop(){const B=BB;if(!B)return;const tt=Math.max(0,B.time),m=Math.floor(tt/60),s=Math.floor(tt%60);
  $('#bTime').textContent=(mode==='scout'?'استطلاع':m+':'+String(s).padStart(2,'0'));
  $('#bStars').innerHTML=[0,1,2].map(i=>`<span class="${i<B.stars?'':'off'}">${art('star')}</span>`).join('');
  const bs=$('#bLoot').querySelectorAll('b');
  if(B.kind==='defense'){$('#bPct').textContent='الضرر '+Math.floor(B.pct)+'%';const left=B.raiders.filter(r=>!r.dead).length+B.waves.filter(w=>!w.done).reduce((a,w)=>a+w.list.length,0);if(bs[0])bs[0].textContent=left;return}
  $('#bPct').textContent=(B.kind==='caravan'?(B.killed||0)+'/'+B.total+' جمال':Math.floor(B.pct)+'%');
  if(bs[0])bs[0].textContent=fmt(B.availG-B.gotG);if(bs[1])bs[1].textContent=fmt(B.availW-B.gotW)}
function beginBattle(){
  const B=BB;
  mode='battle';B.started=true;bigText(B.kind==='caravan'?'اكمن!':'هجوم!');
  if(B.falcon){B.revealUntil=now()+B.falcon*1000;const traps=B.bld.filter(b=>b.t==='trap').length;fx.push({k:'falcon',t:0,dur:2.2});banner('falcon','الصقر طار!',B.kind==='base'?`كشف ${traps} فخاخ لمدة ${B.falcon} ثانية. شوفها زين قبل لا تختفي.`:'الصقر يراقب القافلة من فوق.');snd('win')}
  renderBattleHud();
}
function deployAt(gx,gy){
  const B=BB;if(mode!=='battle'||B.ended)return;const k=B.sel;if(!k)return;
  if(gx<-3||gy<-3||gx>N+3||gy>N+3){fx.push({k:'no',gx,gy,t:0,dur:.6});return 'no'}
  if(k.startsWith('s:')){const sk=k.slice(2);if(!B.sp[sk])return;B.sp[sk]--;S.spells[sk]--;stat('spells');B.spells.push({k:sk,x:gx,y:gy,t:0});snd(sk==='storm'?'boom':'water');B.sel=null;renderBattleHud();return 'spell'}
  const tx=Math.floor(gx),ty=Math.floor(gy);if(B.kind!=='defense'&&B.blocked.has(ty*N+tx)){fx.push({k:'no',gx,gy,t:0,dur:.6});return 'no'}
  if(k==='h'){if(B.heroOut)return;B.heroOut=true;const hp=TR.h.hp*heroMul()*(typeof gearM==='function'?gearM('sh'):1);B.units.push({t:'h',x:gx,y:gy,hp,maxhp:hp,dmg:TR.h.dmg*heroMul()*(typeof gearM==='function'?gearM('sw'):1),cd:0,tgt:null,walk:0,moving:false,hero:1});B.dep++;
    snd('win');fx.push({k:'puff',gx,gy,t:0,dur:.4});fx.push({k:'txt',gx,gy,s:'الفارس!',col:'#ffcb2b',t:0,dur:1.2});shake(.15);B.sel=null;renderBattleHud();return}
  if(!B.left[k])return;
  const t=TR[k];B.left[k]--;S.army[k]--;B.dep++;const mu=tMul(k);
  B.units.push({t:k,x:gx,y:gy,hp:t.hp*mu,maxhp:t.hp*mu,dmg:t.dmg*mu,cd:0,tgt:null,walk:0,moving:false});snd('deploy');
  fx.push({k:'puff',gx,gy,t:0,dur:.4});
  if(!B.left[k]){renderBattleHud()}else{const n=$('#bTroops').querySelector(`[data-k="${k}"] .n`);if(n)n.textContent=B.left[k]}
}
const bcen=b=>{const s=BT[b.t].s;return [b.x+s/2,b.y+s/2]};
function nearestPt(b,x,y){const s=BT[b.t].s;return [Math.max(b.x,Math.min(b.x+s,x)),Math.max(b.y,Math.min(b.y+s,y))]}
function pickTarget(u){
  const B=BB;
  if(B.kind==='caravan'){let best=null,bd=1e9;B.en.forEach(e=>{if(e.dead||e.escaped||e.off+B.prog<0)return;const d=Math.hypot(e.x-u.x,e.y-u.y);if(d<bd){bd=d;best=e}});return best}
  const pref=TR[u.t].pref;let pool=B.bld.filter(b=>!b.dead&&b.t!=='trap'&&b.t!=='wall');
  if(pref){const p=B.bld.filter(b=>!b.dead&&pref.includes(b.t));if(p.length)pool=p}
  if(!pool.length)pool=B.bld.filter(b=>!b.dead&&b.t!=='trap');
  let best=null,bd=1e9;pool.forEach(b=>{const [px,py]=nearestPt(b,u.x,u.y);const d=Math.hypot(px-u.x,py-u.y);if(d<bd){bd=d;best=b}});return best}
function wallAt(x,y){const tx=Math.floor(x),ty=Math.floor(y);return BB.bld.find(b=>b.t==='wall'&&!b.dead&&b.x===tx&&b.y===ty)}
function damageB(b,dmg){if(b.dead)return;b.hp-=dmg;b._hit=performance.now()/1000;if(b.hp<=0){b.hp=0;b.dead=true;const B=BB;shake(.07*BT[b.t].s);fx.push({k:'boom',gx:bcen(b)[0],gy:bcen(b)[1],t:0,dur:.6,r:BT[b.t].s});snd('boom');
  if(b.lg||b.lw){const g=Math.floor(b.lg||0),w=Math.floor(b.lw||0);B.gotG+=g;B.gotW+=w;if(g)fx.push({k:'txt',gx:bcen(b)[0],gy:bcen(b)[1],s:'+'+fmt(g),col:'#ffcb2b',t:0,dur:1.2});if(w)fx.push({k:'txt',gx:bcen(b)[0]+.6,gy:bcen(b)[1]-.3,s:'+'+fmt(w),col:'#8fdcff',t:0,dur:1.2})}
  if(b.t==='castle')B.destroyedCastle=true;
  if(b.t!=='wall'&&b.t!=='trap'){const d=B.bld.filter(x=>x.dead&&x.t!=='wall'&&x.t!=='trap').length;B.pct=d/B.total*100}
  B.stars=(B.pct>=50?1:0)+(B.destroyedCastle?1:0)+(B.pct>=100?1:0);computeBlocked();updateBattleTop()}}
function damageU(u,dmg){if(u.dead)return;u.hp-=dmg;if(u.hp<=0){u.dead=true;fx.push({k:'ghost',gx:u.x,gy:u.y,t:0,dur:.8})}}
function damageE(e,dmg){if(e.dead)return;e.hp-=dmg;if(e.hp<=0){e.dead=true;const B=BB;fx.push({k:'boom',gx:e.x,gy:e.y,t:0,dur:.5,r:1});snd('boom');
  if(e.t==='camel'){B.gotG+=e.lg;B.gotW+=e.lw;B.killed=(B.killed||0)+1;fx.push({k:'txt',gx:e.x,gy:e.y,s:'+'+fmt(e.lg),col:'#ffcb2b',t:0,dur:1.2});fx.push({k:'txt',gx:e.x+.5,gy:e.y-.4,s:'+'+fmt(e.lw),col:'#8fdcff',t:0,dur:1.2});
    const k=B.killed/B.total;B.stars=k>=1?3:k>=.66?2:k>=.33?1:0;updateBattleTop()}}}
function battleTick(dt){
  const B=BB;if(mode!=='battle'||B.ended)return;
  B.time-=dt;B.clock+=dt;const def=B.kind==='defense';const att=def?B.raiders:B.units;
  if(def)B.waves.forEach((w,i)=>{if(!w.done&&B.clock>=w.at){w.done=true;spawnWave(w,i)}});
  if(B.kind==='caravan'){B.prog+=B.speed*dt;B.en.forEach(e=>{if(e.dead||e.escaped)return;const d=B.prog+e.off;const p=pathPos(d);e.walk+=dt;e.moving=true;e.x=p[0];e.y=p[1];if(d>B.len){e.escaped=true;if(e.t==='camel'){B.escaped=(B.escaped||0)+1;fx.push({k:'txt',gx:N,gy:p[1],s:'هربت!',col:'#ff8a7a',t:0,dur:1.4})}}});
    B.en.forEach(e=>{if(e.t!=='guard'||e.dead||e.escaped||B.prog+e.off<0)return;e.cd-=dt;if(e.cd<=0){let tg=null,bd=3.5;B.units.forEach(u=>{if(u.dead)return;const d=Math.hypot(u.x-e.x,u.y-e.y);if(d<bd){bd=d;tg=u}});if(tg){e.cd=1;B.proj.push({k:'arrow',x:e.x,y:e.y,u:tg,t:0,dur:.35,dmg:9*B.L,enemy:1});snd('shot')}}})}
  B.units.forEach(u=>{if(!u.dead){if(def)stepHeroDef(u,dt);else stepAttacker(u,dt)}});
  att.forEach(u=>{if(!u.dead&&(u.burn||0)>B.clock){damageU(u,6*dt*B.L);if(Math.random()<.2)P('sph','fire',u.x,groundY(u.x,u.y)+.5,u.y,0,1.5,0,.4,.08,0)}});
  if(def)B.raiders.forEach(u=>{if(!u.dead)stepAttacker(u,dt)});
  if(B.defs){guardTick(dt);B.defs.forEach(u=>{if(!u.dead)stepDefender(u,dt)})}
  spellTick(dt);
  if(B.kind!=='caravan')B.bld.forEach(b=>{if(b.dead)return;const d=BT[b.t];
    if(b.t==='trap'){const [tx,ty]=bcen(b);if(att.some(u=>!u.dead&&!TR[u.t].air&&Math.hypot(u.x-tx,u.y-ty)<.9)){att.forEach(u=>{if(!u.dead&&!TR[u.t].air&&Math.hypot(u.x-tx,u.y-ty)<1.6)damageU(u,d.dmg[b.lvl-1]*(B.trapM||1))});b.dead=true;fx.push({k:'boom',gx:tx,gy:ty,t:0,dur:.7,r:1.6});snd('boom');shake(.25);fx.push({k:'txt',gx:tx,gy:ty,s:'فخ!',col:'#ff8a7a',t:0,dur:1})}return}
    if(!d.range)return;b.cd-=dt;if(b.t==='catapult')b.arm=Math.max(0,(b.arm||0)-dt*2);
    if((b.stun||0)>B.clock)return;
    if(b.cd<=0){const [cx0,cy0]=bcen(b);let tg=null,bd=d.range*(B.rangeM||1);att.forEach(u=>{if(u.dead||!canHit(b.t,u))return;const dd=Math.hypot(u.x-cx0,u.y-cy0);if(dd<=bd&&dd>=(d.minr||0)){bd=dd;tg=u}});
      if(tg){b.cd=d.fire;if(b.t==='archer'){B.proj.push({k:'arrow',x:cx0,y:cy0,h:50,u:tg,t:0,dur:.4,dmg:d.dmg[b.lvl-1]*(B.dmgM||1)});snd('shot')}else if(b.t==='airdef'){B.proj.push({k:'spear',x:cx0,y:cy0,h:50,u:tg,t:0,dur:.35,dmg:d.dmg[b.lvl-1]*(B.dmgM||1)});snd('shot')}else if(b.t==='firetower'){B.proj.push({k:'fire',x:cx0,y:cy0,h:50,u:tg,t:0,dur:.55,dmg:d.dmg[b.lvl-1]*(B.dmgM||1),sp:d.splash});snd('shot')}else{b.arm=1.5;B.proj.push({k:'stone',x:cx0,y:cy0,tx:tg.x,ty:tg.y,t:0,dur:1,dmg:d.dmg[b.lvl-1]*(B.dmgM||1),sp:d.splash})}}}});
  B.proj.forEach(p=>{p.t+=dt;if(p.t>=p.dur&&!p.done){p.done=true;
    if(p.k==='fire'){const tx=p.u.x,ty=p.u.y;att.forEach(u=>{if(!u.dead&&Math.hypot(u.x-tx,u.y-ty)<p.sp){damageU(u,p.dmg);u.burn=B.clock+2.5}});fx.push({k:'boom',gx:tx,gy:ty,t:0,dur:.45,r:p.sp})}
    else if(p.k==='arrow'||p.k==='spear'){if(p.u)damageU(p.u,p.dmg);else if(p.tgt){B.kind==='caravan'?damageE(p.tgt,p.dmg):damageB(p.tgt,p.dmg)}}
    else if(p.k==='stone'){att.forEach(u=>{if(!u.dead&&Math.hypot(u.x-p.tx,u.y-p.ty)<p.sp)damageU(u,p.dmg)});fx.push({k:'boom',gx:p.tx,gy:p.ty,t:0,dur:.5,r:p.sp});snd('boom')}}});
  B.proj=B.proj.filter(p=>!p.done);
  let over=B.time<=0;
  if(def){if(B.destroyedCastle||B.pct>=50)over=true;if(B.waves.every(w=>w.done)&&!B.raiders.some(r=>!r.dead))over=true}
  else{const alive=B.units.some(u=>!u.dead&&!TR[u.t].heal),left=Object.keys(B.left).some(k=>B.left[k]>0&&!TR[k].hero)||!B.heroOut||(B.kind!=='defense'&&!B.fzOut&&S.fz.list.length>0);if(B.dep>0&&!alive&&!left)over=true;if(B.kind==='base'&&B.pct>=100)over=true;if(B.kind==='caravan'&&B.en.filter(e=>e.t==='camel').every(e=>e.dead||e.escaped))over=true}
  if(over){B.ended=true;if(!B.headless){const w=B.kind==='defense'?(!B.surrender&&!B.destroyedCastle&&B.pct<50):B.stars>0;if(w&&!B.replay)celebrate();setTimeout(endBattle,w&&!B.replay?2400:1200)}}
  if(Math.floor(B.time*4)!==Math.floor((B.time+dt)*4))updateBattleTop();
}
function endBattle(){
  const B=BB;if(!B||B.result)return;B.result=true;modalLock=true;if(B.replay){replayEnd(B);return}const _lg0=lgIdx();preBattleEnd(B);
  const home=()=>{postBattle(B,_lg0);const h=$('#rHome');if(h)h.onclick=()=>{modalLock=false;closeModal();toVillage()}};
  if(B.kind==='defense'){const win=!B.surrender&&!B.destroyedCastle&&B.pct<50;let g,w,tr;
    if(win){g=Math.max(0,Math.min(350*B.L+Math.floor(B.gotG),capG()-S.gold));w=Math.max(0,Math.min(350*B.L,capW()-S.water));S.gold+=g;S.water+=w;tr=ri(8,14);stat('defWins');addXP(30)}
    else{g=-Math.floor(S.gold*.12);w=-Math.floor(S.water*.12);S.gold+=g;S.water+=w;tr=-ri(6,10)}
    S.tro=Math.max(0,S.tro+tr);olEv('def',tr);snd(win?'win':'lose');musTo(win?'victory':'defeat');B.units.forEach(u=>{if(u.dfd&&!u.dead)S.army[u.t]=(S.army[u.t]||0)+1});
    if(B.rec){Object.assign(B.rec,{pct:Math.floor(B.pct),win,lg:Math.max(0,-g),lw:Math.max(0,-w),tr,castle:B.destroyedCastle,seen:true});S.raidLog.unshift(B.rec);S.raidLog=S.raidLog.slice(0,6);S.fz.list=B.units.filter(u=>u.fz&&!u.dead).map(u=>u.t)}
    const sg=v=>'<bdi>'+(v>0?'+':v<0?'-':'')+fmt(Math.abs(v))+'</bdi>';
    openModal(`<div class="mhead ${win?'win':'lose'}"><h3>${win?'صدّيت الغزاة!':'الغزاة اخترقوا قلعتك'}</h3></div><div class="mi">${art(win?'shield':'swords')}</div>
      <p>${win?'دفاعاتك والفارس ردّوهم، وغنمت من عتادهم:':'دمّروا '+Math.floor(B.pct)+'% من قلعتك ونهبوا من خزائنك:'}</p>
      <div class="loot"><span>${art('coin')}${sg(g)}</span><span>${art('drop')}${sg(w)}</span><span>${art('trophy')}<bdi>${tr>0?'+':''}${tr}</bdi></span></div>
      <p class="note">مبانيك الحقيقية ما تتضرر، بس الغنيمة والكؤوس تتغير حسب النتيجة.</p><div class="mb">${B.rec?`<button class="btn p" id="rpW2">${art('play')} الإعادة</button>`:''}<button class="btn g" id="rHome">رجوع للقلعة</button></div>`);
    home();const rw=$('#rpW2');if(rw)rw.onclick=()=>{postBattle(B,_lg0);modalLock=false;closeModal();const r=B.rec;toVillage();startReplay(r)};save();return}
  const g=Math.max(0,Math.min(Math.floor(B.gotG),capG()-S.gold)),w=Math.max(0,Math.min(Math.floor(B.gotW),capW()-S.water));S.gold+=g;S.water+=w;
  const win=B.stars>0;let tr=0,bonus=0,extra='';
  if(B.camp!=null){const i=B.camp,prev=S.camp.stars[i]||0;S.camp.stars[i]=Math.max(prev,B.stars);if(prev===0&&B.stars>0)bonus+=5;if(prev<3&&B.stars===3)bonus+=10;if(bonus){S.gems+=bonus;extra=`<p class="note">مكافأة الحملة: ${bonus} ${art('gem')}</p>`}}
  else if(B.vf||B.noTro){tr=0}else{tr=win?Math.round((B.stars*8+ri(0,4))*(evOn('war')?1.5:1)):-ri(6,12);S.tro=Math.max(0,S.tro+tr);olEv('atk',tr,B.stars)}
  if(win){stat('wins');addXP(10+B.stars*8)}
  if(B.kind==='caravan')stat('camels',B.killed||0);
  snd(win?'win':'lose');musTo(win?'victory':'defeat');
  const nextC=B.camp!=null&&win&&B.camp+1<CAMP.length;
  openModal(`<div class="mhead ${win?'win':'lose'}"><h3>${win?'انتصار!':'هزيمة'}</h3></div>
    <div class="big-stars">${[0,1,2].map(i=>`<span class="${i<B.stars?'':'off'}">${art('star')}</span>`).join('')}</div>
    <p>${B.kind==='caravan'?`نهبت ${B.killed||0} من ${B.total} جمال${B.escaped?' وهرب '+B.escaped:''}`:`دمّرت ${Math.floor(B.pct)}% من ${esc(B.name)}`}</p>
    <div class="loot"><span>${art('coin')}${fmt(g)}</span><span>${art('drop')}${fmt(w)}</span>${B.camp==null?`<span>${art('trophy')}<bdi${B.vf?' id="vfTr"':''}>${tr>0?'+':''}${tr}</bdi></span>`:''}</div>
    ${extra}${(B.gotG>g+1||B.gotW>w+1)?'<p class="note">خزائنك ما وسعت كل الغنيمة. رقِّ الخزائن.</p>':''}
    <div class="mb">${nextC?'<button class="btn y" id="rNext">المرحلة الجاية</button>':''}<button class="btn g" id="rHome">رجوع للقلعة</button></div>`);
  home();const rn=$('#rNext');if(rn)rn.onclick=()=>{modalLock=false;closeModal();toVillage();startCampaign(B.camp+1)};
  save();
}
function toVillage(){mode='village';BB=null;fx.length=0;$('#bhud').classList.remove('on');$('#vhud').hidden=false;centerOn(10.5,10.5,VZ());clampCam();hud();save();if(backToMap){backToMap=false;openMap()}}

/* ================= FEATURES ================= */
/* --- progression --- */
const xpNeed=l=>Math.round(60*Math.pow(l,1.5));
function stat(k,n){S.st[k]=(S.st[k]||0)+(n==null?1:n)}
function addXP(n){S.xp+=n;let up=false;while(S.xp>=xpNeed(S.plv)){S.xp-=xpNeed(S.plv);S.plv++;S.gems+=5;up=true}
  if(up){banner('star','مستواك صار '+S.plv+'!','جاتك 5 جواهر. كمّل كذا.');snd('win');if(mode==='village')confettiAt(cam.tx,cam.tz)}}
function migrate(){S.xp=S.xp||0;S.plv=S.plv||1;S.st=S.st||{};S.claimed=S.claimed||[];S.daily=S.daily||{day:'',streak:0};S.camp=S.camp||{stars:[]};
  S.hero=S.hero||{lvl:1};S.spells=S.spells||{storm:1,heal:1};S.tlv=S.tlv||{w:1,a:1,c:1,k:1};if(S.music==null)S.music=true;
  if(!S.raid)S.raid={next:now()+150000,pend:0};
  if(!S.b.some(b=>b.t==='stable')){outer:for(let r=0;r<12;r++)for(let dx=-r;dx<=r;dx++)for(let dy=-r;dy<=r;dy++){const x=12+dx,y=12+dy;if(inGrid(x,y,2)&&!occupied(x,y,2)&&!inDune(x,y,2)){S.b.push(mk('stable',x,y));break outer}}}
  if(!S.obs){S.obs=[];for(let i=0;i<9;i++)spawnObs()}}
function spawnObs(){for(let k=0;k<60;k++){const x=ri(0,N-1),y=ri(0,N-1);if(!occupied(x,y,1)&&!inDune(x,y,1)&&(Math.abs(x-10.5)>3.5||Math.abs(y-10.5)>3.5)){S.obs.push({id:uid++,k:pick(['rock','rock','bush','palm']),x,y});return}}}

/* --- juice --- */
function coinFly(px,py,icon,n){try{const ch=$(icon==='drop'?'#hW':icon==='gem'?'#hGem':'#hG').closest('.chip');const tg=ch.querySelector('.ico').getBoundingClientRect();const ar=$('#app').getBoundingClientRect();
  const tx=tg.left-ar.left+tg.width/2,ty=tg.top-ar.top+tg.height/2;const k=Math.max(1,Math.min(6,n));const html=art(icon);
  for(let i=0;i<k;i++){const e=document.createElement('div');e.className='fly';e.innerHTML=html;const sx=px+rnd(-26,26),sy=py+rnd(-20,20);e.style.transform=`translate(${tx}px,${ty}px)`;$('#app').appendChild(e);
    const an=e.animate([{transform:`translate(${sx}px,${sy}px) scale(.7)`},{transform:`translate(${sx}px,${sy-18}px) scale(.9)`,offset:.25},{transform:`translate(${tx}px,${ty}px) scale(1)`}],{duration:620,delay:i*45,easing:'ease-in',fill:'backwards'});
    an.onfinish=()=>{e.remove();if(i===k-1){ch.classList.remove('bump');void ch.offsetWidth;ch.classList.add('bump')}};setTimeout(()=>e.remove(),1500)}}catch(e){}}
function confettiAt(x,z){for(let i=0;i<28;i++)P('box','c'+(1+i%4),x,1.8,z,rnd(-2.4,2.4),rnd(3,6.5),rnd(-2.4,2.4),1.7,.1,.07,{g:9,spin:9})}
function bigText(s){const e=$('#big');e.textContent=s;e.classList.remove('go');void e.offsetWidth;e.classList.add('go')}

/* --- music (procedural, Hijaz scale) --- */
let MUS=null;
function pluck(c,out,f,t,v){const o=c.createOscillator(),g=c.createGain(),lp=c.createBiquadFilter();o.type='sawtooth';o.frequency.value=f;lp.type='lowpass';lp.frequency.setValueAtTime(2600,t);lp.frequency.exponentialRampToValueAtTime(320,t+.35);
  g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(v||.5,t+.006);g.gain.exponentialRampToValueAtTime(.0001,t+.55);o.connect(lp).connect(g).connect(out);o.start(t);o.stop(t+.6)}
function drum(c,out,t,v,f){const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(f*1.8,t);o.frequency.exponentialRampToValueAtTime(f,t+.1);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(v,t+.004);g.gain.exponentialRampToValueAtTime(.0001,t+.22);o.connect(g).connect(out);o.start(t);o.stop(t+.25)}
function drone(c,out,f,t,d){const o=c.createOscillator(),g=c.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(.1,t+.6);g.gain.linearRampToValueAtTime(.0001,t+d);o.connect(g).connect(out);o.start(t);o.stop(t+d+.05)}
function musicStart(){if(MUS||!S.music)return;try{if(!AC)AC=new (window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();const c=AC;
  const master=c.createGain();master.gain.value=.1;master.connect(c.destination);
  const sc=[0,1,4,5,7,8,10];const base=146.83;const spb=60/104/2;let step=0,nextT=c.currentTime+.15;
  const pats=[[0,2,3,4,3,2,1,0,4,5,4,3,2,1,2,0],[4,5,7,8,7,5,4,3,2,3,4,5,4,2,1,0],[7,8,9,8,7,5,4,5,4,3,2,1,0,1,2,0],[0,1,0,2,3,4,3,2,1,2,1,0,-1,0,-1,0]];
  const note=d=>{const o=Math.floor(d/7),k=((d%7)+7)%7;return base*Math.pow(2,(sc[k]+12*o)/12)};
  MUS={master,timer:setInterval(()=>{if(!S.music)return;while(nextT<c.currentTime+.35){const i=step%16,bar=Math.floor(step/16)%4;const pat=pats[bar];
      if(i%2===0||Math.random()<.4)pluck(c,master,note(pat[i]),nextT,i%4===0?.55:.32);
      if(i%4===0)drum(c,master,nextT,i%8===0?.9:.55,i%8===0?75:170);else if(i%4===3&&Math.random()<.55)drum(c,master,nextT,.3,420);
      if(i===0)drone(c,master,base/2,nextT,spb*16);
      nextT+=spb;step++}},90)}}catch(e){}}
function musicStop(){if(MUS){clearInterval(MUS.timer);try{MUS.master.disconnect()}catch(e){}MUS=null}}

/* --- obstacles --- */
const OBS={rock:{n:'صخرة',c:80},bush:{n:'شجيرة يابسة',c:50},palm:{n:'نخلة برية',c:120}};
function obsMesh(k){const g=new THREE.Group();
  if(k==='rock'){const r=DO(g,.36,'#a8977e',0,.18,0);r.scale.set(1.1,.7,1);DO(g,.2,'#bba88e',.26,.1,.22)}
  else if(k==='bush'){for(let i=0;i<4;i++){const a=i*1.7;add(g,new THREE.IcosahedronGeometry(.17,0),M(i%2?'#9a7a4a':'#8a6a3a'),Math.cos(a)*.15,.15+i*.03,Math.sin(a)*.15)}
    for(let i=0;i<5;i++){const s=CY(g,.012,.012,.42,'#6b4a2a',0,.05,0,3);s.rotation.set(rnd(-.8,.8),0,rnd(-.8,.8))}}
  else palm(g,0,0,1.5,.3,0,true);
  return mergeStatic(g)}
function showObs(){const o=selO,d=OBS[o.k];$('#selT').textContent=d.n;$('#selS').textContent='أزلها عشان توسّع المكان، وتحتها جواهر.';
  $('#selA').innerHTML=`<button class="btn y sm" id="aRm" ${S.gold<d.c?'disabled':''}><span data-art="shovel"></span>أزل · ${fmt(d.c)}<span data-art="coin"></span></button>`;paintArt($('#selA'));
  $('#aRm').onclick=()=>removeObs(o);$('#sel').classList.add('on')}
function removeObs(o){const d=OBS[o.k];if(S.gold<d.c)return;S.gold-=d.c;S.obs=S.obs.filter(x=>x!==o);const gm=ri(1,3);S.gems+=gm;
  fx.push({k:'boom',gx:o.x+.5,gy:o.y+.5,t:0,dur:.5,r:.7});fx.push({k:'txt',gx:o.x+.5,gy:o.y+.5,s:'+'+gm+' جواهر',col:'#7dff8a',t:0,dur:1.3});
  const [px,py]=proj(o.x+.5,.8,o.y+.5);coinFly(px,py,'gem',gm*2);snd('coin');stat('obs');addXP(4);selO=null;showSel();hud();save()}

/* --- stable & hero --- */
function bStable(L){const g=new THREE.Group();BX(g,1.8,.05,1.8,'#cdb48a');
  for(let i=0;i<5;i++){const a=-.8+i*.4;BX(g,.07,.44,.07,WOOD,a,.05,-.82);BX(g,.07,.44,.07,WOOD,-.82,.05,a);BX(g,.07,.44,.07,WOOD,.82,.05,a)}
  BX(g,1.7,.05,.05,WOODD,0,.38,-.82);BX(g,.05,.05,1.7,WOODD,-.82,.38,0);BX(g,.05,.05,1.7,WOODD,.82,.38,0);BX(g,1.7,.05,.05,WOODD,0,.22,-.82);
  for(let i=0;i<5;i++)add(g,new THREE.IcosahedronGeometry(.16,0),M(i%2?'#e8c45a':'#d9b04a'),-.55+i*.12,.12,-.55+(i%2)*.1);
  BX(g,.6,.16,.22,WOODD,.45,.05,-.55);const wt=add(g,new THREE.PlaneGeometry(.52,.15),WATERM,.45,.22,-.55);wt.rotation.x=-Math.PI/2;
  const h=dyn(unitMesh('h'));h.position.set(0,.05,.12);h.rotation.y=.6;g.add(h);g.userData.hero=h;
  g.userData.flag=flag(g,-.75,.05,.75,'#b8322a',1.3);return g}
function heroSheet(){const L=S.hero.lvl,c=heroCost(),max=Math.min(16,cl()*2+1);
  openSheet('الفارس',`<canvas class="hero-prev" id="hPrev" width="400" height="400"></canvas>
    <div class="row"><div class="rt"><b>الفارس · مستوى ${L}</b><small>صحة ${Math.round(TR.h.hp*heroMul())} · ضرر ${Math.round(TR.h.dmg*heroMul())}</small><small>ينزل معك في كل معركة ببلاش، وفي الغارات يدافع عن قلعتك. قدرته "النخوة" تشفيه وتحمّس الجنود اللي حوله 8 ثواني.</small></div></div>
    <button class="btn g" id="hUp" style="width:100%" ${(S.gold<c||L>=max)?'disabled':''}>${L>=16?'وصل أعلى مستوى':L>=max?'رقِّ القلعة عشان تطوّره':'طوّر · '+fmt(c)+art('coin')}</button>`);
  try{const hm=unitMesh('h');hm.rotation.y=.5;$('#hPrev').getContext('2d').drawImage(prevRender(hm,200,200,1.15),0,0,400,400)}catch(e){}
  $('#hUp').onclick=()=>{if(S.gold<c||L>=max)return;S.gold-=c;S.hero.lvl++;snd('build');addXP(15);toast('الفارس صار مستوى '+S.hero.lvl);
    const st=S.b.find(b=>b.t==='stable');if(st){st._pop=performance.now()/1000;confettiAt(st.x+1,st.y+1)}hud();heroSheet();save()}}

/* --- quests & daily --- */
function questSheet(){const list=QUESTS.filter(q=>!S.claimed.includes(q.id)).slice(0,6);
  const rows=list.map(q=>{const v=Math.min(q.n,q.v());const ok=v>=q.n;return `<div class="row"><div class="ri">${art(ok?'gift':'scroll')}</div><div class="rt"><b>${q.t}</b><div class="bar"><i style="width:${v/q.n*100}%"></i></div><small>${fmt(v)} / ${fmt(q.n)}</small></div><button class="btn ${ok?'g':''} sm" data-q="${q.id}" ${ok?'':'disabled'}>${q.gems}${art('gem')}</button></div>`}).join('');
  openSheet('المهام',`<div class="row lvlrow"><div class="ri">${art('star')}</div><div class="rt"><b>مستواك ${S.plv}</b><div class="bar"><i style="width:${S.xp/xpNeed(S.plv)*100}%"></i></div><small>${S.xp} / ${xpNeed(S.plv)} خبرة · كل مستوى جديد يعطيك 5 جواهر</small></div></div>${rows||'<p class="note">خلّصت كل المهام!</p>'}`);
  $('#sheetBody').querySelectorAll('[data-q]').forEach(e=>e.onclick=()=>{const q=QUESTS.find(x=>x.id===e.dataset.q);if(!q||q.v()<q.n)return;S.claimed.push(q.id);S.gems+=q.gems;
    const r=e.getBoundingClientRect(),ar=$('#app').getBoundingClientRect();coinFly(r.left-ar.left+r.width/2,r.top-ar.top,'gem',q.gems);snd('win');addXP(15);hud();questSheet();save()})}
const dayKey=d=>{d=d||new Date();return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()};
const dailyAvail=()=>S.daily.day!==dayKey();
function dailyModal(){const av=dailyAvail();const y=new Date();y.setDate(y.getDate()-1);let st=S.daily.streak;if(av&&S.daily.day!==dayKey(y))st=0;const today=av?st%7:(st-1+7)%7;
  const lab=d=>[d.g?art('coin')+fmt(d.g):'',d.w?art('drop')+fmt(d.w):'',d.gems?art('gem')+d.gems:''].filter(Boolean).join(' ');
  openModal(`<div class="mhead"><h3>هدية اليوم</h3></div><p>${av?'ارجع كل يوم وكبّر هديتك. اليوم السابع فيه صندوق كبير.':'استلمت هدية اليوم. نشوفك بكرة!'}</p>
    <div class="daily">${DAILY.map((d,k)=>`<div class="${k<today||(!av&&k===today)?'got':''} ${av&&k===today?'today':''}"><span>يوم ${k+1}</span><span>${lab(d)}</span></div>`).join('')}</div>
    <div class="mb">${av?'<button class="btn g" id="dOk">استلم</button>':''}<button class="btn y" id="dX">إغلاق</button></div>`);
  $('#dX').onclick=closeModal;const ok=$('#dOk');if(ok)ok.onclick=()=>{const d=DAILY[today];if(d.g)S.gold=Math.min(capG(),S.gold+d.g);if(d.w)S.water=Math.min(capW(),S.water+d.w);if(d.gems)S.gems+=d.gems;
    S.daily={day:dayKey(),streak:st+1};snd('win');const r=ok.getBoundingClientRect(),ar=$('#app').getBoundingClientRect();coinFly(r.left-ar.left+r.width/2,r.top-ar.top,d.gems?'gem':d.g?'coin':'drop',8);
    closeModal();addXP(10);hud();save()}}

/* --- campaign --- */
function campSheet(){const st=S.camp.stars;const tot=st.reduce((a,b)=>a+(b||0),0);
  const rows=CAMP.map((c,i)=>{const s=st[i]||0;const open=i===0||(st[i-1]||0)>0;
    return `<div class="crow ${open?'':'lock'} ${s===3?'full':''}"><div class="cnum">${i+1}</div><div class="rt"><b>${esc(c.n)}</b><small>${art('castle')} مستوى ${c.L} · ${art('coin')}${fmt(c.g)} · ${art('drop')}${fmt(c.w)}</small><div class="cst">${[0,1,2].map(k=>`<span class="${k<s?'':'off'}">${art('star')}</span>`).join('')}</div></div>${open?`<button class="btn ${s?'y':'g'} sm" data-c="${i}">${s?'أعد':'العب'}</button>`:`<span class="lk">${art('lock')}</span>`}</div>`}).join('');
  openSheet('حملة النفود',`<div class="row"><div class="ri">${art('map')}</div><div class="rt"><b>${tot} / ${CAMP.length*3} نجمة</b><small>كل مرحلة تفتح اللي بعدها. أول فوز يعطيك 5 جواهر، وأول 3 نجوم تعطيك 10 زيادة.</small></div></div><div class="camp">${rows}</div>`);
  $('#sheetBody').querySelectorAll('[data-c]').forEach(e=>e.onclick=()=>startCampaign(+e.dataset.c))}
function startCampaign(i){const c=CAMP[i];const orig=Math.random;let s=c.seed;
  Math.random=()=>{s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};
  try{startScout('base',{L:c.L,name:c.n,camp:i,g:c.g,w:c.w})}finally{Math.random=orig}}

/* --- raids (defend your castle) --- */
function startDefense(){closeSheet();closeModal();selB=null;selO=null;showSel();S.raid.pend=0;S.raid.next=now()+ri(300,420)*1000;const L=cl();
  BB={kind:'defense',L,name:pick(ENEMY_NAMES),bld:S.b.filter(b=>b.lvl>=1&&!b.buried).map(b=>({t:b.t,x:b.x,y:b.y,lvl:b.lvl,hp:BT[b.t].hp[b.lvl-1],maxhp:BT[b.t].hp[b.lvl-1],cd:rnd(0,1)})),
    units:[],raiders:[],en:[],proj:[],time:100,clock:0,started:true,ended:false,left:{},init:{},sel:'h',revealUntil:Infinity,gotG:0,gotW:0,stars:0,pct:0,dep:0,destroyedCastle:false,
    waves:makeWaves(L),spells:[],sp:{...S.spells},spInit:{...S.spells},heroOut:false,nakhwa:false};
  BB.total=BB.bld.filter(b=>b.t!=='wall'&&b.t!=='trap').length;computeBlocked();
  mode='battle';$('#vhud').hidden=true;$('#bhud').classList.add('on');renderBattleHud();centerOn(N/2,N/2,.82);clampCam();bigText('دافع عن قلعتك!');snd('bad');save()}
function makeWaves(L){const n=3+L*2;const sides=[0,1,2,3].sort(()=>Math.random()-.5);
  return [[2,'wa'],[16,'wwa'],[32,'wackg']].map(([at,mix],i)=>{const list=[];for(let k=0;k<n+i*2;k++){let t=mix[ri(0,mix.length-1)];if(t==='c'&&L<2)t='w';if(t==='k'&&L<3)t='a';if(t==='g'&&L<4)t='w';list.push(t)}return {at,side:sides[i],list,done:false}})}
function spawnWave(w,i){const B=BB;const m=1+.15*(B.L-1);
  w.list.forEach(t=>{const a=rnd(3,N-3),off=rnd(1.2,2.8);const [x,y]=w.side===0?[a,-off]:w.side===1?[N+off,a]:w.side===2?[a,N+off]:[-off,a];const T=TR[t];
    B.raiders.push({t,x,y,hp:T.hp*m,maxhp:T.hp*m,dmg:T.dmg*(1+.12*(B.L-1)),cd:rnd(0,1),walk:0,moving:false,raider:1});fx.push({k:'puff',gx:x,gy:y,t:0,dur:.4})});
  bigText(['الموجة الأولى!','الموجة الثانية!','الموجة الأخيرة!'][i]);snd('bad');updateBattleTop()}
function autoRaid(){S.raid.pend=0;S.raid.next=now()+ri(300,420)*1000;
  const def=S.b.filter(b=>(b.t==='archer'||b.t==='catapult')&&!b.buried).reduce((s,b)=>s+b.lvl,0);const r=Math.max(.04,.2-def*.02);
  const lg=Math.floor(S.gold*r),lw=Math.floor(S.water*r);S.gold-=lg;S.water-=lw;{const rt=ri(4,8);S.tro=Math.max(0,S.tro-rt);olEv('raid',-rt)}
  openModal(`<div class="mhead lose"><h3>الغزاة دخلوا!</h3></div><p>ما دافعت بنفسك، فدفاعاتك واجهتهم لحالها ونهبوا:</p><div class="loot"><span>${art('coin')}<bdi>-${fmt(lg)}</bdi></span><span>${art('drop')}<bdi>-${fmt(lw)}</bdi></span></div><p class="note">المرة الجاية اضغط "دافع" لما يجيك التنبيه، وانزل بالفارس والتعاويذ.</p><div class="mb"><button class="btn g" id="oOk">طيب</button></div>`);
  $('#oOk').onclick=closeModal;hud();save()}

/* --- battle: units, spells, hero --- */
function stepAttacker(u,dt){const B=BB;const T=TR[u.t];if(T.heal){stepHealer(u,dt);return}const rg=(u.rage||0)>B.clock;
  if(!u.tgt||u.tgt.dead||u.tgt.escaped)u.tgt=pickTarget(u);
  const tg=u.tgt;if(!tg){u.moving=false;return}
  let px,py;if(B.kind==='caravan'){px=tg.x;py=tg.y}else{[px,py]=nearestPt(tg,u.x,u.y)}
  const d=Math.hypot(px-u.x,py-u.y);const sp=T.speed*(rg?1.5:1)*((u.slow||0)>B.clock?.5:1);
  if(d>T.range){const st=Math.min(d-T.range*.9,sp*dt);const nx=u.x+(px-u.x)/d*st,ny=u.y+(py-u.y)/d*st;
    if(B.kind!=='caravan'&&tg.t!=='wall'){const w=wallAt(nx,ny);if(w&&!(nx>=tg.x&&ny>=tg.y&&nx<tg.x+BT[tg.t].s&&ny<tg.y+BT[tg.t].s)){u.tgt=w;u.moving=false;return}}
    u.x=nx;u.y=ny;u.moving=true;u.walk+=dt*(rg?1.4:1)}
  else{u.moving=false;u.cd-=dt*(rg?1.4:1);if(u.cd<=0){u.cd=u.t==='h'?.8:1;const dm=(u.dmg||T.dmg)*(rg?1.6:1);
    if(TR[u.t].range>=2){B.proj.push({k:'arrow',x:u.x,y:u.y,tgt:tg,tx:px,ty:py,t:0,dur:.3,dmg:dm*(u.snipe>0?(u.snipe--,4):1)});snd('shot')}
    else if(u.t==='k'){B.bld.forEach(b=>{if(b.dead)return;const [qx,qy]=nearestPt(b,px,py);if(Math.hypot(qx-px,qy-py)<1.3)damageB(b,b.t==='wall'?dm*12:dm)});fx.push({k:'boom',gx:u.x,gy:u.y,t:0,dur:.6,r:1.3});snd('boom');u.dead=true}
    else{B.kind==='caravan'?damageE(tg,dm):damageB(tg,dm);fx.push({k:'hit',gx:px,gy:py,t:0,dur:.25})}}}}
function stepHeroDef(u,dt){const B=BB;const T=TR.h;const rg=(u.rage||0)>B.clock;let tg=u.tgt;
  if(!tg||tg.dead){tg=null;let bd=1e9;B.raiders.forEach(r=>{if(r.dead)return;const d=Math.hypot(r.x-u.x,r.y-u.y);if(d<bd){bd=d;tg=r}});u.tgt=tg}
  if(!tg){u.moving=false;return}
  const d=Math.hypot(tg.x-u.x,tg.y-u.y);
  if(d>T.range){const st=Math.min(d-T.range*.9,T.speed*(rg?1.5:1)*dt);u.x+=(tg.x-u.x)/d*st;u.y+=(tg.y-u.y)/d*st;u.moving=true;u.walk+=dt}
  else{u.moving=false;u.cd-=dt*(rg?1.4:1);if(u.cd<=0){u.cd=.8;damageU(tg,u.dmg*(rg?1.6:1));fx.push({k:'hit',gx:tg.x,gy:tg.y,t:0,dur:.25});if(tg.dead){B.gotG+=20*B.L;fx.push({k:'txt',gx:tg.x,gy:tg.y,s:'+'+20*B.L,col:'#ffcb2b',t:0,dur:1})}}}}
function spellTick(dt){const B=BB;const def=B.kind==='defense';
  B.spells.forEach(s=>{s.t+=dt;s.acc=(s.acc||0)+dt;const P_=SPL[s.k];
    while(s.acc>=.5){s.acc-=.5;
      if(s.k==='storm'){
        if(def)B.raiders.forEach(u=>{if(!u.dead&&Math.hypot(u.x-s.x,u.y-s.y)<P_.r){damageU(u,P_.dmg);u.slow=B.clock+1}});
        else if(B.kind==='caravan')B.en.forEach(e=>{if(!e.dead&&!e.escaped&&Math.hypot(e.x-s.x,e.y-s.y)<P_.r)damageE(e,P_.dmg)});
        else B.bld.forEach(b=>{if(b.dead||b.t==='trap')return;const [qx,qy]=nearestPt(b,s.x,s.y);if(Math.hypot(qx-s.x,qy-s.y)<P_.r){damageB(b,b.t==='wall'?P_.dmg*.5:P_.dmg);b.stun=B.clock+4}});
        shake(.1)}
      else B.units.forEach(u=>{if(!u.dead&&Math.hypot(u.x-s.x,u.y-s.y)<P_.r&&u.hp<u.maxhp){u.hp=Math.min(u.maxhp,u.hp+P_.heal);if(Math.random()<.35)fx.push({k:'txt',gx:u.x,gy:u.y,s:'+'+P_.heal,col:'#7dff8a',t:0,dur:.8})}})}});
  B.spells=B.spells.filter(s=>s.t<SPL[s.k].dur)}
function nakhwa(){const B=BB;if(!B||B.nakhwa)return;const h=B.units.find(u=>u.t==='h'&&!u.dead);if(!h)return;B.nakhwa=true;
  h.hp=Math.min(h.maxhp,h.hp+h.maxhp*.4);B.units.forEach(u=>{if(!u.dead&&Math.hypot(u.x-h.x,u.y-h.y)<4.5)u.rage=B.clock+8});
  fx.push({k:'ring',gx:h.x,gy:h.y,t:0,dur:.6});bigText('النخوة!');snd('win');shake(.22);stat('nakhwa');renderBattleHud()}
function spellMesh(k){const g=new THREE.Group();const r=SPL[k].r;const st=k==='storm';
  const ring=add(g,new THREE.RingGeometry(r-.12,r,48),new THREE.MeshBasicMaterial({color:st?'#ffcf7a':'#7dffb0',transparent:true,opacity:.85,side:THREE.DoubleSide,depthWrite:false}),0,.05,0);ring.rotation.x=-Math.PI/2;ring.userData.ns=1;
  const dome=add(g,new THREE.CylinderGeometry(r*.92,r,st?2.6:2.1,24,1,true),new THREE.MeshBasicMaterial({color:st?'#e8b26a':'#8fd8ff',transparent:true,opacity:.2,side:THREE.DoubleSide,depthWrite:false}),0,st?1.3:1.05,0);dome.userData.ns=1;
  if(!st){const cl=new THREE.Group();cl.position.y=2.7;g.add(cl);[[0,0,.8],[.75,.1,.6],[-.75,0,.65],[.3,.3,.55],[-.3,-.3,.55]].forEach(([x,z,s])=>add(cl,new THREE.SphereGeometry(s,12,8),M('#f4fbff',{flatShading:false}),x,0,z))}
  g.userData.spin=dome;return g}

/* ================= INPUT ================= */
const ptrs=new Map();let drag=null,pinch=null,holdT=null,tapMoved=false;
function rel(e){const r=cv.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top]}
(()=>{})('pointerdown',e=>{cv.setPointerCapture(e.pointerId);const [px,py]=rel(e);ptrs.set(e.pointerId,{x:px,y:py});
  if(ptrs.size===2){const [a,b]=[...ptrs.values()];pinch={d:Math.hypot(a.x-b.x,a.y-b.y)||1,z:cam.z};drag=null;clearInterval(holdT);return}
  tapMoved=false;const [gx,gy]=s2w(px,py);drag={sx:px,sy:py,tx:cam.tx,tz:cam.tz,onPlace:false};
  if(mode==='village'&&place){const s=BT[place.t].s;if(gx>=place.x-.7&&gx<place.x+s+.7&&gy>=place.y-.7&&gy<place.y+s+.7){drag.onPlace=true;drag.ox=gx-place.x;drag.oy=gy-place.y}}
  if(mode==='battle'&&BB&&BB.sel){const r=deployAt(gx,gy);if(r!=='no'){const id=e.pointerId;holdT=setInterval(()=>{if(tapMoved)return;const p=ptrs.get(id);if(!p)return;const [hx,hy]=s2w(p.x,p.y);deployAt(hx+rnd(-.3,.3),hy+rnd(-.3,.3))},140)}drag.deployed=true}});
(()=>{})('pointermove',e=>{if(!ptrs.has(e.pointerId))return;const [px,py]=rel(e);ptrs.set(e.pointerId,{x:px,y:py});
  if(pinch&&ptrs.size===2){const [a,b]=[...ptrs.values()];zoomAt((a.x+b.x)/2,(a.y+b.y)/2,pinch.z*Math.hypot(a.x-b.x,a.y-b.y)/pinch.d);return}
  if(!drag)return;const dx=px-drag.sx,dy=py-drag.sy;if(Math.hypot(dx,dy)>(MOB?14:8))tapMoved=true;
  if(drag.onPlace){const [gx,gy]=s2w(px,py);place.x=Math.round(gx-drag.ox);place.y=Math.round(gy-drag.oy);return}
  if(tapMoved){const ppu=PPU*cam.z,a=dx/ppu,b=dy/(ppu*SINE);cam.tx=drag.tx-(RIGHT.x*a+FWD.x*b);cam.tz=drag.tz-(RIGHT.z*a+FWD.z*b);clampCam()}});
const endPtr=e=>{const [px,py]=rel(e);ptrs.delete(e.pointerId);clearInterval(holdT);if(ptrs.size<2)pinch=null;
  if(drag&&!tapMoved&&!drag.onPlace&&!drag.deployed)tap(px,py);if(ptrs.size===0)drag=null};

cv.addEventListener('wheel',e=>{e.preventDefault();const [px,py]=rel(e);zoomAt(px,py,cam.z*(e.deltaY<0?1.1:.9))},{passive:false});
function tap(px,py){if(mode!=='village'||place)return;let b=null,ob=null;
  {let best=null,bd=34;for(const q of S.b){if(!q._bub||frameId-q._bub.f>3)continue;const d=Math.hypot(q._bub.x-px,q._bub.y-py);if(d<bd){bd=d;best=q}}if(best&&best.stock>=1){selO=null;collect(best);selB=best;showSel();return}}
  snd('tap');
  const hits=rayAt(px,py).intersectObjects(world.children,true);for(const h of hits){let o=h.object;while(o&&!o.userData.owner)o=o.parent;if(o){const ow=o.userData.owner;if(S.b.includes(ow)){b=ow;break}if(S.obs.includes(ow)){ob=ow;break}}}
  if(!b&&!ob){const [gx,gy]=s2w(px,py);b=hitBuilding(gx,gy);if(!b)ob=S.obs.find(o=>gx>=o.x&&gx<o.x+1&&gy>=o.y&&gy<o.y+1)||null}
  if(ob){selB=null;selO=ob;showSel();return}selO=null;
  if(b&&BT[b.t].rate&&!b.buried&&!b.up&&b.stock>=1)collect(b);
  selB=b;showSel()}
$('#pOk').onclick=()=>{if(!place)return;const s=BT[place.t].s;
  if(!inGrid(place.x,place.y,s)||occupied(place.x,place.y,s,place.move)){toast('المكان مو فاضي');snd('bad');return}
  if(inDune(place.x,place.y,s)){toast('ما تقدر تبني على الرمل الزاحف');snd('bad');return}
  if(place.move){place.move.x=place.x;place.move.y=place.y;place.move.buried=false;selB=place.move;snd('build')}
  else{const d=BT[place.t];if(d.res==='g'){if(S.gold<d.cost[0])return;S.gold-=d.cost[0]}else{if(S.water<d.cost[0])return;S.water-=d.cost[0]}
    const b=mk(place.t,place.x,place.y,1);b.lvl=1;if(d.time[0]>0){const tt=Math.max(1,Math.round(d.time[0]*evBuild()));b.lvl=0;b.up={end:now()+tt*1000,dur:tt}}S.b.push(b);selB=b;snd('build');b._pop=performance.now()/1000;stat('upgrades');addXP(3);
    if(place.t==='wall'&&S.gold>=d.cost[0]&&count('wall')<LIM.wall[cl()-1]){place={t:'wall',x:place.x+1,y:place.y,move:null};findFree();hud();save();return}}
  place=null;$('#placebar').classList.remove('on');showSel();hud();save()};
$('#pNo').onclick=()=>{place=null;$('#placebar').classList.remove('on');showSel()};

