function stepHealer(u,dt){const B=BB;const T=TR[u.t];const al=B.units.filter(x=>!x.dead&&x!==u&&!TR[x.t].heal);
  let tg=null,bd=1e9;al.forEach(x=>{const d=Math.hypot(x.x-u.x,x.y-u.y)+(x.hp<x.maxhp?0:5);if(d<bd){bd=d;tg=x}});
  u.tgt=null;if(!tg){u.moving=false;return}
  const d=Math.hypot(tg.x-u.x,tg.y-u.y);
  if(d>1.3){const st=Math.min(d-1.1,T.speed*dt);u.x+=(tg.x-u.x)/d*st;u.y+=(tg.y-u.y)/d*st;u.moving=true;u.walk+=dt}else u.moving=false;
  u.cd-=dt;if(u.cd<=0){u.cd=1;const hv=T.heal*tMul('m');let n=0;
    B.units.forEach(x=>{if(!x.dead&&x.hp<x.maxhp&&Math.hypot(x.x-u.x,x.y-u.y)<2.6){x.hp=Math.min(x.maxhp,x.hp+hv);n++;if(Math.random()<.45)fx.push({k:'txt',gx:x.x,gy:x.y,s:'+'+Math.round(hv),col:'#7dff8a',t:0,dur:.7})}});
    if(n)for(let i=0;i<4;i++)P('sph','heal',u.x+rnd(-.5,.5),groundY(u.x,u.y)+.4,u.y+rnd(-.5,.5),0,1.4,0,.8,0,.09,{curve:1})}}
function souqSheet(b){const L=Math.max(1,b.lvl),r=BT.souq.trade[L-1];const amts=[500,2000,8000];
  const row=(k)=>amts.map(a=>{const have=k==='g'?S.gold:S.water;return `<button class="btn sm ${k==='g'?'':'y'}" data-sq="${k}${a}" ${have<a?'disabled':''}><bdi>${fmt(a)}</bdi>${art(k==='g'?'coin':'drop')} ← <bdi>${fmt(a*r)}</bdi>${art(k==='g'?'drop':'coin')}</button>`}).join('');
  openSheet('السوق',`<div class="row"><div class="ri">${art('coin')}</div><div class="rt"><b>سوق مستوى ${L}</b><small>كل صفقة تعطيك ${Math.round(r*100)}% من قيمتها. رقِّ السوق عشان تصير الصفقة أحسن.</small></div></div>
    <h4 class="sec">تبيع ذهب وتاخذ موية</h4><div class="trade">${row('g')}</div><h4 class="sec">تبيع موية وتاخذ ذهب</h4><div class="trade">${row('w')}</div>`);
  $('#sheetBody').querySelectorAll('[data-sq]').forEach(e=>e.onclick=()=>{const k=e.dataset.sq[0],a=+e.dataset.sq.slice(1),get=Math.floor(a*r);
    if(k==='g'){if(S.gold<a)return;if(capW()-S.water<get){toast('خزانات الموية ما تكفي');snd('bad');return}S.gold-=a;S.water+=get;snd('water')}
    else{if(S.water<a)return;if(capG()-S.gold<get){toast('خزائن الذهب ما تكفي');snd('bad');return}S.water-=a;S.gold+=get;snd('coin')}
    stat('trades');hud();souqSheet(b);save()})}

/* --- leagues, achievements, season --- */
const LG=[{n:'رمال',min:0,c:'#c9a26b',r:0},{n:'برونز',min:100,c:'#cd7f4a',r:10},{n:'فضة',min:300,c:'#c9d0d8',r:20},{n:'ذهب',min:600,c:'#ffcb2b',r:35},{n:'زمرّد',min:1000,c:'#3dba2c',r:50},{n:'ألماس',min:1600,c:'#5fd0ff',r:80},{n:'أسطورة النفود',min:2500,c:'#b06bff',r:150}];
const lgIdx=t=>{t=t==null?S.tro:t;let i=0;LG.forEach((l,k)=>{if(t>=l.min)i=k});return i};
const lgBonus=()=>1+lgIdx()*.05;
function lgIco(i){const c=LG[i].c;return `<svg class="art" viewBox="0 0 64 64" aria-hidden="true"><g stroke="${E}" stroke-width="3.6" stroke-linejoin="round"><path d="M32 4l24 9v17c0 14-10 24-24 30C18 54 8 44 8 30V13z" fill="${c}"/><path d="M32 12l15 6v12c0 9-6 16-15 20z" fill="#fff" opacity=".3" stroke="none"/><path d="M32 20l3.5 7 7.5 1-5.5 5 1.3 7.5-6.8-3.6-6.8 3.6 1.3-7.5-5.5-5 7.5-1z" fill="#fff" stroke-width="2.4"/>${i>=4?'<path d="M18 8l4-6 4 6M38 8l4-6 4 6" fill="#ffcb2b" stroke-width="2.4"/>':''}</g></svg>`}
const campStars=()=>S.camp.stars.reduce((a,b)=>a+(b||0),0);
const ACH=[
 {id:'build',n:'البنّاء',d:'ابنِ أو رقِّ مباني',k:'upgrades',t:[5,25,80]},
 {id:'win',n:'الغازي',d:'افز بمعارك',k:'wins',t:[5,25,100]},
 {id:'camel',n:'صائد القوافل',d:'انهب جمال من القوافل',k:'camels',t:[10,50,200]},
 {id:'def',n:'حامي الديار',d:'صدّ غارات على قلعتك',k:'defWins',t:[3,15,50]},
 {id:'gold',n:'تاجر الذهب',d:'جمّع ذهب من المناجم',k:'collectG',t:[5000,50000,300000]},
 {id:'train',n:'المدرّب',d:'درّب جنود',k:'trained',t:[50,300,1500]},
 {id:'stars',n:'فارس الحملة',d:'اجمع نجوم الحملة',v:campStars,t:[9,24,36]},
 {id:'tro',n:'صاحب الكؤوس',d:'اجمع كؤوس',v:()=>S.tro,t:[200,800,2000]},
 {id:'map',n:'سيد الخريطة',d:'اهزم قرى القبائل',k:'villages',t:[3,15,60]},
 {id:'oasis',n:'ابن الواحات',d:'اجمع كنوز الواحات',k:'oasis',t:[5,30,100]}];
const ACHR=[5,15,40],TIERN=['برونزي','فضي','ذهبي'];
const achV=a=>a.v?a.v():(S.st[a.k]||0);
const achCan=a=>{const c=S.ach[a.id]||0;return c<3&&achV(a)>=a.t[c]};
const seasonKey=()=>{const d=new Date();return d.getFullYear()+'-'+(d.getMonth()+1)};
const SEAS_N=15,SEAS_STEP=120;
const SEAS_PTS={collectG:.01,collectW:.01,wins:15,defWins:25,camels:4,upgrades:6,trained:1,spells:2,nakhwa:3,obs:3,villages:10,oasis:5,trades:2};
function seasonCheck(){if(!S.season||S.season.id!==seasonKey())S.season={id:seasonKey(),pts:0,got:[]}}
function seasonRew(i){if(i===SEAS_N-1)return {gems:60};if(i%3===2)return {gems:5+i};const a=400*cl()+i*150;return i%3===0?{g:a}:{w:a}}
const rewLab=r=>[r.g?art('coin')+'<bdi>'+fmt(r.g)+'</bdi>':'',r.w?art('drop')+'<bdi>'+fmt(r.w)+'</bdi>':'',r.gems?art('gem')+r.gems:''].filter(Boolean).join(' ');
const seasonDays=()=>{const d=new Date();return Math.ceil((new Date(d.getFullYear(),d.getMonth()+1,1)-d)/86400000)};
const _stat0=stat;
stat=function(k,n){_stat0(k,n);const p=SEAS_PTS[k];if(p&&S.season){seasonCheck();S.season.pts+=p*(n==null?1:n)}};
function progClaimable(){const mx=Math.max(S.lg.max||0,lgIdx());if(LG.some((l,k)=>l.r&&k<=mx&&!S.lg.got.includes(k)))return true;if(ACH.some(achCan))return true;
  const tier=Math.floor((S.season?S.season.pts:0)/SEAS_STEP);for(let i=0;i<Math.min(SEAS_N,tier);i++)if(!S.season.got.includes(i))return true;return false}
let progTab='league';
function progSheet(){seasonCheck();S.lg.max=Math.max(S.lg.max||0,lgIdx());
  const tabs=[['league','الدوري'],['ach','الإنجازات'],['season','الموسم']].map(([k,n])=>`<button data-pt="${k}" class="${progTab===k?'on':''}">${n}</button>`).join('');let body='';
  if(progTab==='league'){const i=lgIdx(),cur=LG[i],nx=LG[i+1];
    body=`<div class="lg-hero">${lgIco(i)}<div class="rt"><b>دوري ${cur.n}</b><small>${S.tro} كأس${nx?' · باقي '+(nx.min-S.tro)+' لدوري '+nx.n:' · وصلت أعلى دوري!'}</small>${nx?`<div class="bar"><i style="width:${Math.max(0,Math.min(100,(S.tro-cur.min)/(nx.min-cur.min)*100))}%"></i></div>`:''}<small>بونص غنيمة الغزو: <bdi>+${Math.round((lgBonus()-1)*100)}%</bdi></small></div></div>`+
      LG.map((l,k)=>{const got=S.lg.got.includes(k),can=l.r&&k<=S.lg.max&&!got;return `<div class="row ${k===i?'cur':''}"><div class="ri">${lgIco(k)}</div><div class="rt"><b>${l.n}</b><small>${l.min} كأس فأكثر · غنيمة <bdi>+${k*5}%</bdi></small></div>${l.r?`<button class="btn sm ${can?'g':''}" data-lg="${k}" ${can?'':'disabled'}>${got?'استلمت':l.r+art('gem')}</button>`:''}</div>`}).join('')+
      `<p class="note">تكسب كؤوس لما تفوز بغزو قلعة أو كمين قافلة، وتخسر لما تنهزم أو يغزونك. مكافأة كل دوري تستلمها مرة وحدة.</p>`}
  else if(progTab==='ach'){body=ACH.map(a=>{const c=S.ach[a.id]||0,v=achV(a),nx=a.t[Math.min(2,c)],can=achCan(a);
      return `<div class="row"><div class="ri ach t${c}">${art('medal')}</div><div class="rt"><b>${a.n}${c?' · '+TIERN[c-1]:''}</b><small>${a.d}: <bdi>${fmt(Math.min(v,nx))} / ${fmt(nx)}</bdi></small><div class="bar"><i style="width:${c>=3?100:Math.min(100,v/nx*100)}%"></i></div><div class="pips">${[0,1,2].map(k=>`<span class="p${k} ${k<c?'on':''}"></span>`).join('')}</div></div>${c>=3?`<span class="done-t">${art('star')}</span>`:`<button class="btn sm ${can?'g':''}" data-ac="${a.id}" ${can?'':'disabled'}>${ACHR[c]}${art('gem')}</button>`}</div>`}).join('')}
  else{const pts=Math.floor(S.season.pts),tier=Math.floor(pts/SEAS_STEP);
    body=`<div class="lg-hero">${art('crown')}<div class="rt"><b>موسم ${new Date().toLocaleDateString('ar-SA-u-nu-latn',{month:'long'})}</b><small><bdi>${pts}</bdi> نقطة · باقي ${seasonDays()} يوم</small><div class="bar"><i style="width:${tier>=SEAS_N?100:(pts%SEAS_STEP)/SEAS_STEP*100}%"></i></div><small>تجمع نقاط من الفوز والدفاع والقوافل والبناء والجمع. كل ${SEAS_STEP} نقطة تفتح جائزة.</small></div></div>`+
      Array.from({length:SEAS_N},(_,i)=>{const r=seasonRew(i),got=S.season.got.includes(i),can=i<tier&&!got;return `<div class="row ${i===SEAS_N-1?'cur':''}"><div class="cnum">${i+1}</div><div class="rt"><b>${rewLab(r)}</b><small>${(i+1)*SEAS_STEP} نقطة</small></div><button class="btn sm ${can?'g':''}" data-se="${i}" ${can?'':'disabled'}>${got?'استلمت':can?'استلم':art('lock')}</button></div>`}).join('')}
  openSheet('التقدّم',`<div class="tabs-in">${tabs}</div>${body}`);
  const B=$('#sheetBody');
  B.querySelectorAll('[data-pt]').forEach(e=>e.onclick=()=>{progTab=e.dataset.pt;snd('tap');progSheet()});
  const gemFx=(e,n)=>{const r=e.getBoundingClientRect(),ar=$('#app').getBoundingClientRect();coinFly(r.left-ar.left+r.width/2,r.top-ar.top,'gem',n)};
  B.querySelectorAll('[data-lg]').forEach(e=>e.onclick=()=>{const k=+e.dataset.lg;if(S.lg.got.includes(k)||k>S.lg.max)return;S.lg.got.push(k);S.gems+=LG[k].r;gemFx(e,LG[k].r);snd('win');hud();progSheet();save()});
  B.querySelectorAll('[data-ac]').forEach(e=>e.onclick=()=>{const a=ACH.find(x=>x.id===e.dataset.ac);if(!a||!achCan(a))return;const c=S.ach[a.id]||0;S.ach[a.id]=c+1;S.gems+=ACHR[c];gemFx(e,ACHR[c]);snd('win');addXP(10);hud();progSheet();save()});
  B.querySelectorAll('[data-se]').forEach(e=>e.onclick=()=>{const i=+e.dataset.se;if(S.season.got.includes(i)||Math.floor(S.season.pts/SEAS_STEP)<=i)return;const r=seasonRew(i);
    if(r.g)S.gold=Math.min(capG(),S.gold+r.g);if(r.w)S.water=Math.min(capW(),S.water+r.w);if(r.gems){S.gems+=r.gems;gemFx(e,r.gems)}S.season.got.push(i);snd('win');hud();progSheet();save()})}
