let cineOn=false;
function cine(id,done){const L=STORY[id];if(!L){done&&done();return}cineOn=true;const el=CINE;let i=0,typing=null;
  el.hidden=false;el.querySelector('.c-ch').textContent=L.title||'';
  const show=()=>{const [w,tx]=L.lines[i];const c=CAST[w];el.classList.toggle('evil',w==='falcon');const por=el.querySelector('.c-por');por.innerHTML=c.svg;por.classList.remove('in');void por.offsetWidth;por.classList.add('in');
    el.querySelector('.c-nm').textContent=c.n;const t=el.querySelector('.c-tx');t.textContent='';let k=0;clearInterval(typing);
    typing=setInterval(()=>{k+=2;t.textContent=tx.slice(0,k);if(k>=tx.length){clearInterval(typing);typing=null}},30);
    el.querySelector('.c-next').textContent=i===L.lines.length-1?'يلا!':'التالي'};
  const fin=()=>{clearInterval(typing);el.hidden=true;el.onclick=null;cineOn=false;const first=!S.story.seen.includes(id);if(first)S.story.seen.push(id);
    if(L.reward&&first){S.gems+=L.reward;hud();toast('جاتك '+L.reward+' جوهرة من القبيلة!');snd('win')}save();done&&done()};
  el.onclick=e=>{if(e.target.closest('.c-skip')){fin();return}if(typing){clearInterval(typing);typing=null;el.querySelector('.c-tx').textContent=L.lines[i][1];return}i++;snd('tap');if(i>=L.lines.length)fin();else show()};
  show();snd('build')}
function playSeq(seq,go){if(!seq.length){go();return}cine(seq.shift(),()=>playSeq(seq,go))}
