/* --- enemy castle guards --- */
function addGuards(B){if(B.kind!=='base'||B.L<2)return;const c=B.bld.find(b=>b.t==='castle');if(!c)return;const n=Math.min(10,B.L+1);const pool=B.L>=4?'wwaacg':B.L>=3?'wwaac':'wwa';
  const r=B.R||Math.random;B.guardQ=[];for(let i=0;i<n;i++)B.guardQ.push(pool[Math.floor(r()*pool.length)]);B.defs=[];B.guardC=bcen(c)}
