const TORCH=[];function torches(){[[0,0],[1,1]].forEach(()=>{const l=new THREE.PointLight(0xff9a40,0,8,1.6);l.castShadow=false;scene.add(l);TORCH.push(l)})}
let _envT=0,_envK=-1,_lt=0;function gfxTick(t){lifeTick(t,Math.min(.05,t-(_lt||t)));_lt=t;if(TORCH.length){const c=(mode==='village'?castle():BB&&BB.bld.find(b=>b.t==='castle'));const on=nightK>.05&&c;TORCH.forEach((l,i)=>{l.intensity=on?nightK*(1.6+Math.sin(t*9+i*2)*.25+Math.sin(t*23+i)*.12):0;if(c){l.position.set(c.x+(i?3.2:-.2),2.2,c.y+(i?3.2:-.2))}})}if(++_envT%20===0){const k=+(.35*(1-.75*nightK)).toFixed(3);if(k!==_envK){_envK=k;Object.values(MC).forEach(m=>{if(m!==WATERM&&m!==GOLDM&&m.envMapIntensity!=null)m.envMapIntensity=k})}}WATERM.emissiveIntensity=.75+Math.sin(t*2.1)*.22;FIREM.emissiveIntensity=2.2+Math.sin(t*13)*.4;FIRE2.emissiveIntensity=2.4+Math.sin(t*17+1)*.4;GOLDM.emissiveIntensity=1+Math.sin(t*3)*.15;if(WINM)WINM.emissiveIntensity=2.2}
