const LK={sun:1.2,hemi:.62};
updateSky=function(){const p=(Date.now()/1000%DAYLEN)/DAYLEN;let i=0;while(i<SKYK.length-2&&p>SKYK[i+1][0])i++;const a=SKYK[i],b=SKYK[i+1];const f=(p-a[0])/Math.max(1e-6,b[0]-a[0]);
  const lc=k=>_c1.set(a[k]).lerp(_c2.set(b[k]),f);const lcl=k=>lc(k).convertSRGBToLinear();sun.color.copy(lc(1));sun.intensity=(a[2]+(b[2]-a[2])*f)*LK.sun;hemi.color.copy(lc(3));hemi.groundColor.copy(lc(4));hemi.intensity=(a[5]+(b[5]-a[5])*f)*LK.hemi;
  const cc=lcl(6).clone();renderer.setClearColor(cc);scene.fog.color.copy(cc);nightK=a[7]+(b[7]-a[7])*f;WINM.emissive.setRGB(1,.55,.15).multiplyScalar(nightK*.95)};
const ENVK=.35;
const CLOUDS=[],BIRDS=[];
function lifeInit(){const c=document.createElement('canvas');c.width=c.height=128;const g=c.getContext('2d');[[64,64,60],[40,70,34],[88,58,38],[62,44,30]].forEach(([x,y,r])=>{const gr=g.createRadialGradient(x,y,0,x,y,r);gr.addColorStop(0,'rgba(0,0,0,.9)');gr.addColorStop(1,'rgba(0,0,0,0)');g.fillStyle=gr;g.fillRect(0,0,128,128)});
  const tex=new THREE.CanvasTexture(c);const geo=new THREE.PlaneGeometry(1,1);geo.rotateX(-Math.PI/2);
  for(let i=0;i<0;i++){const m=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({map:tex,transparent:true,depthWrite:false,opacity:.14,color:0x302010}));m.position.set(rnd(-10,32),.06,rnd(-10,32));const sc=rnd(9,16);m.scale.set(sc,1,sc*.7);m.renderOrder=0;m.userData.ns=1;scene.add(m);CLOUDS.push(m)}
  const bm=M('#3a2a20',{flatShading:true});for(let i=0;i<7;i++){const b=new THREE.Group();const body=BX(b,.32,.08,.1,bm,0,0,0);const wl=new THREE.Group(),wr=new THREE.Group();b.add(wl,wr);BX(wl,.12,.03,.42,bm,0,0,.22);BX(wr,.12,.03,.42,bm,0,0,-.22);b.userData={wl,wr,a:rnd(0,6.28),r:rnd(9,16),h:rnd(6,9),sp:rnd(.18,.3)*(i%2?1:-1),ph:rnd(0,6)};b.scale.setScalar(1.3);scene.add(b);BIRDS.push(b)}}
function lifeTick(t,dt){const day=1-nightK;CLOUDS.forEach((m,i)=>{m.material.opacity=.14*day;m.position.x+=dt*.45;m.position.z+=dt*.25;if(m.position.x>cam.tx+30){m.position.x=cam.tx-30;m.position.z=cam.tz+rnd(-20,20)}if(m.position.z>cam.tz+30)m.position.z=cam.tz-30});
  BIRDS.forEach(b=>{const u=b.userData;b.visible=mode==='village'&&day>.4;if(!b.visible)return;u.a+=u.sp*dt;const cx=N/2,cz=N/2;b.position.set(cx+Math.cos(u.a)*u.r,u.h+Math.sin(t*.7+u.ph)*.5,cz+Math.sin(u.a)*u.r);b.rotation.y=-u.a-(u.sp>0?0:Math.PI);const f=Math.sin(t*10+u.ph)*.6;u.wl.rotation.x=f;u.wr.rotation.x=-f})}
const _rvl=renderVillage;renderVillage=function(t,dt){_rvl(t,dt);const c=castle();if(c&&!c.buried){const [x,y]=proj(c.x+1.5,TOPH.castle+.15,c.y+1.5);const e=ovEl('nm');if(e._s!==HOMEN){e._s=HOMEN;e.innerHTML='<span>'+HOMEN+'</span>'}pos2(e,x,y)}};
