/* ================= v0.7: true 3D camera, sky, decorations, weather ================= */
/* --- perspective orbit camera --- */
cam.yaw=Math.PI/4;cam.pitch=.74;
const PMIN=.38,PMAX=1.25;
updateCamera=function(){const fov=camera.fov*Math.PI/180;const hh=H/2/(PPU*cam.z);const D=hh/Math.tan(fov/2)*1.08;
  const sx=(Math.random()-.5)*shakeAmt,sz=(Math.random()-.5)*shakeAmt;const cp=Math.cos(cam.pitch),sp=Math.sin(cam.pitch);
  camera.aspect=W/Math.max(1,H);camera.near=Math.max(.3,D*.05);camera.far=D+900;
  camera.position.set(cam.tx+sx+Math.sin(cam.yaw)*cp*D,sp*D,cam.tz+sz+Math.cos(cam.yaw)*cp*D);camera.lookAt(cam.tx+sx,0,cam.tz+sz);camera.updateProjectionMatrix();camera.updateMatrixWorld();
  sun.position.set(cam.tx-17,27,cam.tz-6);sun.target.position.set(cam.tx,0,cam.tz);sun.target.updateMatrixWorld();
  if(typeof SKY!=='undefined'&&SKY)SKY.position.set(camera.position.x,0,camera.position.z);CAMD=D};
let CAMD=30;
Object.assign(sun.shadow.camera,{left:-26,right:26,top:26,bottom:-26,far:120});sun.shadow.camera.updateProjectionMatrix();
function camReset(){const y0=cam.yaw,p0=cam.pitch;let k=0;const tgt=Math.round((y0-Math.PI/4)/(Math.PI*2))*Math.PI*2+Math.PI/4;
  const step=()=>{k=Math.min(1,k+.08);const e=1-Math.pow(1-k,3);cam.yaw=y0+(tgt-y0)*e;cam.pitch=p0+(.74-p0)*e;updateCamera();if(k<1)requestAnimationFrame(step)};step()}
/* gestures: rebuild pointer handlers for grab-pan, pinch zoom, twist rotate, two-finger tilt */
{const ptrs3=new Map();let g=null,pin=null,hold=null,moved=false;
  const down=e=>{e.stopImmediatePropagation();cv.setPointerCapture(e.pointerId);const [px,py]=rel(e);ptrs3.set(e.pointerId,{x:px,y:py});
    if(ptrs3.size===2){const [a,b]=[...ptrs3.values()];pin={d:Math.hypot(a.x-b.x,a.y-b.y)||1,z:cam.z,a:Math.atan2(b.y-a.y,b.x-a.x),yaw:cam.yaw,my:(a.y+b.y)/2,pitch:cam.pitch};g=null;clearInterval(hold);return}
    moved=false;const [gx,gy]=s2w(px,py);g={sx:px,sy:py,gx,gy,onPlace:false};
    if(mode==='village'&&place){const s=BT[place.t].s;if(gx>=place.x-.7&&gx<place.x+s+.7&&gy>=place.y-.7&&gy<place.y+s+.7){g.onPlace=true;g.ox=gx-place.x;g.oy=gy-place.y}}
    if(mode==='battle'&&BB&&BB.sel){const r=deployAt(gx,gy);if(r!=='no'){const id=e.pointerId;hold=setInterval(()=>{if(moved)return;const p=ptrs3.get(id);if(!p)return;const [hx,hy]=s2w(p.x,p.y);deployAt(hx+rnd(-.3,.3),hy+rnd(-.3,.3))},140)}g.deployed=true}};
  const move=e=>{e.stopImmediatePropagation();if(!ptrs3.has(e.pointerId))return;const [px,py]=rel(e);ptrs3.set(e.pointerId,{x:px,y:py});
    if(pin&&ptrs3.size===2){const [a,b]=[...ptrs3.values()];const d=Math.hypot(a.x-b.x,a.y-b.y);const ang=Math.atan2(b.y-a.y,b.x-a.x);let da=ang-pin.a;da=Math.atan2(Math.sin(da),Math.cos(da));
      cam.yaw=pin.yaw-da;cam.pitch=Math.max(PMIN,Math.min(PMAX,pin.pitch+((a.y+b.y)/2-pin.my)*.005));zoomAt((a.x+b.x)/2,(a.y+b.y)/2,pin.z*d/pin.d);camUI();return}
    if(!g)return;const dx=px-g.sx,dy=py-g.sy;if(Math.hypot(dx,dy)>(MOB?14:8))moved=true;
    if(g.onPlace){const [gx,gy]=s2w(px,py);place.x=Math.round(gx-g.ox);place.y=Math.round(gy-g.oy);return}
    if(moved){const p=s2w(px,py);cam.tx+=g.gx-p[0];cam.tz+=g.gy-p[1];clampCam()}};
  const up=e=>{e.stopImmediatePropagation();const [px,py]=rel(e);ptrs3.delete(e.pointerId);clearInterval(hold);if(ptrs3.size<2)pin=null;
    if(g&&!moved&&!g.onPlace&&!g.deployed)tap(px,py);if(ptrs3.size===0)g=null};
  cv.addEventListener('pointerdown',down,true);cv.addEventListener('pointermove',move,true);cv.addEventListener('pointerup',up,true);cv.addEventListener('pointercancel',up,true);
  addEventListener('keydown',e=>{if(mode!=='village'&&mode!=='battle'&&mode!=='scout')return;const k=e.key.toLowerCase();if(k==='q'||k==='ض'){cam.yaw+=.25;updateCamera();camUI()}else if(k==='e'||k==='ث'){cam.yaw-=.25;updateCamera();camUI()}else if(k==='r'||k==='ق'){cam.pitch=Math.min(PMAX,cam.pitch+.08);updateCamera()}else if(k==='f'||k==='ب'){cam.pitch=Math.max(PMIN,cam.pitch-.08);updateCamera()}})}
function camUI(){const n=$('#bCam .needle');if(n)n.style.transform=`rotate(${(-(cam.yaw-Math.PI/4))*180/Math.PI}deg)`}

/* --- sky dome + far landscape --- */
let SKY=null;const SKYU={top:{value:new THREE.Color()},hor:{value:new THREE.Color()},sunDir:{value:new THREE.Vector3(-17,27,-6).normalize()},sunK:{value:1}};
function buildSky(){const m=new THREE.ShaderMaterial({uniforms:SKYU,side:THREE.BackSide,depthWrite:false,fog:false,
    vertexShader:'varying vec3 vD;void main(){vD=normalize(position);gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',
    fragmentShader:'uniform vec3 top,hor,sunDir;uniform float sunK;varying vec3 vD;void main(){float h=clamp(vD.y,-.2,1.);vec3 c=mix(hor,top,pow(max(h,0.),.55));c=mix(c,hor*.85,clamp(-h*5.,0.,1.));float s=max(dot(normalize(vD),sunDir),0.);c+=vec3(1.,.82,.55)*(pow(s,400.)*6.+pow(s,12.)*.35)*sunK;gl_FragColor=linearToOutputTexel(vec4(c,1.));}'});
  SKY=new THREE.Mesh(new THREE.SphereGeometry(700,32,16),m);SKY.renderOrder=-10;SKY.frustumCulled=false;scene.add(SKY);
  const far=new THREE.Mesh(new THREE.RingGeometry(130,1400,48,1),M('#d39a56',{flatShading:false,roughness:1}));far.rotation.x=-Math.PI/2;far.position.set(N/2,-.36,N/2);far.receiveShadow=false;scene.add(far);
  const r=seedR(321);const mg=new THREE.Group();
  for(let i=0;i<34;i++){const a=i/34*Math.PI*2+r()*.15,d=210+r()*120,h=22+r()*48,w=30+r()*40;const c=new THREE.Mesh(new THREE.ConeGeometry(w,h,5+Math.floor(r()*3)),M(r()<.5?'#b57a4a':'#9a6440',{roughness:1}));c.position.set(N/2+Math.cos(a)*d,h/2-1,N/2+Math.sin(a)*d);c.rotation.y=r()*3;mg.add(c)}
  for(let i=0;i<40;i++){const a=r()*Math.PI*2,d=70+r()*80;const s=new THREE.Mesh(new THREE.SphereGeometry(1,16,8),M(r()<.5?'#dfa860':'#d09450',{flatShading:false,roughness:1}));s.scale.set(10+r()*16,2+r()*4,5+r()*8);s.rotation.y=r()*3;s.position.set(N/2+Math.cos(a)*d,-1,N/2+Math.sin(a)*d);mg.add(s)}
  scene.add(mergeStatic(mg));scene.fog.near=90;scene.fog.far=420}
const SKYT={day:new THREE.Color('#62a6e6').convertSRGBToLinear(),dusk:new THREE.Color('#5a4a8e').convertSRGBToLinear(),night:new THREE.Color('#0b1030').convertSRGBToLinear()};
function skyTick(){SKYU.hor.value.copy(scene.fog.color);const p=(Date.now()/1000%DAYLEN)/DAYLEN;const dusk=Math.max(0,1-Math.abs(p-.6)/.07)+Math.max(0,1-Math.abs(p-.94)/.06);
  SKYU.top.value.copy(SKYT.day).lerp(SKYT.dusk,Math.min(1,dusk)).lerp(SKYT.night,nightK);if(WX.type==='rain')SKYU.top.value.lerp(new THREE.Color(.18,.2,.24),.6);if(WX.type==='storm')SKYU.top.value.lerp(new THREE.Color(.6,.38,.18),.8);
  SKYU.sunK.value=(1-nightK)*(WX.type==='clear'?1:.15)}

