  if(mode==='village'&&WX.type==='clear'){if(!WX.next)WX.next=n+ri(120,240)*1000;if(n>WX.next){WX.next=n+ri(300,540)*1000;const r=Math.random();if(r<.35)wxStart('rain',ri(70,110));else if(r<.5)wxStart('storm',ri(45,70))}}
