const _hs9=heroSheet;heroSheet=function(){_hs9();const body=$('#sheetBody');const rows=H2.map(k=>{const T=TR[k],L=S.tlv[k]||1,c=h2Cost(k),max=Math.min(16,cl()*2);const un=S.h2[k];const lockC=cl()<H2U[k];
    return `<div class="row"><div class="ri" style="font-size:44px">${art('v_'+k)}</div><div class="rt"><b>${T.n}${un?' · مستوى '+L:''}</b><small>${T.d}</small>${un?`<small>صحة ${Math.round(T.hp*tMul(k))} · ضرر ${Math.round(T.dmg*tMul(k))}</small>`:''}</div>
      ${un?`<button class="btn sm" data-h2u="${k}" ${(S.gold<c||L>=max)?'disabled':''}>${L>=max?'رقِّ القلعة':fmt(c)+art('coin')}</button>`:`<button class="btn g sm" data-h2b="${k}" ${(lockC||S.gold<H2C[k])?'disabled':''}>${lockC?'قلعة '+H2U[k]:'افتح · '+fmt(H2C[k])+art('coin')}</button>`}</div>`}).join('');
  body.insertAdjacentHTML('beforeend',`<h4 class="sec">أبطال جدد</h4>${rows}`);paintArt(body);
  body.querySelectorAll('[data-h2b]').forEach(e=>e.onclick=()=>{const k=e.dataset.h2b;if(S.gold<H2C[k]||cl()<H2U[k])return;S.gold-=H2C[k];S.h2[k]=true;snd('win');toast(TR[k].n+' انضم لك!');hud();heroSheet();save()});
  body.querySelectorAll('[data-h2u]').forEach(e=>e.onclick=()=>{const k=e.dataset.h2u,c=h2Cost(k);if(S.gold<c)return;S.gold-=c;S.tlv[k]=(S.tlv[k]||1)+1;snd('build');addXP(15);hud();heroSheet();save()})};

/* --- sliding dune spell --- */
SPL.dune={n:'كثيب زاحف',cost:220,r:2.6,dmg:60,dur:2.4,d:'تدفن مباني العدو تحت الرمل: تتضرر وتوقف دفاعاتها 10 ثواني.'};
