function shrub(g,x,y,s){g.save();g.translate(x,y);g.scale(s,s);g.fillStyle='rgba(60,35,10,.2)';g.beginPath();g.ellipse(0,1,16,3,0,0,7);g.fill();g.strokeStyle='#5a4a2a';g.lineWidth=1.4;
  for(let i=0;i<9;i++){const a=-Math.PI/2+(i-4)*.28;g.beginPath();g.moveTo(0,0);g.quadraticCurveTo(Math.cos(a)*6,Math.sin(a)*8,Math.cos(a)*14,Math.sin(a)*14);g.stroke()}
  g.fillStyle='#8a9a4a';for(let i=0;i<14;i++){const a=-Math.PI/2+(i/13-.5)*2.4;g.beginPath();g.arc(Math.cos(a)*(8+i%3*3),Math.sin(a)*(8+i%3*3),2.4,0,7);g.fill()}g.restore()}
huntStart=function(){const M_=mgOpen('المقناص');const {g,w,h}=M_;const fk=S.fk;let last=performance.now(),T=25,dives=6,caught=0,gold=0,birds=[],spawn=0,fal=null,state='run',msgs=[],feath=[];
  $('#mgBot').innerHTML='<div class="mg-hint">اضغط قدّام الحبارى عشان ينقض الصقر</div>';
  const fr=1.6+fk.lv*.12,fsp=300+fk.lv*30,S2=Math.min(1.4,w/330);const gy0=h*.56;
  const props=[];for(let i=0;i<9;i++)props.push({x:Math.random()*w,y:gy0+Math.random()*(h*.38),s:.7+Math.random()*.8,k:Math.random()<.65?'shrub':'rock'});props.sort((a,b)=>a.y-b.y);
  const cvx=M_.c;cvx.onpointerdown=e=>{if(state!=='run'||fal||dives<=0)return;const r=cvx.getBoundingClientRect();const x=e.clientX-r.left,y=e.clientY-r.top;if(y<gy0-10)return;dives--;fal={x:hx,y:hy,tx:x,ty:y-10*S2,t:0};snd('shot')};
  $('#mgX').onclick=()=>{state='done';mgClose()};let hx=w*.5,hy=h*.14,flap=0;
  const loop=tms=>{const dt=Math.min(.05,(tms-last)/1000);last=tms;const t=tms/1000;
    if(state==='run'){T-=dt;spawn-=dt;
      if(spawn<=0&&birds.length<4){spawn=rnd(.8,1.8);const golden=Math.random()<.12;const dirn=Math.random()<.5?1:-1;const y=rnd(gy0+20,h*.9);birds.push({x:dirn>0?-50:w+50,y,v:(rnd(60,110)+(golden?45:0))*dirn,golden,ph:0,run:1,stop:0})}
      birds.forEach(b=>{if(b.stop>0){b.stop-=dt;b.run=Math.max(0,b.run-dt*4)}else{b.run=Math.min(1,b.run+dt*3);if(Math.random()<dt*.35)b.stop=rnd(.4,1);if(Math.random()<dt*.4)b.v*=-1}b.x+=b.v*dt*b.run;b.ph+=dt*Math.abs(b.v)*.16*b.run});
      birds=birds.filter(b=>b.x>-80&&b.x<w+80&&!b.got);
      if(fal){fal.t+=dt;const d=Math.hypot(fal.tx-fal.x,fal.ty-fal.y);const st=fsp*dt*(1+fal.t*1.2);fal.ang=Math.atan2(fal.ty-fal.y,fal.tx-fal.x);if(d<=st){fal.x=fal.tx;fal.y=fal.ty;
          const hit=birds.find(b=>Math.hypot(b.x-fal.x,(b.y-30*S2)-fal.y)<26*fr*S2);
          if(hit){hit.got=true;caught++;const v=hit.golden?{gems:3,g:600*cl()}:{g:350*cl()};gold+=v.g;if(v.gems){S.gems+=v.gems;msgs.push({x:fal.x,y:fal.y,s:'+3 جواهر!',t:0})}msgs.push({x:fal.x,y:fal.y-24,s:'صيدة! +'+fmt(v.g),t:0});snd('win');for(let i=0;i<14;i++)feath.push({x:fal.x,y:fal.y,vx:rnd(-80,80),vy:rnd(-90,-20),r:rnd(0,6),t:0,c:hit.golden?'#f0d070':'#d8c4a0'})}
          else{msgs.push({x:fal.x,y:fal.y,s:'فاتت!',t:0});snd('bad')}hx=fal.x;hy=fal.y;fal=null;state==='run'&&(hx=hx)}
        else{fal.x+=(fal.tx-fal.x)/d*st;fal.y+=(fal.ty-fal.y)/d*st}}
      else{const tx=w*.5+Math.cos(t*.7)*w*.28,ty=h*.15+Math.sin(t*1.1)*h*.04;hx+=(tx-hx)*Math.min(1,dt*1.5);hy+=(ty-hy)*Math.min(1,dt*1.5)}
      if(T<=0||(dives<=0&&!fal)){state='done';setTimeout(()=>huntEnd(caught,gold),800)}}
    desertBg(g,w,h,t,t*20);const gg=g.createLinearGradient(0,gy0-10,0,h);gg.addColorStop(0,'#e2b070');gg.addColorStop(1,'#c89050');g.fillStyle=gg;g.fillRect(0,gy0-10,w,h);
    g.strokeStyle='rgba(255,236,190,.35)';g.lineWidth=2;for(let i=0;i<7;i++){const y=gy0+i*h*.06;g.beginPath();for(let x=0;x<=w;x+=16)g.lineTo(x,y+Math.sin(x*.03+i)*3);g.stroke()}
    const draw=[];props.forEach(p=>draw.push({y:p.y,f:()=>{if(p.k==='shrub')shrub(g,p.x,p.y,p.s*S2);else{g.fillStyle='#a8927a';g.strokeStyle='#5a4430';g.beginPath();g.ellipse(p.x,p.y-4*p.s,9*p.s*S2,6*p.s*S2,0,0,7);g.fill();g.stroke()}}}));
    birds.forEach(b=>draw.push({y:b.y,f:()=>drawHoubara2(g,b.x,b.y,.95*S2,b.ph,b.run,b.golden,b.v)}));draw.sort((a,b)=>a.y-b.y).forEach(d=>d.f());
    flap+=dt*(fal?3:9);const fx_=fal?fal.x:hx,fy=fal?fal.y:hy;
    if(fal){const sh=Math.max(0,1-(fal.ty-fal.y)/(h*.6));g.fillStyle=`rgba(60,35,10,${.25*sh})`;g.beginPath();g.ellipse(fal.tx,fal.ty+28*S2,18*sh*S2,5*sh*S2,0,0,7);g.fill()}
    drawFalcon2(g,fx_,fy,1.25*S2,flap,fal?Math.min(1,fal.t*3):0,fal?fal.ang:Math.sin(t*.7)*.15+(Math.cos(t*.7)<0?Math.PI:0));
    feath.forEach(f=>{f.t+=dt;f.x+=f.vx*dt;f.y+=f.vy*dt;f.vy+=120*dt;f.r+=dt*5;g.save();g.translate(f.x,f.y);g.rotate(f.r);g.globalAlpha=Math.max(0,1-f.t/1.2);g.fillStyle=f.c;g.beginPath();g.ellipse(0,0,4,1.4,0,0,7);g.fill();g.restore()});g.globalAlpha=1;feath=feath.filter(f=>f.t<1.2);
    msgs.forEach(m=>{m.t+=dt;g.globalAlpha=Math.max(0,1-m.t);g.fillStyle='#fff';g.strokeStyle='#3a2410';g.lineWidth=5;g.font='bold 20px Lalezar,sans-serif';g.textAlign='center';g.strokeText(m.s,m.x,m.y-m.t*30);g.fillText(m.s,m.x,m.y-m.t*30);g.globalAlpha=1});msgs=msgs.filter(m=>m.t<1);
    $('#mgInfo').textContent=`⏱ ${Math.max(0,Math.ceil(T))} · انقضاضات ${dives} · صيد ${caught}`;
    MGR=requestAnimationFrame(loop)};MGR=requestAnimationFrame(loop)};
