falconMesh=function(folded){const g=new THREE.Group();const BR=SM('#7a5a3a'),DK=SM('#3a2818'),CR=SM('#ecdcb8');
  const b=SP(g,.12,BR,0,.16,0,12);b.scale.set(1.7,.95,.95);const ch=SP(g,.095,CR,.05,.13,0,10);ch.scale.set(1.25,.8,.85);
  const h=new THREE.Group();h.position.set(.2,.24,0);g.add(h);g.userData.head=h;SP(h,.075,SM('#d9c4a0'),0,0,0,12);
  const cap=add(h,new THREE.SphereGeometry(.079,12,6,0,Math.PI*2,0,Math.PI/2.2),SM('#4a3424'),0,.004,0);cap.rotation.z=-.3;
  [-1,1].forEach(sg=>{const m=SP(h,.03,SM('#2a1e14'),.035,-.03,.05*sg,6);m.scale.set(.6,1.3,.5);SP(h,.016,M('#120a04'),.05,.015,.052*sg,6);SP(h,.02,M('#ffd23a'),.048,.015,.05*sg,6).scale.set(.5,.5,.3)});
  const ce=CO(h,.026,.05,'#ffd23a',.09,-.02,0,6);ce.rotation.z=-Math.PI/2;const bk=CO(h,.022,.05,'#2a2a30',.125,-.03,0,6);bk.rotation.z=-Math.PI/2-.5;
  const wingGeo=(primary)=>{const s=new THREE.Shape();if(!primary){s.moveTo(.06,0);s.bezierCurveTo(.08,.1,.06,.2,.02,.26);s.lineTo(-.12,.24);s.bezierCurveTo(-.13,.14,-.1,.06,-.08,0);s.closePath()}
    else{s.moveTo(.02,.24);s.lineTo(-.06,.5);for(let i=0;i<5;i++){s.lineTo(-.08-i*.022,.47-i*.035);s.lineTo(-.095-i*.022,.43-i*.035)}s.lineTo(-.13,.24);s.closePath()}
    const ge=new THREE.ShapeGeometry(s);ge.rotateX(Math.PI/2);return ge};
  const wings=[];[1,-1].forEach(sg=>{const wg=new THREE.Group();wg.position.set(.02,.2,.05*sg);wg.scale.z=sg;g.add(wg);
    const a=new THREE.Mesh(wingGeo(false),M('#8a6844',{side:THREE.DoubleSide,flatShading:false}));const p=new THREE.Mesh(wingGeo(true),M('#3a2818',{side:THREE.DoubleSide,flatShading:false}));wg.add(a,p);
    if(folded){wg.rotation.x=sg*1.35;wg.rotation.y=sg*.5;wg.position.y=.17}wings.push(wg)});g.userData.wings=wings;
  const tl=new THREE.Shape();tl.moveTo(-.12,-.04);tl.lineTo(-.34,-.07);tl.quadraticCurveTo(-.37,0,-.34,.07);tl.lineTo(-.12,.04);tl.closePath();const tg=new THREE.ShapeGeometry(tl);tg.rotateX(Math.PI/2);
  const tail=new THREE.Mesh(tg,M('#6e5034',{side:THREE.DoubleSide}));tail.position.y=folded?.12:.17;if(folded)tail.rotation.z=.5;g.add(tail);
  if(folded){[-1,1].forEach(sg=>{CY(g,.012,.012,.08,'#ffd23a',.04,0,.04*sg,4)})}
  return g};

