/* ---- base snapshot of a real player, cleaned the same way on client and server ---- */
function vfCleanBase(snap,L){const out=[],cnt={};let castle=false;
  (snap||[]).forEach(a=>{if(!Array.isArray(a))return;let [t,x,y,l]=a;const d=BT[t];if(!d||d.decor||!d.hp)return;x=x|0;y=y|0;l=Math.max(1,Math.min(MAXL,l|0,t==='castle'?L:L));
    if(t==='castle'){if(castle)return;castle=true;l=L}else{const lim=LIM[t];const mx=lim?lim[Math.min(lim.length,L)-1]:(t==='stable'?1:0);cnt[t]=(cnt[t]||0)+1;if(cnt[t]>mx)return}
    if(!inGrid(x,y,d.s))return;out.push([t,x,y,l])});return out}
function vfApplyBase(B,snap){const bl=[];snap.forEach(([t,x,y,l])=>{const d=BT[t];const hp=d.hp[Math.min(d.hp.length,l)-1];bl.push({t,x,y,lvl:l,hp,maxhp:hp,cd:rnd(0,1)})});
  B.bld=bl;B.guardQ=null;B.defs=null;
  const lootable=B.bld.filter(b=>['goldstore','waterstore','goldmine','well','castle'].includes(b.t));
  lootable.forEach(b=>{const w=b.t==='castle'?.15:(b.t.includes('store')?.6/Math.max(1,B.bld.filter(x=>x.t.includes('store')).length):.25/Math.max(1,B.bld.filter(x=>x.t==='goldmine'||x.t==='well').length));
    b.lg=(b.t==='waterstore'||b.t==='well')?0:B.availG*w*(b.t.includes('store')?2:1);b.lw=(b.t==='goldstore'||b.t==='goldmine')?0:B.availW*w*(b.t.includes('store')?2:1);if(b.t==='castle'){b.lg=B.availG*.15;b.lw=B.availW*.15}});
  B.total=Math.max(1,B.bld.filter(b=>b.t!=='wall'&&b.t!=='trap').length);addGuards(B);computeBlocked()}
/* ---- attacker setup, clamped to what the server-known castle level allows ---- */
function vfSetupNow(){const B=BB;const fal=S.b.find(b=>b.t==='falcon'&&!b.buried);
  return {army:{...B.init},sp:{...B.spInit},tl:{...S.tlv},hero:S.hero.lvl,h2:{...(S.h2||{})},fz:[...S.fz.list],cl:cl(),fal:fal?fal.lvl:0,gfx:S.gfx}}
function vfClampSetup(s,cmax){const c=Math.max(1,Math.min(cmax|0||1,s.cl|0||1,MAXL));const o={cl:c,army:{},sp:{},tl:{},h2:{},fz:[],fal:Math.max(0,Math.min(c,s.fal|0)),gfx:s.gfx};
  const cap=BT.barracks.house[Math.min(BT.barracks.house.length,c)-1];let used=0;
  Object.keys(TR).forEach(k=>{const n=Math.max(0,(s.army||{})[k]|0);if(!n||TR[k].hero||H2.includes(k)||k==='h')return;if((TR[k].bl||1)>c)return;const sp=TR[k].space||1;const m=Math.min(n,Math.floor((cap-used)/sp));if(m>0){o.army[k]=m;used+=m*sp}});
  H2.forEach(k=>{if((s.army||{})[k]&&c>=H2U[k])o.army[k]=1;if((s.h2||{})[k]&&c>=H2U[k])o.h2[k]=true});
  Object.keys(TR).forEach(k=>{o.tl[k]=Math.max(1,Math.min(MAXL,c+1,(s.tl||{})[k]|0||1))});
  Object.keys(SPL).forEach(k=>{o.sp[k]=Math.max(0,Math.min(3,(s.sp||{})[k]|0))});
  o.hero=Math.max(1,Math.min(16,c*2+1,s.hero|0||1));
  (s.fz||[]).slice(0,30).forEach(k=>{if(TR[k]&&!TR[k].hero&&k!=='h'&&!H2.includes(k))o.fz.push(k)});return o}
function vfLoadSetup(st){S.army={};TROOPS.forEach(k=>S.army[k]=0);Object.assign(S.army,st.army);S.spells={...st.sp};S.tlv={...S.tlv,...st.tl};S.hero.lvl=st.hero;S.h2={...st.h2};S.fz.list=[...st.fz];
  S.b=[{t:'castle',x:9,y:9,lvl:st.cl},{t:'barracks',x:3,y:3,lvl:st.cl}];if(st.fal)S.b.push({t:'falcon',x:15,y:3,lvl:st.fal});if(st.gfx)S.gfx=st.gfx}

/* ---- build the battle from a server ticket (identical on client & server) ---- */
