Promise.resolve().then(()=>{const e=$('#bEnd');if(!e||!e.onclick)return;const f=e.onclick;e.onclick=function(){const B=BB;if(B&&B.vf){if(B.vf.replay){toVillage();return}if(!B.ended)B.vf.inputs.push({k:'e',tk:B.tick})}return f.apply(this,arguments)}});
