function vfReplayEnd(B){openModal(`<div class="mhead ${B.stars?'lose':'win'}"><h3>انتهت الإعادة</h3></div><p>${esc(B.name)} · ${'⭐'.repeat(B.stars)||'ولا نجمة'} · ضرر ${Math.floor(B.pct)}%</p><div class="mb"><button class="btn g" id="rHome">رجوع للقلعة</button></div>`);$('#rHome').onclick=()=>{modalLock=false;closeModal();toVillage()}}
async function vfInbox(){if(!vfOn()||mode!=='village'||$('#modal').classList.contains('on'))return;let L_;try{L_=await rpc('nf_inbox',{p_id:S.ol.id,p_secret:S.ol.sec})}catch(e){return}
  if(!L_||!L_.items||!L_.items.length){if(L_&&typeof L_.trophies==='number'&&!(S.ol.q||[]).length){S.tro=L_.trophies;hud()}return}
  S.pvLog=S.pvLog||[];let lg=0,lw=0;L_.items.forEach(it=>{const g=it.friendly?0:Math.min(Math.floor(S.gold*.15),it.loot_g|0),w=it.friendly?0:Math.min(Math.floor(S.water*.15),it.loot_w|0);S.gold-=g;S.water-=w;lg+=g;lw+=w;it.lg=g;it.lw=w;S.pvLog.unshift(it)});S.pvLog=S.pvLog.slice(0,5);
  if(typeof L_.trophies==='number'){S.tro=L_.trophies;S.ol.tro=L_.trophies}save();hud();
  const it=L_.items[0];const n=L_.items.length;
  openModal(`<div class="mhead ${it.stars?'lose':'win'}"><h3>${n>1?n+' لاعبين هاجموك!':it.stars?'لاعب هاجم مضاربك!':'صدّيت هجوم لاعب!'}</h3></div><div class="mi">${art(it.stars?'swords':'shield')}</div>
    <p><b>${esc(it.attacker_name)}</b> ${it.friendly?`سوّى معركة ودية على قلعتك (${'⭐'.repeat(it.stars)||'ولا نجمة'} · ${it.pct}%)`:it.stars?`أخذ ${'⭐'.repeat(it.stars)} ودمّر ${it.pct}%`:`هاجمك وما قدر عليك (${it.pct}%)`}</p>
    <div class="loot"><span>${art('coin')}<bdi>-${fmt(lg)}</bdi></span><span>${art('drop')}<bdi>-${fmt(lw)}</bdi></span><span>${art('trophy')}<bdi>${L_.items.reduce((a,x)=>a+x.tr_def,0)>0?'+':''}${L_.items.reduce((a,x)=>a+x.tr_def,0)}</bdi></span></div>
    <div class="mb"><button class="btn p" id="pvRp">${art('play')} شاهد الإعادة</button><button class="btn g" id="oOk">طيب</button></div>`);
  $('#oOk').onclick=closeModal;$('#pvRp').onclick=()=>{closeModal();vfReplay(it)}}
const _log13=logSheet;logSheet=function(){_log13();const L_=S.pvLog||[];if(!L_.length)return;const box=$('#sheetBody');
  box.insertAdjacentHTML('afterbegin','<p class="note" style="margin-bottom:6px">هجمات لاعبين حقيقيين:</p>'+L_.map((r,i)=>`<div class="row"><div class="ri">${art(r.stars?'swords':'shieldr')}</div><div class="rt"><b>${esc(r.attacker_name)} · ${r.stars?'⭐'.repeat(r.stars):'صدّيته'}</b><small>ضرر ${r.pct}% · <bdi>${r.tr_def>0?'+':''}${r.tr_def}</bdi>${art('trophy')}</small></div><button class="btn p sm" data-pv="${i}">${art('play')} شاهد</button></div>`).join(''));paintArt(box);
  box.querySelectorAll('[data-pv]').forEach(b=>b.onclick=()=>{snd('tap');vfReplay(S.pvLog[+b.dataset.pv])})};
setTimeout(vfInbox,6000);setInterval(()=>{if(!document.hidden)vfInbox()},60000);

/* ================= v1.3: make online obvious ================= */
{const s=$('.side');const b=document.createElement('button');b.className='ibtn';b.id='bOnl';b.setAttribute('aria-label','أونلاين');b.style.marginTop='14px';b.style.position='relative';
  b.innerHTML='<span data-art="trophy" style="width:34px;height:34px;display:block"></span><small>أونلاين</small><i id="onlDot" style="position:absolute;top:2px;right:2px;width:12px;height:12px;border-radius:50%;border:2px solid #3a2410;background:#999"></i>';
  s.appendChild(b);paintArt(b);b.onclick=()=>{snd('tap');lbSheet()}}
function onlDot(){const d=$('#onlDot');if(!d)return;const on=S.ol&&S.ol.reg&&navigator.onLine&&!ONL.err;d.style.background=on?'#46d12c':(S.ol&&S.ol.name?'#ffb020':'#e8443a')}
setInterval(onlDot,3000);addEventListener('online',onlDot);addEventListener('offline',onlDot);
const _ons14=olNameSheet;
olNameSheet=function(after){_ons14(after);const n=$('#sheetBody .note');if(n&&!(S.ol&&S.ol.name))n.innerHTML='<b>العب أونلاين!</b><br>اختر اسمك عشان تدخل لوحة المتصدرين وتهاجم قلاع لاعبين حقيقيين، وهم يقدرون يهاجمونك بعد. النت لازم يكون شغال.'};
const _lb14=lbSheet;
lbSheet=async function(){const o=olInit();if(!o.name){olNameSheet();return}const p=_lb14();
  const add=()=>{const box=$('#sheetBody');if(!box||$('#pvGo'))return;const h=box.querySelector('.lg-hero');if(!h)return;
    h.insertAdjacentHTML('afterend',`<button class="btn r" id="pvGo" style="width:100%;margin-bottom:12px">⚔️ هاجم لاعب حقيقي · ${50*cl()}${art('coin')}</button>`);paintArt(box);
    $('#pvGo').onclick=()=>{const c=50*cl();if(S.gold<c){toast('ما عندك ذهب كفاية');snd('bad');return}if(!Object.keys(S.army).some(k=>S.army[k]>0)){toast('درّب جيش أول');snd('bad');return}S.gold-=c;snd('tap');closeSheet();startScout('base')}};
  add();await p;add();onlDot()};
Promise.resolve().then(()=>{const _mp14=$('#mPlay').onclick;if(!_mp14)return;
$('#mPlay').onclick=function(){const r=_mp14.apply(this,arguments);setTimeout(()=>{if(!(S.ol&&S.ol.name)&&!S.olAsk&&S.tut==='done'&&mode==='village'&&!$('#modal').classList.contains('on')){S.olAsk=1;save();olNameSheet()}onlDot()},1800);return r};});

/* ================= v1.3: online hub, chat, friends, friendly battles ================= */
const CH={room:'g',last:0,timer:0,items:[],title:''};
S.mute=S.mute||[];
const ago=s=>s<60?'الحين':s<3600?'قبل '+Math.floor(s/60)+' د':s<86400?'قبل '+Math.floor(s/3600)+' س':'قبل '+Math.floor(s/86400)+' يوم';
function needOnline(){if(!(S.ol&&S.ol.name)){olNameSheet(()=>onlHub());return false}if(!navigator.onLine){toast('النت مقفل');return false}return true}
function onlHub(){if(!needOnline())return;stopChat();
  openSheet('أونلاين',`<div class="lg-hero"><div class="ri">${art('trophy')}</div><div class="rt" style="flex:1"><b>${escH(S.ol.name)}</b><small id="hubSub">🏆 ${S.tro} · كود الصداقة: <b id="hubCode" style="font-family:monospace;letter-spacing:2px">${S.ol.code||'…'}</b></small></div></div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px">
      <button class="btn r" id="hAtk" style="grid-column:1/3">⚔️ هاجم لاعب حقيقي · ${50*cl()}${art('coin')}</button>
      <button class="btn y" id="hLb">🏆 المتصدرين</button><button class="btn p" id="hChat">💬 الدردشة</button>
      <button class="btn g" id="hFr" style="grid-column:1/3">👥 الأصدقاء</button></div>
    <p class="note" id="hubOn">…</p>`);
  $('#hAtk').onclick=()=>{const c=50*cl();if(S.gold<c){toast('ما عندك ذهب كفاية');snd('bad');return}if(!TROOPS.some(k=>S.army[k]>0)){toast('درّب جيش أول');snd('bad');return}S.gold-=c;snd('tap');closeSheet();startScout('base')};
  $('#hLb').onclick=()=>{snd('tap');lbSheet()};$('#hChat').onclick=()=>{snd('tap');chatSheet('g','الدردشة العامة')};$('#hFr').onclick=()=>{snd('tap');friendsSheet()};
  rpc('nf_me',{p_id:S.ol.id,p_secret:S.ol.sec}).then(m=>{S.ol.code=m.code;save();const c=$('#hubCode');if(c)c.textContent=m.code;const o=$('#hubOn');if(o)o.textContent=`المتصلين الحين: ${m.online} لاعب · شارك كود الصداقة مع ربعك عشان يضيفونك.`}).catch(()=>{const o=$('#hubOn');if(o)o.textContent='ما قدرنا نوصل للسيرفر.'})}
$('#bOnl').onclick=()=>{snd('tap');onlHub()};{const b=document.createElement('button');b.id='xOnl';b.hidden=true;b.onclick=()=>{snd('tap');onlHub()};$('.side').appendChild(b);DTILES.unshift(['onl','#xOnl','trophy','أونلاين','دردشة وأصدقاء ولاعبين'])}
/* ---- chat ---- */
function stopChat(){clearInterval(CH.timer);CH.timer=0}
function chatSheet(room,title){if(!needOnline())return;stopChat();CH.room=room;CH.last=0;CH.items=[];CH.title=title;
  openSheet(title,`<div id="chatOn" style="font-size:12px;font-weight:800;color:var(--muted);margin-bottom:6px">…</div>
    <div id="chatList" style="height:min(46vh,380px);overflow-y:auto;background:#fff6df;border:3px solid var(--edge);border-radius:14px;padding:8px;display:flex;flex-direction:column;gap:6px"></div>
    <div style="display:flex;gap:8px;margin-top:10px"><input id="chatIn" maxlength="200" placeholder="اكتب رسالة…" style="flex:1;min-width:0;font:700 16px var(--display,sans-serif);padding:10px 12px;border:3px solid var(--edge);border-radius:14px;direction:rtl">
    <button class="btn g" id="chatSend" style="flex:0 0 auto">إرسال</button></div>
    <p class="note" style="margin-top:10px">خلك محترم. اضغط على أي رسالة عشان تبلّغ عنها أو تكتم صاحبها. الكلام البذيء ينحجب تلقائياً.</p>`);
  const inp=$('#chatIn');const send=async()=>{const v=inp.value.trim();if(!v)return;inp.value='';try{await rpc('nf_chat_send',{p_id:S.ol.id,p_secret:S.ol.sec,p_room:room,p_body:v});snd('tap');chatPull()}catch(e){toast(/slow/.test(String(e))?'شوي شوي على الرسايل':'ما انرسلت');inp.value=v}};
  $('#chatSend').onclick=send;inp.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();send()}};
  chatPull();CH.timer=setInterval(()=>{if(!$('#chatList')||!$('#sheet').classList.contains('on')){stopChat();return}if(!document.hidden)chatPull()},4000)}
async function chatPull(){const room=CH.room;let r;try{r=await rpc('nf_chat_get',{p_id:S.ol.id,p_secret:S.ol.sec,p_room:room,p_after:CH.last})}catch(e){const o=$('#chatOn');if(o)o.textContent=/not friends/.test(String(e))?'ما عاد صديقك':'ما قدرنا نوصل للسيرفر';return}
  if(room!==CH.room)return;const o=$('#chatOn');if(o)o.textContent='🟢 المتصلين الحين: '+r.online;const box=$('#chatList');if(!box)return;
  const now_=Date.now()/1000;const nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<60;
  r.items.forEach(m=>{if(m.id<=CH.last)return;CH.last=Math.max(CH.last,m.id);if(S.mute.includes(m.sid))return;const d=document.createElement('div');
    d.style.cssText=`align-self:${m.me?'flex-start':'flex-end'};max-width:82%;background:${m.me?'#d9f5c2':'#fff'};border:2px solid var(--edge);border-radius:12px;padding:6px 10px;box-shadow:0 2px 0 var(--edge)`;
    d.innerHTML=`${m.me?'':`<b data-mu="${escH(m.sid)}" style="display:block;font-size:12px;color:#8a4a12;cursor:pointer">${escH(m.name)}${m.title&&typeof TITLE_N!=='undefined'&&TITLE_N[m.title]?' · '+TITLE_N[m.title]:''}</b>`}<span style="font-weight:700;font-size:15px;word-break:break-word">${escH(m.body)}</span><small style="display:block;font-size:10px;color:var(--muted);text-align:left">${ago(Math.max(0,now_-m.t))}</small>`;
    box.appendChild(d)});
  while(box.children.length>120)box.removeChild(box.firstChild);
  if(!r.items.length&&!box.children.length)box.innerHTML='<p class="note" style="margin:auto">ما فيه رسايل للحين. ابدأ السوالف!</p>';
  else{const n=box.querySelector('.note');if(n&&r.items.length)n.remove()}
  if(nearBottom||r.items.length&&CH.last===r.items[r.items.length-1].id)box.scrollTop=box.scrollHeight;
  box.querySelectorAll('[data-mu]').forEach(e=>e.onclick=()=>{const id=e.dataset.mu;if(confirmMute(e.textContent))S.mute.push(id);save();chatSheet(CH.room,CH.title)})}
function confirmMute(n){toast('كتمت '+n);return true}
/* ---- friends ---- */
async function friendsSheet(){if(!needOnline())return;stopChat();
  openSheet('الأصدقاء',`<div class="lg-hero"><div class="rt" style="flex:1"><b>كودك: <span id="frCode" style="font-family:monospace;letter-spacing:3px">${S.ol.code||'…'}</span></b><small>أرسله لربعك عشان يضيفونك</small></div><button class="btn sm y" id="frShare">مشاركة</button></div>
    <div style="display:flex;gap:8px;margin-bottom:12px"><input id="frIn" maxlength="6" placeholder="كود صديقك" style="flex:1;min-width:0;font:700 18px monospace;letter-spacing:3px;text-transform:uppercase;padding:10px 12px;border:3px solid var(--edge);border-radius:14px;text-align:center">
    <button class="btn g" id="frAdd" style="flex:0 0 auto">أضف</button></div><div id="frList"><p class="note">جاري التحميل…</p></div>`);
  $('#frShare').onclick=async()=>{const c=S.ol.code;if(!c)return;const t=`ضيفني في قلاع النفود! كودي: ${c}\nhttps://rimalith.com/nufud/`;try{if(navigator.share){await navigator.share({text:t});return}}catch(e){return}try{await navigator.clipboard.writeText(t);toast('انسخ الكود')}catch(e){toast('كودك: '+c)}};
  $('#frAdd').onclick=async()=>{const v=$('#frIn').value.trim().toUpperCase();if(v.length<6){toast('الكود 6 حروف');return}
    try{const r=await rpc('nf_friend_add',{p_id:S.ol.id,p_secret:S.ol.sec,p_code:v});snd('win');toast('صار '+r.name+' صديقك');friendsSheet()}catch(e){const m=String(e);toast(/no such/.test(m)?'ما لقينا هالكود':/self/.test(m)?'هذا كودك أنت':/too many/.test(m)?'وصلت الحد (50 صديق)':'ما قدرنا نضيفه');snd('bad')}};
  if(!S.ol.code)rpc('nf_me',{p_id:S.ol.id,p_secret:S.ol.sec}).then(m=>{S.ol.code=m.code;save();const c=$('#frCode');if(c)c.textContent=m.code}).catch(()=>{});
  let L_;try{L_=await rpc('nf_friends',{p_id:S.ol.id,p_secret:S.ol.sec})}catch(e){const b=$('#frList');if(b)b.innerHTML='<p class="note">ما قدرنا نوصل للسيرفر.</p>';return}
  const box=$('#frList');if(!box)return;
  box.innerHTML=L_.length?L_.map((f,i)=>`<div class="row" style="padding:6px 10px;margin-bottom:6px"><i style="flex:0 0 auto;width:12px;height:12px;border-radius:50%;border:2px solid var(--edge);background:${f.online?'#46d12c':'#bbb'}"></i>
      <div class="rt" style="flex:1;min-width:0"><b style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escH(f.name)}</b><small>🏆 ${f.trophies} · قلعة ${f.castle} · ${f.online?'متصل':ago(f.seen)}</small></div>
      <button class="btn sm p" data-dm="${i}">💬</button><button class="btn sm r" data-fa="${i}">⚔️</button><button class="btn sm" data-fx="${i}">✕</button></div>`).join('')+'<p class="note">⚔️ = معركة ودية على قلعة صديقك: ما فيها كؤوس ولا غنيمة، وصديقك يشوف الإعادة.</p>'
    :'<p class="note">ما عندك أصدقاء للحين. أرسل كودك لربعك أو اكتب كودهم فوق.</p>';
  box.querySelectorAll('[data-dm]').forEach(b=>b.onclick=()=>{const f=L_[+b.dataset.dm];snd('tap');chatSheet('dm:'+f.id,'💬 '+f.name)});
  box.querySelectorAll('[data-fa]').forEach(b=>b.onclick=()=>{const f=L_[+b.dataset.fa];if(!TROOPS.some(k=>S.army[k]>0)){toast('درّب جيش أول');snd('bad');return}snd('tap');friendAttack(f)});
  box.querySelectorAll('[data-fx]').forEach(b=>b.onclick=async()=>{const f=L_[+b.dataset.fx];if(b.dataset.ok!=='1'){b.dataset.ok='1';b.textContent='متأكد؟';return}try{await rpc('nf_friend_del',{p_id:S.ol.id,p_secret:S.ol.sec,p_friend:f.id});toast('انشال '+f.name);friendsSheet()}catch(e){toast('ما قدرنا')}})}
async function friendAttack(f){closeSheet();toast('نجهّز المعركة الودية…');let t;try{t=await rpc('nf_ticket_friend',{p_id:S.ol.id,p_secret:S.ol.sec,p_friend:f.id})}catch(e){toast(/no base/.test(String(e))?'قلعة صديقك ما تحدثت للحين':'ما قدرنا نوصل للسيرفر');return}
  if(mode==='map')closeMap(true);BB=null;const B=vfBuild(t,'pvp',{});if(!B)return;B.friendly=true;renderBattleHud();banner('swords','معركة ودية','قلعة '+esc(f.name)+' · بدون كؤوس ولا غنيمة')}
const _eb15=endBattle;endBattle=function(){const B=BB;if(B&&B.vf&&B.friendly&&!B.vf.replay&&!B.result){B.gotG=0;B.gotW=0}return _eb15()};

/* ================= v1.4: cloud save + recovery, chat moderation, push notifications ================= */
const FNU=ONL.u.replace('/rest/v1/rpc/','/functions/v1/');
/* ---------- cloud save ---------- */
let csLast='',csBusy=false;
function cloudPayload(){const c=JSON.parse(JSON.stringify(S));delete c.pvLog;if(c.ol){c.ol={id:c.ol.id,name:c.ol.name,code:c.ol.code}}c.last=now();return c}
async function cloudSave(force){if(!vfOn()||csBusy)return;const p=cloudPayload();const sig=JSON.stringify(p).replace(/"last":\d+/,'');if(!force&&sig===csLast)return;csBusy=true;
  try{const r=await rpc('nf_save',{p_id:S.ol.id,p_secret:S.ol.sec,p_save:p});if(r&&r.ok){csLast=sig;S.ol.cloudAt=now();S.ol.hasCode=!!r.has_code||S.ol.hasCode}}catch(e){if(/not owner/.test(String(e))){S.ol.reg=false;toast('حسابك انفتح في جهاز ثاني')}}finally{csBusy=false}}
setInterval(()=>{if(!document.hidden)cloudSave()},90000);setTimeout(()=>cloudSave(true),12000);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&vfOn()){try{const p=cloudPayload();fetch(ONL.u+'nf_save',{method:'POST',keepalive:true,headers:{apikey:ONL.k,Authorization:'Bearer '+ONL.k,'Content-Type':'application/json'},body:JSON.stringify({p_id:S.ol.id,p_secret:S.ol.sec,p_save:p})}).catch(()=>{})}catch(e){}}});
function accountSheet(){if(!needOnline())return;stopChat();const o=S.ol;
  openSheet('حسابي',`<div class="lg-hero"><div class="ri">${art('shield')}</div><div class="rt" style="flex:1"><b>${escH(o.name)}</b><small>${o.cloudAt?'✅ محفوظ في السيرفر · آخر حفظ '+ago(Math.max(0,(now()-o.cloudAt)/1000)):'⏳ جاري الحفظ في السيرفر…'}</small></div></div>
    <div class="row" style="display:block"><b style="font-family:var(--display);font-weight:400;font-size:17px">🔐 كود الاسترجاع</b><small style="display:block;color:var(--muted);font-weight:700;margin:4px 0 8px">لو ضاع جوالك أو حذفت اللعبة، هذا الكود يرجّع لك قلعتك وكؤوسك. احفظه في مكان آمن ولا تعطيه أحد.</small>
      <div id="recBox" style="font:700 22px monospace;letter-spacing:3px;text-align:center;background:#fff6df;border:3px dashed var(--edge);border-radius:12px;padding:10px;margin-bottom:8px">${o.hasCode?'•••• - •••• - ••••':'—'}</div>
      <button class="btn y" id="recNew" style="width:100%">${o.hasCode?'اطلع كود جديد (القديم يوقف)':'اطلع كود الاسترجاع'}</button></div>
    <div class="row" style="display:block"><b style="font-family:var(--display);font-weight:400;font-size:17px">↩️ استرجاع حساب</b><small style="display:block;color:var(--muted);font-weight:700;margin:4px 0 8px">عندك كود من جهاز ثاني؟ اكتبه هنا. تقدّمك في هذا الجهاز بيتبدّل بالحساب المسترجع.</small>
      <div style="display:flex;gap:8px"><input id="recIn" maxlength="14" placeholder="XXXX-XXXX-XXXX" style="flex:1;min-width:0;font:700 17px monospace;letter-spacing:2px;text-transform:uppercase;padding:10px;border:3px solid var(--edge);border-radius:14px;text-align:center"><button class="btn g" id="recGo" style="flex:0 0 auto">استرجع</button></div></div>`);
  $('#recNew').onclick=async()=>{const b=$('#recNew');if(o.hasCode&&b.dataset.ok!=='1'){b.dataset.ok='1';b.textContent='متأكد؟ الكود القديم بيوقف';return}
    try{await cloudSave(true);const r=await rpc('nf_rec_new',{p_id:o.id,p_secret:o.sec});o.hasCode=true;o.recShown=1;save();$('#recBox').textContent=r.code;snd('win');
      b.textContent='📋 انسخ / شارك الكود';b.dataset.ok='2';b.onclick=async()=>{const t='كود استرجاع قلاع النفود: '+r.code;try{if(navigator.share){await navigator.share({text:t});return}}catch(e){return}try{await navigator.clipboard.writeText(r.code);toast('انسخ الكود')}catch(e){toast(r.code)}}}catch(e){toast('ما قدرنا نوصل للسيرفر')}};
  $('#recGo').onclick=async()=>{const v=$('#recIn').value.trim();if(v.replace(/[^A-Za-z0-9]/g,'').length!==12){toast('الكود 12 حرف');return}const b=$('#recGo');if(b.dataset.ok!=='1'){b.dataset.ok='1';b.textContent='متأكد؟';return}
    try{const r=await rpc('nf_recover',{p_code:v});if(!r.save){toast('الحساب ما له حفظ في السيرفر');return}const ns=r.save;ns.ol={id:r.id,sec:r.secret,name:r.name,code:r.code,reg:true,srv:ONL.srv,q:[],sig:'',hasCode:true,recShown:1};ns.tro=r.trophies;
      S=ns;save();toast('رجع حسابك! نعيد تشغيل اللعبة…');snd('win');setTimeout(()=>location.reload(),900)}catch(e){const m=String(e);toast(/bad code/.test(m)?'الكود غلط':/slow/.test(m)?'محاولات كثيرة، جرّب بعد دقيقة':'ما قدرنا نوصل للسيرفر');snd('bad');b.dataset.ok='';b.textContent='استرجع'}}}
/* ---------- push notifications ---------- */
const pushOK=()=>'serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window;
const isIOS=/iP(hone|ad|od)/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const standalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
const b64u=s=>{const p='='.repeat((4-s.length%4)%4);const b=atob((s+p).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from([...b].map(c=>c.charCodeAt(0)))};
async function pushEnable(){if(!needOnline())return;
  if(!pushOK()){toast(isIOS&&!standalone()?'أضف اللعبة للشاشة الرئيسية أول (مشاركة ← إضافة إلى الشاشة الرئيسية)':'جهازك ما يدعم التنبيهات');return}
  try{const perm=await Notification.requestPermission();if(perm!=='granted'){toast('رفضت التنبيهات. تقدر تفعّلها من إعدادات الجوال');return}
    const reg=await navigator.serviceWorker.ready;const k=await fetch(FNU+'nf-push',{method:'POST',headers:{apikey:ONL.k,Authorization:'Bearer '+ONL.k,'Content-Type':'application/json'},body:'{"action":"key"}'}).then(r=>r.json());
    let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:b64u(k.key)});
    await rpc('nf_push_sub',{p_id:S.ol.id,p_secret:S.ol.sec,p_sub:sub.toJSON()});S.ol.push=1;save();snd('win');toast('تمام! بيجيك تنبيه إذا أحد هاجمك أو راسلك');onlHub()}
  catch(e){console.warn('push',e);toast('ما قدرنا نفعّل التنبيهات')}}
async function pushOff(){try{const reg=await navigator.serviceWorker.ready;const s=await reg.pushManager.getSubscription();if(s)await s.unsubscribe()}catch(e){}try{await rpc('nf_push_off',{p_id:S.ol.id,p_secret:S.ol.sec})}catch(e){}S.ol.push=0;save();toast('وقفت التنبيهات');onlHub()}
/* extend the hub with account + notifications */
const _hub16=onlHub;onlHub=function(){_hub16();const box=$('#sheetBody');if(!box||!$('#hFr'))return;
  const pushOn=S.ol.push&&pushOK()&&Notification.permission==='granted';
  $('#hFr').insertAdjacentHTML('afterend',`<button class="btn" id="hAcc">🔐 حسابي</button><button class="btn ${pushOn?'':'y'}" id="hPush">${pushOn?'🔕 وقّف التنبيهات':'🔔 فعّل التنبيهات'}</button>`);
  $('#hFr').style.gridColumn='1/3';$('#hAcc').onclick=()=>{snd('tap');accountSheet()};$('#hPush').onclick=()=>{snd('tap');pushOn?pushOff():pushEnable()};
  if(!S.ol.recShown){box.querySelector('.lg-hero').insertAdjacentHTML('afterend',`<div class="note" style="border-color:#e8443a;background:#ffe3dc;color:#7a1a10" id="recNag">⚠️ <b>احفظ كود الاسترجاع</b> عشان ما يضيع حسابك لو غيّرت جوالك. <u>اضغط هنا</u></div>`);$('#recNag').onclick=()=>{snd('tap');accountSheet()}}};
/* ---------- chat: report / mute / admin delete + bans ---------- */
const _cp16=chatPull;
chatPull=async function(){await _cp16();const box=$('#chatList');if(!box)return;
  box.querySelectorAll('[data-mu]').forEach(e=>{e.onclick=null;const bub=e.parentElement;if(bub.dataset.wired)return;bub.dataset.wired=1;bub.style.cursor='pointer';
    bub.onclick=ev=>{ev.stopPropagation();const ex=bub.querySelector('.chAct');if(ex){ex.remove();return}box.querySelectorAll('.chAct').forEach(x=>x.remove());
      const mid=+bub.dataset.mid;const sid=e.dataset.mu;
      bub.insertAdjacentHTML('beforeend',`<div class="chAct" style="display:flex;gap:6px;margin-top:6px"><button class="btn sm r" data-a="rep">🚩 بلاغ</button><button class="btn sm" data-a="mute">🔇 كتم</button>${CH.adm?'<button class="btn sm p" data-a="del">🗑️ حذف</button>':''}</div>`);
      bub.querySelectorAll('[data-a]').forEach(b=>b.onclick=async e2=>{e2.stopPropagation();const a=b.dataset.a;
        if(a==='mute'){S.mute.push(sid);save();toast('كتمته عندك');chatSheet(CH.room,CH.title);return}
        if(a==='rep'){try{const r=await rpc('nf_report',{p_id:S.ol.id,p_secret:S.ol.sec,p_msg:mid});toast(r.muted?'انمنع من الدردشة 24 ساعة':'وصل البلاغ، شكراً');if(!S.mute.includes(sid))S.mute.push(sid);save();chatSheet(CH.room,CH.title)}catch(er){toast(/slow/.test(String(er))?'بلاغات كثيرة اليوم':'ما وصل البلاغ')}return}
        if(a==='del'){try{await rpc('nf_mod_del',{p_id:S.ol.id,p_secret:S.ol.sec,p_msg:mid});bub.remove();toast('انحذفت')}catch(er){toast('ما انحذفت')}}})}})};
/* tag bubbles with their message id and read moderation flags (patched pull) */
const _rpc16=rpc;
rpc=async function(f,b){const r=await _rpc16(f,b);
  if(f==='nf_chat_get'&&r){CH.adm=!!r.adm;CH.ban=r.ban|0;setTimeout(()=>{const box=$('#chatList');if(!box)return;const bubs=[...box.children].filter(x=>!x.dataset.mid&&x.querySelector('small'));
      const its=(r.items||[]).filter(m=>!S.mute.includes(m.sid));bubs.slice(-its.length).forEach((d,i)=>{if(its[i])d.dataset.mid=its[i].id});
      const inp=$('#chatIn'),sb=$('#chatSend');if(CH.ban&&inp){inp.disabled=true;inp.placeholder='ممنوع من الدردشة '+CH.ban+' ساعة بسبب بلاغات';if(sb)sb.disabled=true}},0)}
  if(f==='nf_chat_send'&&b&&String(b.p_room).startsWith('dm:')){fetch(FNU+'nf-push',{method:'POST',headers:{apikey:ONL.k,Authorization:'Bearer '+ONL.k,'Content-Type':'application/json'},body:JSON.stringify({action:'dm',id:S.ol.id,secret:S.ol.sec,to:String(b.p_room).slice(3)})}).catch(()=>{})}
  return r};

/* ================= v1.6: proper 3D framing ================= */
camera.fov=30;camera.updateProjectionMatrix();
const PDEF=.86;cam.pitch=PDEF;
/* frame the actual village: centre on the buildings and zoom so they fill the screen */
function villageBox(){const bs=S.b.filter(b=>!b.buried&&BT[b.t]&&!BT[b.t].decor);if(!bs.length)return {cx:N/2,cz:N/2,w:12,h:12};
  let x0=1e9,z0=1e9,x1=-1e9,z1=-1e9;bs.forEach(b=>{const s=BT[b.t].s||1;x0=Math.min(x0,b.x);z0=Math.min(z0,b.y);x1=Math.max(x1,b.x+s);z1=Math.max(z1,b.y+s)});
  return {cx:(x0+x1)/2,cz:(z0+z1)/2,w:Math.max(10,x1-x0+3),h:Math.max(10,z1-z0+3)}}
function camFitZ(){const v=villageBox();const yaw=cam.yaw;
  const across=Math.abs(Math.cos(yaw))*v.w+Math.abs(Math.sin(yaw))*v.h, deep=Math.abs(Math.sin(yaw))*v.w+Math.abs(Math.cos(yaw))*v.h;
  const hudTop=150,hudBot=120;const zW=(W*.94)/(PPU*across);const zH=(Math.max(200,H-hudTop-hudBot))/(PPU*deep*Math.sin(cam.pitch)+PPU*2.2);
  return {v,z:Math.max(.55,Math.min(1.6,Math.min(zW,zH)*1.28))}}
function camFit(anim){const f=camFitZ();const v=f.v;const z1=f.z;const tx1=v.cx,tz1=v.cz+.6;
  if(!anim){cam.tx=tx1;cam.tz=tz1;cam.z=z1;clampCam();return}
  const a={tx:cam.tx,tz:cam.tz,z:cam.z,p:cam.pitch,y:cam.yaw};const ty=Math.round((a.y-Math.PI/4)/(Math.PI*2))*Math.PI*2+Math.PI/4;let k=0;
  const step=()=>{k=Math.min(1,k+.07);const e=1-Math.pow(1-k,3);cam.tx=a.tx+(tx1-a.tx)*e;cam.tz=a.tz+(tz1-a.tz)*e;cam.z=a.z+(z1-a.z)*e;cam.pitch=a.p+(PDEF-a.p)*e;cam.yaw=a.y+(ty-a.y)*e;updateCamera();if(k<1)requestAnimationFrame(step);else clampCam()};step()}
camReset=function(){camFit(true)};
const _cOn17=centerOn;
centerOn=function(gx,gy,z){if(mode==='village'&&gx===10.5&&gy===10.5){cam.pitch=PDEF;camFit(false);return}_cOn17(gx,gy,z)};
/* keep the camera on the village (no drifting off into empty sand) */
const _cl17=clampCam;clampCam=function(){const v=villageBox();const r=mode==='village'?Math.max(v.w,v.h)/2+4:N/2+3;
  cam.z=Math.max(.38,Math.min(2.2,cam.z));if(mode==='village'){cam.tx=Math.max(v.cx-r,Math.min(v.cx+r,cam.tx));cam.tz=Math.max(v.cz-r,Math.min(v.cz+r,cam.tz));updateCamera()}else _cl17()};
/* lighter, finer rain so the view stays clear */
const _rt17=rainTick;rainTick=function(dt){_rt17(dt);if(RAIN&&RAIN.visible){RAIN.material.opacity=.22*(GQ.wxK||0);RAIN.material.color.set('#e6f2ff');if(!RAIN.userData.thin){RAIN.userData.thin=1;RAIN.geometry.dispose();RAIN.geometry=new THREE.BoxGeometry(.012,.8,.012)}}};

