try{const q=new URLSearchParams(location.search).get('ref');if(q&&/^[A-Z0-9]{6}$/i.test(q)&&!S.refSet)S.refPending=q.toUpperCase()}catch(e){}
async function refTick(){if(!(S.ol&&S.ol.reg))return;try{if(S.refPending&&!S.refSet){await rpc('nf_ref_set',{p_id:S.ol.id,p_secret:S.ol.sec,p_code:S.refPending}).catch(()=>{});S.refSet=true;S.refPending=null;save()}
  const r=await rpc('nf_ref_claim',{p_id:S.ol.id,p_secret:S.ol.sec});const g=(r.mine|0)+(r.invites|0)*50;if(g>0){S.gems+=g;save();hud();banner('gift','هدية الدعوة',r.mine?'وصلت قلعتك مستوى 3، وجاتك 50 جوهرة لأنك دخلت بدعوة صاحبك.':'ربعك اللي دعيتهم لعبوا، وجاتك '+g+' جوهرة.')}S.refInfo=r}catch(e){}}
function refSheet(){if(!needOnline())return;const code=S.ol.code||'…';const link='https://rimalith.com/nufud/?ref='+code;
  openSheet('ادعُ ربعك',`<div class="lg-hero"><div class="ri">${art('gift')}</div><div class="rt"><b>كل صاحب يدخل بكودك = 50${art('gem')} لك و50${art('gem')} له</b><small>الجواهر تنزل لما تصير قلعة صاحبك مستوى 3 (لين 20 صاحب).</small></div></div>
    <div class="row"><div class="rt"><b>كودك: <span style="font-family:monospace;letter-spacing:2px">${code}</span></b><small>${link}</small></div><button class="btn sm g" id="rfSh">شارك</button></div>
    ${S.refSet||(S.refInfo&&S.refInfo.ref_by)?'<p class="note">دخلت بدعوة صاحب ✔</p>':`<div style="display:flex;gap:8px;margin-top:10px"><input id="rfIn" maxlength="6" placeholder="كود صاحبك" style="flex:1;min-width:0;font:700 16px monospace;padding:10px;border:3px solid var(--edge);border-radius:14px;text-transform:uppercase"><button class="btn y" id="rfGo">تم</button></div><p class="note">تقدر تدخل كود صاحبك أول 3 أيام من بدايتك.</p>`}
    <p class="note">دعيت ${S.refInfo?S.refInfo.total|0:0} صاحب لعب.</p>`);paintArt($('#sheetBody'));
  $('#rfSh').onclick=async()=>{const text='تعال العب معي قلاع النفود 🏰 وادخل بكودي '+code+' وتاخذ 50 جوهرة: '+link;try{if(navigator.share)await navigator.share({text});else{await navigator.clipboard.writeText(text);toast('انسخ الرابط')}}catch(e){}};
  const go=$('#rfGo');if(go)go.onclick=async()=>{const v=$('#rfIn').value.trim().toUpperCase();if(!/^[A-Z0-9]{6}$/.test(v)){toast('الكود 6 حروف');return}try{const r=await rpc('nf_ref_set',{p_id:S.ol.id,p_secret:S.ol.sec,p_code:v});S.refSet=true;save();toast('تم! دعوة '+(r.name||''));refSheet()}catch(e){const s=String(e);toast(/late/.test(s)?'فات وقت إدخال الكود':/already/.test(s)?'دخلت كود قبل':'الكود غلط')}}}
