let EN_OBS=null;function trNode(n,map){if(n.nodeType===3){const t=n.nodeValue.trim();if(t&&map[t])n.nodeValue=n.nodeValue.replace(t,map[t])}else if(n.nodeType===1&&!/SCRIPT|STYLE|TEXTAREA|INPUT/.test(n.tagName))n.childNodes.forEach(c=>trNode(c,map))}
function setLang(l){S.lang=l;save();document.documentElement.lang=l==='en'?'en':'ar';trNode(document.body,l==='en'?EN:ENR);if(EN_OBS){EN_OBS.disconnect();EN_OBS=null}
  if(l==='en'){EN_OBS=new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(n=>trNode(n,EN))));EN_OBS.observe(document.body,{childList:true,subtree:true})}}
